// non modificare a mano. Si carica solo quando si apre una lezione (lpi-lesson-view.js).
const LPI_LESSONS_FETCHED = "2026-11-11";
const LPI_LESSONS = [{"id":"103.1_01","objective":"103.1","title":"103.1 Lezione 1","url":"https://learning.lpi.org/it/learning-materials/101-500/103/103.1/103.1_01/","notice":"Linux Professional Institute Inc. Tutti i diritti riservati. Visita il sito Learning Materials: https://learning.lpi.org Quest'opera è sotto la licenza 'Creative Commons Attribution-NonCommercial-NoDerivatives 4.0 International License'.","body":[["h1","103.1 Lezione 1"],["table",["tr",["th",["p","Certificazione:"]],["td",["p","LPIC-1"]]],["tr",["th",["p","Versione:"]],["td",["p","5.0"]]],["tr",["th",["p","Argomento:"]],["td",["p","103 Comandi GNU e Unix"]]],["tr",["th",["p","Obiettivo:"]],["td",["p","103.1 Lavorare con la Riga di Comando"]]],["tr",["th",["p","Lezione:"]],["td",["p","1 di 2"]]]],["h2","Introduzione"],["p","I nuovi arrivati nel mondo dell’amministrazione Linux e della ",["em","shell Bash"]," spesso si sentono un po' persi senza i confort rassicuranti di un’interfaccia GUI. Sono abituati ad avere accesso con il tasto destro del mouse ai segnali visivi e alle informazioni contestuali rese disponibili dalle utility grafiche di gestione file. Quindi è importante imparare e padroneggiare rapidamente l’insieme relativamente piccolo di strumenti da riga di comando attraverso il quale è possibile attingere istantaneamente a tutti i dati disponibili."],["h3","Ottenere Informazioni di Sistema"],["p","Mentre fissi il rettangolo lampeggiante di un prompt della riga di comando, la tua prima domanda sarà probabilmente “Dove sono?” o, più precisamente, \"`Dove mi trovo nel filesystem Linux in questo momento e se, diciamo, ho creato un nuovo file, dove risiederebbe? ",["code","\" Quello che stai cercando qui è la tua ",["em","directory di lavoro attuale"],", e il comando `pwd"]," ti dirà ciò che vuoi sapere:"],["pre","$ ",["strong","pwd"],"\n/home/frank"],["p","Supponendo che Frank sia attualmente connesso al sistema e che ora si trovi nella sua home directory: ",["code","/home/frank/"],". Se Frank crea un file vuoto usando il comando ",["code","touch"]," senza specificare un’altra posizione nel filesystem, il file verrà creato in ",["code","/home/frank/"],". Attraverso il comando ",["code","ls"]," ci verrà mostrato questo nuovo file:"],["pre","$ ",["strong","touch newfile"],"\n$ ",["strong","ls"],"\nnewfile"],["p","Oltre alla tua posizione nel filesystem, spesso vorrai informazioni sul sistema Linux che stai eseguendo. Ciò potrebbe includere il numero esatto di rilascio della distribuzione o la versione del kernel Linux attualmente caricato. Lo strumento ",["code","uname"]," è ciò che cerchi. E, in particolare, ",["code","uname"]," usando l’opzione ",["code","-a"]," (“all”)."],["pre","$ ",["strong","uname -a"],"\nLinux base 4.18.0-18-generic #19~18.04.1-Ubuntu SMP Fri Apr 5 10:22:13 UTC 2019 x86_64 x86_64 x86_64 GNU/Linux"],["p",["code","uname"]," mostra che la macchina di Frank ha installato la versione del kernel Linux 4.18.0 ed esegue Ubuntu 18.04 su una CPU a 64 bit (",["code","x86_64"],")."],["h3","Ottenere Infomazioni sui Comandi"],["p","Ti imbatterai spesso in documentazione che parla di comandi Linux con i quali non hai ancora familiarità. La stessa riga di comando offre tutti i tipi di informazioni utili su che cosa facciano i comandi e su come usarli efficacemente. Forse le informazioni più utili si trovano nei numerosi file del sistema ",["code","man"],"."],["p","Di norma gli sviluppatori Linux scrivono file ",["code","man"]," e li distribuiscono insieme alle utility che creano. I file ",["code","man"]," sono documenti altamente strutturati il cui contenuto è intuitivamente diviso per titoli di sezione standard. Digitando ",["code","man"]," seguito dal nome di un comando si otterranno informazioni che includono il nome del comando, una breve sinossi di utilizzo, una descrizione più dettagliata e alcuni importanti precedenti storici e di licenza. Ecco un esempio:"],["pre","$ ",["strong","man uname"],"\nUNAME(1)             User Commands            UNAME(1)\nNAME\n   uname - print system information\nSYNOPSIS\n   uname [OPTION]...\nDESCRIPTION\n   Print certain system information.  With no OPTION, same as -s.\n   -a, --all\n      print  all information, in the following order, except omit -p\n      and -i if unknown:\n   -s, --kernel-name\n      print the kernel name\n   -n, --nodename\n      print the network node hostname\n   -r, --kernel-release\n      print the kernel release\n   -v, --kernel-version\n      print the kernel version\n   -m, --machine\n      print the machine hardware name\n   -p, --processor\n      print the processor type (non-portable)\n   -i, --hardware-platform\n      print the hardware platform (non-portable)\n   -o, --operating-system\n      print the operating system\n   --help display this help and exit\n   --version\n      output version information and exit\nAUTHOR\n   Written by David MacKenzie.\nREPORTING BUGS\n   GNU coreutils online help: <http://www.gnu.org/software/coreutils/>\n   Report uname translation bugs to\n   <http://translationproject.org/team/>\nCOPYRIGHT\n   Copyright©2017 Free Software Foundation, Inc. License  GPLv3+: GNU\n   GPL version 3 or later <http://gnu.org/licenses/gpl.html>.\n   This is free software: you are free to change and redistribute it.\n   There is NO WARRANTY, to the extent permitted by law.\nSEE ALSO\n   arch(1), uname(2)\n   Full documentation at: <http://www.gnu.org/software/coreutils/uname>\n   or available locally via: info '(coreutils) uname invocation'\nGNU coreutils 8.28       January 2018             UNAME(1)"],["p",["code","man"]," funziona solo quando gli viene fornito il nome esatto di comando. Se, tuttavia, non si è sicuri del nome del comando che si sta cercando, si può usare il comando ",["code","apropos"]," per cercare tra i nomi e le descrizioni delle pagine di ",["code","man"],". Supponendo, per esempio, che non ci si ricordi che è ",["code","uname"]," che indicherà l’attuale versione del kernel Linux, si può passare la parola ",["code","kernel"]," ad ",["code","apropros"],". Probabilmente si otterrano molte righe di output, ma tra queste ci dovrebbero essere:"],["pre","$ ",["strong","apropos kernel"],"\nsystemd-udevd-kernel.socket (8) - Device event managing daemon\nuname (2)            - get name and information about current kernel\nurandom (4)          - kernel random number source devices"],["p","Se non hai bisogno della documentazione completa di un comando, puoi ottenere rapidamente le sue informazioni di base usando ",["code","type"],". Questo esempio usa ",["code","type"]," per interrogare quattro comandi separati contemporaneamente. I risultati ci mostrano che ",["code","cp"]," (“copy”) è un programma che risiede in ",["code","/bin/cp"]," e che ",["code","kill"]," (cambia lo stato di un processo in esecuzione) è uno ",["em","shell builtin"]," - nel senso che è in realtà integrato nella shell Bash stessa:"],["pre","$ ",["strong","type uname cp kill which"],"\nuname is hashed (/bin/uname)\ncp is /bin/cp\nkill is a shell builtin\nwhich is /usr/bin/which"],["p","Si noti che, oltre a essere un normale comando binario come ",["code","cp"],", ",["code","uname"]," è anche \"hashed\". Questo perché Frank ha recentemente usato ",["code","uname"]," e, per aumentare l’efficienza del sistema, è stato aggiunto a una tabella hash al fine di renderlo più velocemente accessibile alla successiva esecuzione. Se eseguisse ",["code","type uname"]," dopo un avvio del sistema, Frank troverebbe che ",["code","type"]," descrive ancora una volta ",["code","uname"]," come un normale binario."],["note","Nota",["p","Un modo più rapido per ripulire la tabella hash è eseguire il comando ",["code","hash -d"],"."]],["p","A volte, specialmente quando si lavora con script automatici, è necessaria una fonte di informazioni più semplice su un comando. Il comando ",["code","which"],", che il nostro precedente comando ",["code","type"]," ha tracciato per noi, non restituirà altro che la posizione assoluta di un comando. Questo esempio individua i comandi ",["code","uname"]," e ",["code","which"]," ."],["pre","$ ",["strong","which uname which"],"\n/bin/uname\n/usr/bin/which"],["note","Nota",["p","Se volete visualizzare informazioni sui comandi “builtin”, potete usare il comando ",["code","help"]," seguito dal comando."]],["h3","Utilizzare l’History dei Comandi"],["p","Spesso ricercerai attentamente l’utilizzo corretto di un comando e lo eseguirai insieme a una complicata serie di opzioni e argomenti. Ma cosa succede poche settimane dopo quando è necessario eseguire lo stesso comando con le stesse opzioni e gli stessi argomenti ma non è possibile ricordare i dettagli? Invece di dover ricominciare tutto da capo, sarai spesso in grado di recuperare il comando originale usando ",["code","history"],"."],["p","Digitando ",["code","history"]," verranno restituiti i comandi che hai eseguito precedentemente, con il più recente per ultimo. Puoi facilmente cercare tra questi comandi reindirizzando una stringa specifica al comando ",["code","grep"],". Questo esempio cercherà qualsiasi comando che includa il testo ",["code","bash_history"],":"],["pre","$ ",["strong","history | grep bash_history"],"\n1605 sudo find /home -name \".bash_history\" | xargs grep sudo"],["p","Viene restituito un singolo comando insieme al suo numero progressivo, 1605."],["p","Parlando di ",["code","bash_history"],", questo è in realtà il nome di un file nascosto che dovresti trovare nella home directory del tuo utente. Dato che è un file nascosto (indicato come tale dal punto che precede il suo nome file), sarà visibile solo elencando il contenuto della directory usando ",["code","ls"]," con l’argomento ",["code","-a"],":"],["pre","$ ",["strong","ls /home/frank"],"\nnewfile\n$ ",["strong","ls -a /home/frank"],"\n.  ..  .bash_history  .bash_logout  .bashrc  .profile  .ssh  newfile"],["p","Che cosa c’è nel file ",["code",".bash_history"],"? Dai un’occhiata tu stesso: vedrai centinaia e centinaia dei tuoi comandi più recenti. Potresti, tuttavia, essere sorpreso di scoprire che mancano alcuni dei tuoi comandi più recenti. Questo perché, mentre vengono immediatamente aggiunti al database dinamico ",["code","history"],", le ultime aggiunte alla cronologia dei comandi non vengono scritte nel file ",["code",".bash_history"]," fino a quando non si esce dalla sessione."],["p","Puoi sfruttare i contenuti di \"history\" per rendere la tua esperienza da riga di comando molto più veloce ed efficiente usando i tasti freccia su e giù della tastiera. Premendo il tasto “Su” più volte, la riga di comando verrà popolata con comandi recenti. Quando arrivi a quello che desideri eseguire una seconda volta, puoi eseguirlo premendo Invio. Ciò semplifica il richiamo e, se desiderato, la modifica dei comandi più volte durante una sessione di shell."],["h2","Esercizi Guidati"],["ol",["li",["p","Usa il sistema ",["code","man"]," per determinare quale opzione consente ad ",["code","apropos"]," di eseguirsi, per poi immediatamente richiudersi, solo indicando un breve riepilogo del suo funzionamento."]," ",["table",["tr",["td"]]]],["li",["p","Usa il sistema ",["code","man"]," per determinare quale licenza è utilizzata dal comando ",["code","grep"],"."]," ",["table",["tr",["td"]]]]],["h2","Esercizi Esplorativi"],["ol",["li",["p","Identifica l’architettura hardware e la versione del kernel Linux utilizzata sul tuo computer in un formato di output di facile lettura."]," ",["table",["tr",["td"]]]],["li",["p","Visualizza le ultime venti righe del database dinamico ",["code","history"]," e del file ",["code",".bash_history"]," per confrontarli."]," ",["table",["tr",["td"]]]],["li",["p","Usa lo strumento ",["code","apropos"]," per identificare la pagina ",["code","man"]," del comando di cui avrai bisogno per visualizzare la dimensione in byte anziché in megabyte o gigabyte di un dispositivo a blocchi."]," ",["table",["tr",["td"]]]]],["h2","Sommario"],["p","In questa lezione abbiamo imparato:"],["ul",["li",["p","Come ottenere informazioni riguardo la posizione sul filesystem e sullo stack del software del sistema operativo."]],["li",["p","Come trovare aiuto per l’utilizzo di un comando."]],["li",["p","Come identificare la posizione sul filesystem e il tipo di comandi binari."]],["li",["p","Come trovare e riutilizzare i comandi eseguiti in precedenza."]]],["p","In questa lezione sono stati discussi i seguenti comandi:"],["dl",["dt",["code","Pwd"]],["dd",["p","Visualizza la posizione di lavoro corrente sul filesystem."]],["dt",["code","Uname"]],["dd",["p","Visualizza l’architettura hardware del sistema, la versione del kernel Linux, la distribuzione e la versione di distribuzione."]],["dt",["code","Man"]],["dd",["p","Accede ai file della guida che documentano l’utilizzo dei comandi."]],["dt",["code","Type"]],["dd",["p","Visualizza la posizione sul filesystem e il tipo per uno o più comandi."]],["dt",["code","Which"]],["dd",["p","Visualizza la posizione sul filesystem per un comando."]],["dt",["code","History"]],["dd",["p","Visualizza i comandi eseguiti in precedenza."]]],["h2","Risposte agli Esercizi Guidati"],["ol",["li",["p","Usa il sistema ",["code","man"]," per determinare quale opzione consente ad ",["code","apropos"]," di eseguirsi, per poi immediatamente richiudersi, solo indicando un breve riepilogo del suo funzionamento."],"  ",["p","Esegui ",["code","man apropos"]," e scorri verso il basso attraverso la sezione “Options” fino ad arrivare alla parte riguardante l’opzione ",["code","--usage"],"."]],["li",["p","Usa il sistema ",["code","man"]," per determinare quale licenza è utilizzata dal comando ",["code","grep"],"."],"  ",["p","Esegui ",["code","man grep"]," e scorri verso il basso fino alla sezione “Copyright”. Nota che il programma utilizza una licenza d’uso della Free Software Foundation."]]],["h2","Risposte agli Esercizi Esplorativi"],["ol",["li",["p","Identifica l’architettura hardware e la versione del kernel Linux in uso sul tuo computer in un formato di output di facile lettura."],"  ",["p","Esegui ",["code","man uname"],", leggi la sezione “Description” e identifica gli argomenti del comando che mostreranno solo i risultati esatti che desideri. Nota come ",["code","-v"]," ti fornirà la versione del kernel e ",["code","-i"]," fornirà la piattaforma hardware."],"    ",["pre","$ ",["strong","man uname"],"\n$ ",["strong","uname -v"],"\n$ ",["strong","uname -i"]]],["li",["p","Stampa le ultime venti righe del database dinamico ",["code","history"]," e del file ",["code",".bash_history"]," per confrontarli."],"   ",["pre","$ ",["strong","history 20"],"\n$ ",["strong","tail -n 20 .bash_history"]]],["li",["p","Usa il comando ",["code","apropos"]," per identificare la pagina ",["code","man"]," dove troverai il comando di cui avrai bisogno per visualizzare la dimensione di un dispositivo a blocchi collegato al sistema in byte invece che in megabyte o gigabyte."],"  ",["p","Un modo è quello di eseguire ",["code","apropos"]," seguito dalla stringa ",["code","block"],", leggere i risultati, notare che ",["code","lsblk"]," elenca i dispositivi a blocchi (sarebbe quindi lo strumento più probabile per le nostre esigenze), eseguire ",["code","man lsblk"],", scorrere fino alla sezione “Description” e scoprire che ",["code","-b"]," mostrerà la dimensione del dispositivo in byte. Infine, eseguire ",["code","lsblk -b"]," per vedere cosa viene visualizzato."],"    ",["pre","$ ",["strong","apropos block"],"\n$ ",["strong","man lsblk"],"\n$ ",["strong","lsblk -b"]]]]]},{"id":"103.1_02","objective":"103.1","title":"103.1 Lezione 2","url":"https://learning.lpi.org/it/learning-materials/101-500/103/103.1/103.1_02/","notice":"Linux Professional Institute Inc. Tutti i diritti riservati. Visita il sito Learning Materials: https://learning.lpi.org Quest'opera è sotto la licenza 'Creative Commons Attribution-NonCommercial-NoDerivatives 4.0 International License'.","body":[["h1","103.1 Lezione 2"],["table",["tr",["th",["p","Certificazione:"]],["td",["p","LPIC-1"]]],["tr",["th",["p","Versione:"]],["td",["p","5.0"]]],["tr",["th",["p","Argomento:"]],["td",["p","103 Comandi GNU e Unix"]]],["tr",["th",["p","Obiettivo:"]],["td",["p","103.1 Lavorare con la Riga di Comando"]]],["tr",["th",["p","Lezione:"]],["td",["p","2 di 2"]]]],["h2","Introduzione"],["p","Un ambiente di sistema operativo include gli strumenti di base, come la shell della riga di comando e talvolta una GUI, necessari per eseguire ciò di cui si ha bisogno. Il tuo ambiente inoltre ti fornirà tutta una serie di scorciatoie e valori predefiniti. In questa sezione impareremo come elencare, invocare e gestire quei valori."],["h3","Trovare le variabili di ambiente"],["p","Per iniziare, come possiamo identificare i valori attuali per ciascuna delle nostre variabili d’ambiente? Un modo è attraverso il comando ",["code","env"],":"],["pre","$ ",["strong","env"],"\nDBUS_SESSION_BUS_ADDRESS=unix:path=/run/user/1000/bus\nXDG_RUNTIME_DIR=/run/user/1000\nXAUTHORITY=/run/user/1000/gdm/Xauthority\nXDG_CONFIG_DIRS=/etc/xdg/xdg-ubuntu:/etc/xdg\nPATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:/usr/games:/usr/local/games:/snap/bin\nGJS_DEBUG_TOPICS=JS ERROR;JS LOG\n[...]"],["p","Otterrai un gran numero di informazioni in output, molto più di quanto è incluso nell’estratto sopra. Ma per ora nota la voce ",["code","PATH"],", che contiene le directory in cui la tua shell (e altri programmi) cercheranno altri programmi senza necessariamente doverli richiamare indicandone il percorso completo. Con questo set, puoi eseguire un programma binario che risiede in ",["code","/usr/local/bin"]," dalla tua home directory, come se il file fosse locale."],["p","Cambiamo argomento per un attimo. Il comando ",["code","echo"]," stamperà sullo schermo qualunque cosa tu gli dica. Che tu ci creda o no, ci saranno delle volte in cui usare ",["code","echo"],", per ripetere letteralmente qualcosa, sarà molto utile."],["pre","$ ",["strong","echo \"Hi. How are you?\""],"\nHi. How are you?"],["p","Ma c’è qualcos’altro che puoi fare con ",["code","echo"],". Quando gli dai il nome di una variabile d’ambiente - e gli dici che questa è una variabile anteponendo al suo nome un carattere ",["code","$"]," — ciò facendo, invece di stampare semplicemente il nome della variabile, la shell restituirà il suo valore. Non sei sicuro che la tua directory preferita sia attualmente nella variabile PATH? Puoi verificare rapidamente attraverso il comando ",["code","echo"],":"],["pre","$ ",["strong","echo $PATH"],"\n/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:/usr/games:/usr/local/games:/snap/bin"],["h3","Creare Nuove Variabili d’Ambiente"],["p","Puoi aggiungere le tue variabili personalizzate al tuo ambiente. Il modo più semplice è usare il carattere ",["code","="],". La stringa a sinistra sarà il nome della tua nuova variabile e la stringa a destra sarà il suo valore. Ora puoi fornire il nome della variabile a ",["code","echo"]," per verificare se ha funzionato:"],["pre","$ ",["strong","myvar=hello"],"\n$ ",["strong","echo $myvar"],"\nhello"],["note","Nota","Da notare che non c’è spazio su entrambi i lati del segno uguale durante l’assegnazione variabile."],["p","Ma ha funzionato davvero? Digita \"bash\" nel terminale per aprire una nuova shell. Questa nuova shell assomiglia esattamente a quella in cui ti trovavi, ma in realtà è una ",["em","figlia"]," (child) di quella originale (che chiamiamo ",["em","genitore"],"). Ora, all’interno di questa nuova shell figlia, cerca di far sì che ",["code","echo"]," realizzi la sua magia come prima. Niente. Cosa sta succedendo?"],["pre","$ ",["strong","bash"],"\n$ ",["strong","echo $myvar"],"\n\n$"],["p","Una variabile che crei come abbiamo appena fatto sarà disponibile solo localmente - entro la sessione di shell stessa. Se avvii una nuova shell - o chiudi la sessione usando ",["code","exit"]," - la variabile non ti seguirà. Digitando ",["code","exit"]," qui tornerai alla shell genitore originale che, in questo momento, è dove vogliamo essere. Puoi eseguire ",["code","echo $myvar"]," ancora una volta se vuoi solo confermare che la variabile è ancora valida. Ora digita ",["code","export myvar"]," per passare la variabile a tutte le shell figlie che potresti successivamente creare. Provalo: digita ",["code","bash"]," per una nuova shell e poi ",["code","echo"]," seguito dalla variabile:"],["pre","$ ",["strong","exit"],"\n$ ",["strong","export myvar"],"\n$ ",["strong","bash"],"\n$ ",["strong","echo $myvar"],"\nhello"],["p","Tutto ciò può sembrare un po' sciocco quando stiamo creando Shell senza uno scopo reale. Ma capire come vengono propagate le variabili della shell attraverso il tuo sistema diventerà molto importante una volta che si inizierà a scrivere script."],["h3","Cancellare una Variabile d’Ambiente"],["p","Vuoi sapere come eliminare tutte quelle variabili effimere che hai creato? Un modo è semplicemente quello di chiudere la shell genitore o riavviare il computer. Ma ci sono modi più semplici. Per esempio, \"unset\". Digitare ",["code","unset"]," seguito dalla variabile (senza ",["code","$"],") per eliminarla. ",["code","echo"]," ora lo dimostrerà."],["pre","$ ",["strong","unset myvar"],"\n$ ",["strong","echo $myvar"],"\n\n$"],["p","Se c’è un comando ",["code","unset"],", allora puoi scommettere che ci sia anche un comando ",["code","set"],". L’esecuzione di ",["code","set"]," da sola mostrerà molte informazioni in output, ma in realtà non è poi così diverso da quello che ti ha restituito ",["code","env"],". Guarda la prima riga di output che otterrai quando filtri per la stringa ",["code","PATH"],":"],["pre","$ ",["strong","set | grep PATH"],"\nPATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:/usr/games:/usr/local/games:/snap/bin\n[...]"],["p","Qual è la differenza tra ",["code","set"]," ed ",["code","env"],"? Per i nostri scopi, la cosa principale è che l’esecuzione di ",["code","set"]," produrrà in output variabili e funzioni. Illustriamolo. Creeremo una nuova variabile chiamata ",["code","mynewvar"]," e poi confermeremo che è lì:"],["pre","$ ",["strong","mynewvar=goodbye"],"\n$ ",["strong","echo $mynewvar"],"\ngoodbye"],["p","Ora, eseguendo ",["code","env"]," insieme a ",["code","grep"]," per filtrare la stringa ",["code","mynewvar"]," non otterremo nessun risultato nell’output. Ma eseguire ",["code","set"]," allo stesso modo ci mostrerà la nostra variabile locale precedentemente creata."],["pre","$ ",["strong","env | grep mynewvar"],"\n\n$ ",["strong","set | grep mynewvar"],"\nmynewvar=goodbye"],["h3","Usare il Virgolettato per Escludere i Caratteri Speciali"],["p","Ora è un buon momento per farti affrontare il problema dei caratteri speciali. I caratteri alfanumerici (a-z e 0-9) vengono normalmente letti letteralmente da Bash. Se provi a creare un nuovo file chiamato ",["code","myfile"],", dovresti semplicemente digitare ",["code","touch"]," seguito da ",["code","myfile"]," e Bash saprà cosa farne. Ma se vuoi includere un carattere speciale nel tuo nome file, dovrai fare un po' più di lavoro."],["p","Per illustrare questo, eseguiremo ",["code","touch"]," seguito da: ",["code","my big file"],". Il problema è che ci sono due spazi tra le parole che Bash interpreterà. Mentre, tecnicamente, non chiameresti uno spazio un “carattere” , per Bash invece è come se lo fosse letteralmente. Se elenchi i contenuti della tua directory corrente, invece di un file chiamato ",["code","my big file"],", vedrai tre file denominati, rispettivamente, ",["code","my"],", ",["code","big"]," e ",["code","file"],". Questo perché Bash ha ritenuto che tu volessi creare più file i cui nomi stavi passando in un elenco:"],["pre","$ ",["strong","touch my big file"],"\n$ ",["strong","ls"],"\nmy big file"],["p","Gli spazi verranno interpretati allo stesso modo se si eliminano (",["code","rm"],") i tre file in un solo comando:"],["pre","$ ",["strong","rm my big file"]],["p","Ora proviamo nel modo giusto. Digita ",["code","touch"]," e le tre parti del tuo nome file, ma questa volta racchiudi il nome tra virgolette. Questa volta ha funzionato. L’elenco dei contenuti della directory ti mostrerà un singolo file con il nome corretto."],["pre","$ ",["strong","touch \"my big file\""],"\n$ ",["strong","ls"],"\n'my big file'"],["p","Esistono altri modi per ottenere lo stesso effetto. Le virgolette singole, per esempio, funzionano così come le virgolette doppie. (Nota che le virgolette singole conserveranno il valore letterale di tutti i caratteri, mentre le virgolette doppie conserveranno tutti i caratteri ",["em","ad eccezione"]," di ",["code","$"],", ",["code","`"],",",["code","\\"]," e, in alcuni casi, ",["code","!"],".)"],["pre","$ ",["strong","rm 'my big file'"]],["p","Anteporre un carattere di back slash (",["code","\\"],") a un caratterre speciale farà si che Bash lo interpreti letteralmente."],["pre","$ ",["strong","touch my\\ big\\ file"]],["h2","Esercizi Guidati"],["ol",["li",["p","Usa il comando ",["code","export"]," per aggiungere una nuova directory al tuo path (questa modifica non sopravviverà al riavvio)."]," ",["table",["tr",["td"]]]],["li",["p","Usa il comando ",["code","unset"]," per cancellare la variabile ",["code","PATH"],". Prova a eseguire un comando usando ",["code","sudo"]," (per esempio ",["code","sudo cat /etc/shadow"],") . Cosa è successo? Perché? (L’uscita dalla shell ti riporterà al tuo stato originale.)"]," ",["table",["tr",["td"]]]]],["h2","Esercizi Esplorativi"],["ol",["li",["p","Ricerca in Internet l’elenco completo dei caratteri speciali."]],["li",["p","Prova a eseguire comandi usando stringhe composte da caratteri speciali e usando vari metodi per evitarli. Ci sono differenze tra il modo in cui questi metodi si comportano?"]]],["h2","Sommario"],["p","In questa lezione abbiamo imparato:"],["ul",["li",["p","Come identificare le variabili d’ambiente del tuo sistema."]],["li",["p","Come creare le proprie variabili di ambiente ed esportarle in altre shell figlie."]],["li",["p","Come rimuovere le variabili d’ambiente e come usare sia i comandi ",["code","env"]," che ",["code","set"],"."]],["li",["p","Come gestire i caratteri speciali in modo che Bash li legga letteralmente."]]],["p","In questa lezione sono stati discussi i seguenti comandi:"],["dl",["dt",["code","echo"]],["dd",["p","Stampa in output stringhe e variabili."]],["dt",["code","env"]],["dd",["p","Visualizza e modifica le variabili di ambiente."]],["dt",["code","export"]],["dd",["p","Passa una variabile alle shell figlie."]],["dt",["code","unset"]],["dd",["p","Rimuove i valori e gli attributi delle variabili e delle funzioni della shell."]]],["h2","Risposte agli Esercizi Guidati"],["ol",["li",["p","Usa il comando ",["code","export"]," per aggiungere una nuova directory al tuo path (questa modifica non sopravviverà al riavvio)."],"  ",["p","Puoi aggiungere temporaneamente una nuova directory (chiamata per esempio ",["code","myfiles"]," che risiede nella tua home directory) al tuo percorso usando ",["code","export PATH=\"/home/youname/myfiles:$PATH\""],". Crea un semplice script nella directory ",["code","myfiles /"],", rendilo eseguibile e prova ad eseguirlo da una directory diversa. Questi comandi presumono che tu sia nella tua home directory che contiene una directory chiamata ",["code","myfiles"],"."],"    ",["pre","$ ",["strong","touch myfiles/myscript.sh"],"\n$ ",["strong","echo '#!/bin/bash' >> myfiles/myscript.sh"],"\n$ ",["strong","echo 'echo Hello' >> myfiles/myscript.sh"],"\n$ ",["strong","chmod +x myfiles/myscript.sh"],"\n$ ",["strong","myscript.sh"],"\nHello"]],["li",["p","Usa il comando ",["code","unset"]," per cancellare la variabile ",["code","PATH"],". Prova a eseguire un comando usando ",["code","sudo"]," (per esempio ",["code","sudo cat /etc/shadow"],") . Che cosa è successo? Perché? (L’uscita dalla shell ti riporterà al tuo stato originale.)"],"  ",["p","Digitando ",["code","unset PATH"]," si cancelleranno le impostazioni della variabile path corrente. Tentare di invocare un binario senza il suo percorso assoluto fallirà. Per questa ragione, tentare di eseguire un comando usando sudo (che è esso stesso un programma binario situato in ",["code","/usr/bin/sudo"],") fallirà - a meno che non si specifichi la posizione assoluta, come in: ",["code","/usr/bin/sudo /bin/cat /etc/shadow"],". Puoi resettare la tua ",["code","PATH"]," usando ",["code","export"]," o semplicemente uscendo dalla shell."]]],["h2","Risposte agli Esercizi Esplorativi"],["ol",["li",["p","Ricerca in Internet l’elenco completo dei caratteri speciali."],"  ",["p","Ecco la lista: ",["code","& ; | * ? \" ' [ ] ( ) $ < > { } # / \\ ! ~"],"."]],["li",["p","Prova a eseguire comandi usando stringhe composte da caratteri speciali e usando vari metodi per evitarli. Ci sono differenze tra il modo in cui questi metodi si comportano?"],"  ",["p","Utilizzando il carattere ",["code","\""]," si manterrano i valori speciali del simbolo del dollaro ($), dell’apice traversa (",["code",") e del back slash. L’utilizzo del carattere ``"],", annullerà invece ",["em","tutti"]," i significati speciali dei caratteri e consentirà una loro interpretazione letterale."],"    ",["pre","$ ",["strong","echo \"$mynewvar\""],"\ngoodbye\n$ ",["strong","echo '$mynewvar'"],"\n$mynewvar"]]]]},{"id":"103.2_01","objective":"103.2","title":"103.2 Lezione 1","url":"https://learning.lpi.org/it/learning-materials/101-500/103/103.2/103.2_01/","notice":"Linux Professional Institute Inc. Tutti i diritti riservati. Visita il sito Learning Materials: https://learning.lpi.org Quest'opera è sotto la licenza 'Creative Commons Attribution-NonCommercial-NoDerivatives 4.0 International License'.","body":[["h1","103.2 Lezione 1"],["table",["tr",["th",["p","Certificazione:"]],["td",["p","LPIC-1"]]],["tr",["th",["p","Versione:"]],["td",["p","5.0"]]],["tr",["th",["p","Argomento:"]],["td",["p","103 Comandi GNU e Unix"]]],["tr",["th",["p","Obiettivo:"]],["td",["p","103.2 Elaborare flussi di testo utilizzando i filtri"]]],["tr",["th",["p","Lezione:"]],["td",["p","1 di 1"]]]],["h2","Introduzione"],["p","Trattare il testo è una parte importante del lavoro di ogni amministratore di sistema. Doug McIlroy, un membro del team di sviluppo originale di Unix, ha sintetizzato la filosofia Unix e ha detto (tra le altre cose importanti): \"[è necessario] Scrivere programmi per gestire i flussi di testo, perché questa è un’interfaccia universale\". Linux si ispira al funzionamento del sistema Unix e adotta fortemente la sua filosofia, quindi un amministratore deve aspettarsi molti strumenti di manipolazione del testo all’interno di una distribuzione Linux."],["h3","Una Rapida Rassegna su Reindirizzamenti e Pipe"],["dl",["dt","Ulteriori riferimenti alla filosofia Unix"],["dd",["ul",["li",["p","Scrivi programmi che facciano una cosa e la facciano bene."]],["li",["p","Scrivi programmi che lavorino insieme."]]]]],["p","Un modo importante per far lavorare i programmi insieme è attraverso il ",["em","piping"]," e i ",["em","reindirizzamenti"]," (redirections). Praticamente tutti i programmi di manipolazione del testo partono da un input standard (",["em","stdin"],"), lo inviano a un output standard (",["em","stdout"],") e inviano eventuali errori a un output degli errori standard (",["em","stderr"],"). Se non diversamente specificato, l’input standard è quello che viene digitato sulla tastiera (il programma lo legge dopo aver premuto il tasto Invio). Allo stesso modo, l’output standard e gli errori vengono visualizzati nella schermata del terminale. Vediamo come funziona il tutto."],["p","Nel tuo terminale, digita ",["code","cat"]," e quindi premi il tasto Invio. Quindi digitare del testo casuale."],["pre","$ ",["strong","cat"],"\nThis is a test\nThis is a test\nHey!\nHey!\nIt is repeating everything I type!\nIt is repeating everything I type!\n(I will hit ctrl+c so I will stop this nonsense)\n(I will hit ctrl+c so I will stop this nonsense)\n^C"],["p","Per maggiori informazioni sul comando ",["code","cat"]," (il termine deriva da “concatenare”) fare riferimento alle pagine di man."],["note","Nota",["p","Se stai lavorando su un’installazione davvero semplice di un server Linux, alcuni comandi come ",["code","info"]," e ",["code","less"]," potrebbero essere non disponibili. In tal caso, installare questi strumenti utilizzando la procedura corretta nel sistema in uso come descritto nelle lezioni corrispondenti."]],["p","Come dimostrato sopra, se non specifichi da dove ",["code","cat"]," deve leggere, questo lo farà dall’input standard (qualunque cosa tu digiti) e produrrà tutto ciò che legge sulla tua finestra del terminale (il suo output standard)."],["p","Ora prova quanto segue:"],["pre","$ ",["strong","cat > mytextfile"],"\nThis is a test\nI hope cat is storing this to mytextfile as I redirected the output\nI will hit ctrl+c now and check this\n^C\n\n$ ",["strong","cat mytextfile"],"\nThis is a test\nI hope cat is storing this to mytextfile as I redirected the output\nI will hit ctrl+c now and check this"],["p","Il carattere ",["code",">"]," (Maggiore di) dice a ",["code","cat"]," di indirizzare il suo output sul file ",["code","mytextfile"],", non sullo standard output. Ora prova questo:"],["pre","$ ",["strong","cat mytextfile > mynewtextfile"],"\n$ ",["strong","cat mynewtextfile"],"\nThis is a test\nI hope cat is storing this to mytextfile as I redirected the output\nI will hit ctrl+c now and check this"],["p","Questo ha l’effetto di copiare ",["code","mytextfile"]," in ",["code","mynewtextfile"],". Puoi effettivamente verificare che questi due file abbiano lo stesso contenuto eseguendo il comando ",["code","diff"],":"],["pre","$ ",["strong","diff mynewtextfile mytextfile"]],["p","Poiché non esiste alcun output, i file sono uguali. Ora prova un reindirizzamento accodato (",["em","append redirection"],") (",["code",">>"],"):"],["pre","$ ",["strong","echo 'This is my new line' >> mynewtextfile"],"\n$ ",["strong","diff mynewtextfile mytextfile"],"\n4d3\n< This is my new line"],["p","Finora abbiamo usato i reindirizzamenti per creare e manipolare i file. Possiamo anche usare le pipe (rappresentate dal simbolo ",["code","|"],") per reindirizzare l’output di un programma ad un altro programma. Cerchiamo di trovare le righe in cui si trova la parola “this”:"],["pre","$ ",["strong","cat mytextfile | grep this"],"\nI hope cat is storing this to mytextfile as I redirected the output\nI will hit ctrl+c now and check this\n\n$ ",["strong","cat mytextfile | grep -i this"],"\nThis is a test\nI hope cat is storing this to mytextfile as I redirected the output\nI will hit ctrl+c now and check this"],["p","Ora abbiamo reindirizzato l’output di ",["code","cat"]," a un altro comando: ",["code","grep"],". Nota che quando ignoriamo maiuscole e minuscole (usando l’opzione ",["code","-i"],") otteniamo di conseguenza una riga in più."],["h3","Elaborare Flussi di Testo"],["h4","Lettura di un File Compresso"],["p","Creeremo un file chiamato ",["code","ftu.txt"]," contenente un elenco dei seguenti comandi:"],["pre","bzcat\ncat\ncut\nhead\nless\nmd5sum\nnl\nod\npaste\nsed\nsha256sum\nsha512sum\nsort\nsplit\ntail\ntr\nuniq\nwc\nxzcat\nzcat"],["p","Ora useremo il comando ",["code","grep"]," per stampare tutte le linee contenenti la stringa ",["code","cat"],":"],["pre","$ ",["strong","cat ftu.txt | grep cat"],"\nbzcat\ncat\nxzcat\nzcat"],["p","Un altro modo per ottenere queste informazioni è semplicemente usare il comando ",["code","grep"]," per filtrare direttamente il testo, senza la necessità di usare un’altra applicazione per inviare il flusso di testo all'",["em","stdout"],"."],["pre","$ ",["strong","grep cat ftu.txt"],"\nbzcat\ncat\nxzcat\nzcat"],["note","Nota",["p","Ricorda che ci sono molti modi per eseguire la stessa attività usando Linux."]],["p","Ci sono altri comandi che gestiscono i file compressi (",["code","bzcat"]," per i file compressi ",["code","bzip"],", ",["code","xzcat"]," per i file compressi ",["code","xz"]," e ",["code","zcat"]," per i file compressi ",["code","gzip"],") e ognuno viene usato per visualizzare il contenuto di un file compresso basato sull’algoritmo di compressione utilizzato."],["p","Verifica che il file appena creato ",["code","ftu.txt"]," sia l’unico nella directory, quindi crea una versione compressa del file ",["code","gzip"],":"],["pre","$ ",["strong","ls ftu"],"*\nftu.txt\n\n$ ",["strong","gzip ftu.txt"],"\n$ ",["strong","ls ftu"],"*\nftu.txt.gz"],["p","Quindi, usa il comando ",["code","zcat"]," per visualizzare il contenuto del file compresso con gzip:"],["pre","$ ",["strong","zcat ftu.txt.gz"],"\nbzcat\ncat\ncut\nhead\nless\nmd5sum\nnl\nod\npaste\nsed\nsha256sum\nsha512sum\nsort\nsplit\ntail\ntr\nuniq\nwc\nxzcat\nzcat"],["p","Nota che ",["code","gzip"]," comprime ",["code","ftu.txt"]," in ",["code","ftu.txt.gz"]," e rimuoverà il file originale. Di default, non verrà visualizzato alcun output dal comando ",["code","gzip"],". Comunque, se vuoi che ",["code","gzip"]," ti dica cosa sta facendo, usa l’opzione ",["code","-v"]," per l’output “verboso”."],["h4","Visualizzare un File in un Paginatore"],["p","Sai che ",["code","cat"]," concatena un file nell’output standard (una volta che viene fornito un file dopo il comando). Il file ",["code","/var/log/syslog"]," è dove il tuo sistema Linux memorizza tutto quello che sta accadendo nel sistema. Usare il comando ",["code","sudo"]," per elevare i privilegi in modo da poter leggere il file ",["code","/var/log/syslog"],":"],["pre","$ ",["strong","sudo cat /var/log/syslog"]],["ol",["li",["p","vedrai i messaggi scorrere molto velocemente nella finestra del tuo terminale. È possibile reindirizzare l’output al programma ",["code","less"]," in modo che i risultati vengano impaginati. Usando ",["code","less"]," puoi usare i tasti freccia per navigare nell’output e anche usare i comandi come utilizzassi ",["code","vi"]," per navigare e cercare in tutto il testo."]]],["p","Tuttavia, invece di reindirizzare il comando ",["code","cat"]," in un programma di impaginazione, è più pragmatico usare direttamente il programma di impaginazione:"],["pre","$ ",["strong","sudo less /var/log/syslog"],"\n... (output omitted for clarity)"],["h4","Ottenere una Parte di un File di Testo"],["p","Se è necessario rivedere solo l’inizio o la fine di un file, sono disponibili altri metodi. Il comando ",["code","head"]," è usato per leggere di default le prime dieci righe di un file, e il comando ",["code","tail"]," è usato per leggere di default. le ultime dieci righe di un file. Ora prova:"],["pre","$ ",["strong","sudo head /var/log/syslog"],"\nNov 12 08:04:30 hypatia rsyslogd: [origin software=\"rsyslogd\" swVersion=\"8.1910.0\" x-pid=\"811\" x-info=\"https://www.rsyslog.com\"] rsyslogd was HUPed\nNov 12 08:04:30 hypatia systemd[1]: logrotate.service: Succeeded.\nNov 12 08:04:30 hypatia systemd[1]: Started Rotate log files.\nNov 12 08:04:30 hypatia vdr: [928] video directory scanner thread started (pid=882, tid=928, prio=low)\nNov 12 08:04:30 hypatia vdr: [882] registered source parameters for 'A - ATSC'\nNov 12 08:04:30 hypatia vdr: [882] registered source parameters for 'C - DVB-C'\nNov 12 08:04:30 hypatia vdr: [882] registered source parameters for 'S - DVB-S'\nNov 12 08:04:30 hypatia vdr: [882] registered source parameters for 'T - DVB-T'\nNov 12 08:04:30 hypatia vdr[882]: vdr: no primary device found - using first device!\nNov 12 08:04:30 hypatia vdr: [929] epg data reader thread started (pid=882, tid=929, prio=high)\n$ ",["strong","sudo tail /var/log/syslog"],"\nNov 13 10:24:45 hypatia kernel: [ 8001.679238] mce: CPU7: Core temperature/speed normal\nNov 13 10:24:46 hypatia dbus-daemon[2023]: [session uid=1000 pid=2023] Activating via systemd: service name='org.freedesktop.Tracker1.Miner.Extract' unit='tracker-extract.service' requested by ':1.73' (uid=1000 pid=2425 comm=\"/usr/lib/tracker/tracker-miner-fs \")\nNov 13 10:24:46 hypatia systemd[2004]: Starting Tracker metadata extractor...\nNov 13 10:24:47 hypatia dbus-daemon[2023]: [session uid=1000 pid=2023] Successfully activated service 'org.freedesktop.Tracker1.Miner.Extract'\nNov 13 10:24:47 hypatia systemd[2004]: Started Tracker metadata extractor.\nNov 13 10:24:54 hypatia kernel: [ 8010.462227] mce: CPU0: Core temperature above threshold, cpu clock throttled (total events = 502907)\nNov 13 10:24:54 hypatia kernel: [ 8010.462228] mce: CPU4: Core temperature above threshold, cpu clock throttled (total events = 502911)\nNov 13 10:24:54 hypatia kernel: [ 8010.469221] mce: CPU0: Core temperature/speed normal\nNov 13 10:24:54 hypatia kernel: [ 8010.469222] mce: CPU4: Core temperature/speed normal\nNov 13 10:25:03 hypatia systemd[2004]: tracker-extract.service: Succeeded."],["p","Per indicate il numero di righe visualizzate, possiamo reindirizzare l’output del comando ",["code","head"]," al comando ",["code","nl"],", che mostrerà il numero di righe di testo trasmesse al comando:"],["pre","$ ",["strong","sudo head /var/log/syslog | nl"],"\n1\tNov 12 08:04:30 hypatia rsyslogd: [origin software=\"rsyslogd\" swVersion=\"8.1910.0\" x-pid=\"811\" x-info=\"https://www.rsyslog.com\"] rsyslogd was HUPed\n2\tNov 12 08:04:30 hypatia systemd[1]: logrotate.service: Succeeded.\n3\tNov 12 08:04:30 hypatia systemd[1]: Started Rotate log files.\n4\tNov 12 08:04:30 hypatia vdr: [928] video directory scanner thread started (pid=882, tid=928, prio=low)\n5\tNov 12 08:04:30 hypatia vdr: [882] registered source parameters for 'A - ATSC'\n6\tNov 12 08:04:30 hypatia vdr: [882] registered source parameters for 'C - DVB-C'\n7\tNov 12 08:04:30 hypatia vdr: [882] registered source parameters for 'S - DVB-S'\n8\tNov 12 08:04:30 hypatia vdr: [882] registered source parameters for 'T - DVB-T'\n9\tNov 12 08:04:30 hypatia vdr[882]: vdr: no primary device found - using first device!\n10\tNov 12 08:04:30 hypatia vdr: [929] epg data reader thread started (pid=882, tid=929, prio=high)"],["p","Possiamo fare lo stesso eseguendo il piping dell’output del comando ",["code","tail"]," al comando ",["code","wc"],", che di default conta il numero di parole all’interno di un documento, e usando l’opzione ",["code","-l"]," per stampare il numero di righe di testo che il comando ha letto:"],["pre","$ ",["strong","sudo tail /var/log/syslog | wc -l"],"\n10"],["p","Se un amministratore deve visualizzare più (o meno) parti dall’inizio o dalla fine di un file, l’opzione ",["code","-n"]," può essere usata per definire l’output dei comandi:"],["pre","$ ",["strong","sudo tail -n 5 /var/log/syslog"],"\nNov 13 10:37:24 hypatia systemd[2004]: tracker-extract.service: Succeeded.\nNov 13 10:37:42 hypatia dbus-daemon[2023]: [session uid=1000 pid=2023] Activating via systemd: service name='org.freedesktop.Tracker1.Miner.Extract' unit='tracker-extract.service' requested by ':1.73' (uid=1000 pid=2425 comm=\"/usr/lib/tracker/tracker-miner-fs \")\nNov 13 10:37:42 hypatia systemd[2004]: Starting Tracker metadata extractor...\nNov 13 10:37:43 hypatia dbus-daemon[2023]: [session uid=1000 pid=2023] Successfully activated service 'org.freedesktop.Tracker1.Miner.Extract'\nNov 13 10:37:43 hypatia systemd[2004]: Started Tracker metadata extractor.\n$ ",["strong","sudo head -n 12 /var/log/syslog"],"\nNov 12 08:04:30 hypatia rsyslogd: [origin software=\"rsyslogd\" swVersion=\"8.1910.0\" x-pid=\"811\" x-info=\"https://www.rsyslog.com\"] rsyslogd was HUPed\nNov 12 08:04:30 hypatia systemd[1]: logrotate.service: Succeeded.\nNov 12 08:04:30 hypatia systemd[1]: Started Rotate log files.\nNov 12 08:04:30 hypatia vdr: [928] video directory scanner thread started (pid=882, tid=928, prio=low)\nNov 12 08:04:30 hypatia vdr: [882] registered source parameters for 'A - ATSC'\nNov 12 08:04:30 hypatia vdr: [882] registered source parameters for 'C - DVB-C'\nNov 12 08:04:30 hypatia vdr: [882] registered source parameters for 'S - DVB-S'\nNov 12 08:04:30 hypatia vdr: [882] registered source parameters for 'T - DVB-T'\nNov 12 08:04:30 hypatia vdr[882]: vdr: no primary device found - using first device!\nNov 12 08:04:30 hypatia vdr: [929] epg data reader thread started (pid=882, tid=929, prio=high)\nNov 12 08:04:30 hypatia vdr: [882] no DVB device found\nNov 12 08:04:30 hypatia vdr: [882] initializing plugin: vnsiserver (1.8.0): VDR-Network-Streaming-Interface (VNSI) Server"],["h4","Le Basi di sed, l’Editor di Flussi di Testo"],["p","Diamo un’occhiata agli altri file, termini e utilità che non hanno \"cat\" nei loro nomi. Possiamo farlo passando l’opzione ",["code","-v"]," a ",["code","grep"],", che indicherà al comando di produrre solo le righe che non contengono ",["code","cat"],":"],["pre","$ ",["strong","zcat ftu.txt.gz | grep -v cat"],"\ncut\nhead\nless\nmd5sum\nnl\nod\npaste\nsed\nsha256sum\nsha512sum\nsort\nsplit\ntail\ntr\nuniq\nwc"],["p","Gran parte di ciò che possiamo fare con ",["code","grep"]," possiamo anche farla con ",["code","sed"]," - l’editor di flussi per filtrare e trasformare il testo (come indicato nella pagina di manuale di ",["code","sed"],"). Per prima cosa ripristineremo il nostro file ",["code","ftu.txt"]," decomprimendo il nostro archivio ",["code","gzip"],":"],["pre","$ ",["strong","gunzip ftu.txt.gz"],"\n$ ",["strong","ls ftu"],"*\nftu.txt"],["p","Ora, possiamo usare ",["code","sed"]," per elencare solo le righe che contengono la stringa ",["code","cat"],":"],["pre","$ ",["strong","sed -n /cat/p < ftu.txt"],"\nbzcat\ncat\nxzcat\nzcat"],["p","Abbiamo usato il segno minore ",["code","<"]," per indirizzare il contenuto del file ",["code","ftu.txt"]," nel nostro comando ",["code","sed"],". La stringa racchiusa tra ",["em","slash"]," (ovvero ",["code","/cat/"],") è il termine che stiamo cercando. L’opzione ",["code","-n"]," indica a ",["code","sed"]," di non produrre output (tranne quello successivamente indicato dal comando ",["code","p"],"). Prova a eseguire questo stesso comando senza l’opzione ",["code","-n"]," per vedere cosa succede. Quindi prova questo:"],["pre","$ ",["strong","sed /cat/d < ftu.txt"],"\ncut\nhead\nless\nmd5sum\nnl\nod\npaste\nsed\nsha256sum\nsha512sum\nsort\nsplit\ntail\ntr\nuniq\nwc"],["p","Se non usiamo l’opzione ",["code","-n"],", ",["code","sed"]," visualizzerà il contenuto proveniente dal file ad eccezione di ciò che ",["code","d"]," indica a ",["code","sed"]," di cancellare dal suo output."],["p","Un uso comune di ",["code","sed"]," è trovare e sostituire il testo all’interno di un file. Supponiamo di voler cambiare ogni ricorrenza di ",["code","cat"]," in ",["code","dog"],". Puoi usare ",["code","sed"]," per fare ciò fornendo l’opzione ",["code","s"]," per scambiare ogni occorrenza del primo termine, ",["code","cat"],", per il secondo termine, ",["code","dog"],":"],["pre","$ ",["strong","sed s/cat/dog/ < ftu.txt"],"\nbzdog\ndog\ncut\nhead\nless\nmd5sum\nnl\nod\npaste\nsed\nsha256sum\nsha512sum\nsort\nsplit\ntail\ntr\nuniq\nwc\nxzdog\nzdog"],["p","Invece di usare un operatore di reindirizzamento (",["code","<"],") per passare il file ",["code","ftu.txt"]," nel nostro comando ",["code","sed"],", possiamo semplicemente far funzionare direttamente il comando ",["code","sed"]," sul file. Lo proveremo ora, creando contemporaneamente un backup del file originale:"],["pre","$ ",["strong","sed -i.backup s/cat/dog/ ftu.txt"],"\n$ ",["strong","ls ftu"],"*\nftu.txt  ftu.txt.backup"],["p","L’opzione ",["code","-i"]," eseguirà un’operazione ",["code","sed"]," sul tuo file ",["em","originale"],". Se non usi il ",["code",".backup"]," dopo il parametro ",["code","-i"],", avresti semplicemente riscritto il tuo file ",["em","originale"],". Qualunque cosa tu usi come testo dopo il parametro ",["code","-i"]," sarà il nome in cui il file originale verrà salvato prima delle modifiche che hai richiesto a ",["code","sed"],"."],["h4","Garantire l’Integrità dei Dati"],["p","Abbiamo dimostrato quanto sia facile manipolare i file in Linux. Ci sono momenti in cui potresti voler distribuire un file a qualcun altro e vuoi essere sicuro che il destinatario riceva una copia autentica del file originale. Un uso molto comune di questa tecnica viene praticato quando i server di distribuzione Linux ospitano immagini CD o DVD scaricabili del loro software insieme a file che contengono i valori di ",["em","checksum"]," calcolati di tali immagini disco. Ecco per esempio un elenco da un mirror di download della distribuzione Debian:"],["pre","━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n[PARENTDIR] Parent Directory                                      -\n[SUM]       MD5SUMS                              2019-09-08 17:46 274\n[CRT]       MD5SUMS.sign                         2019-09-08 17:52 833\n[SUM]       SHA1SUMS                             2019-09-08 17:46 306\n[CRT]       SHA1SUMS.sign                        2019-09-08 17:52 833\n[SUM]       SHA256SUMS                           2019-09-08 17:46 402\n[CRT]       SHA256SUMS.sign                      2019-09-08 17:52 833\n[SUM]       SHA512SUMS                           2019-09-08 17:46 658\n[CRT]       SHA512SUMS.sign                      2019-09-08 17:52 833\n[ISO]       debian-10.1.0-amd64-netinst.iso      2019-09-08 04:37 335M\n[ISO]       debian-10.1.0-amd64-xfce-CD-1.iso    2019-09-08 04:38 641M\n[ISO]       debian-edu-10.1.0-amd64-netinst.iso  2019-09-08 04:38 405M\n[ISO]       debian-mac-10.1.0-amd64-netinst.iso  2019-09-08 04:38 334M\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"],["p","Nell’elenco sopra, i file di immagine dell’installatore Debian sono accompagnati da file di testo che contengono checksum dei file generati da vari algoritmi (MD5, SHA1, SHA256 e SHA512)."],["note","Nota",["p","Un checksum è un valore derivato da un calcolo matematico, basato su una funzione hash crittografica, rispetto a un file. Esistono diversi tipi di funzioni ",["em","hash"]," crittografiche che variano di intensità. L’esame prevede che tu abbia familiarità con l’uso di ",["code","md5sum"],", ",["code","sha256sum"]," e ",["code","sha512sum"],"."]],["p","Una volta scaricato un file (per esempio, l’immagine ",["code","debian-10.1.0-amd64-netinst.iso"],"), confronterai il checksum del file scaricato con un valore di checksum che ti è stato fornito."],["p","Ecco un esempio per illustrare quanto fin qui detto. Calcoleremo il valore SHA256 del file ",["code","ftu.txt"]," usando il comando ",["code","sha256sum"],":"],["pre","$ ",["strong","sha256sum ftu.txt"],"\n345452304fc26999a715652543c352e5fc7ee0c1b9deac6f57542ec91daf261c  ftu.txt"],["p","La lunga stringa di caratteri che precede il nome del file è il valore di checksum SHA256 di questo file di testo. Creiamo un file che contenga quel valore, in modo da poterlo utilizzare per verificare l’integrità del nostro file originale di testo. Possiamo farlo con lo stesso comando ",["code","sha256sum"]," e reindirizzare l’output su un file:"],["pre","$ ",["strong","sha256sum ftu.txt > sha256.txt"]],["p","Ora, per verificare il file ",["code","ftu.txt"],", utilizziamo semplicemente lo stesso comando e forniamo il nome file che contiene il nostro valore di checksum insieme all’opzione ",["code","-c"],":"],["pre","$ ",["strong","sha256sum -c sha256.txt"],"\nftu.txt: OK"],["p","Il valore contenuto nel file corrisponde al checksum SHA256 calcolato per il nostro file ",["code","ftu.txt"],", proprio come ci aspetteremmo. Tuttavia, se il file originale fosse modificato (come alcuni byte persi durante il download di un file, o se qualcuno lo avesse deliberatamente manomesso), il controllo del valore fallirebbe. In tali casi sappiamo che il nostro file è danneggiato o corrotto e non possiamo fidarci dell’integrità del suo contenuto. Per dimostrare il punto, aggiungeremo del testo alla fine del file:"],["pre","$ ",["strong","echo \"new entry\" >> ftu.txt"]],["p","Ora faremo un tentativo di verificare l’integrità del file:"],["pre","$ ",["strong","sha256sum -c sha256.txt"],"\nftu.txt: FAILED\nsha256sum: WARNING: 1 computed checksum did NOT match"],["p","Vediamo che il checksum non corrisponde a quanto previsto per il file. Pertanto, non potevamo fidarci dell’integrità di questo file. Potremmo tentare di scaricare una nuova copia di un file, segnalare l’errore del checksum al mittente del file o segnalarlo a un team di sicurezza del data center in base all’importanza del file."],["h4","Guardare più in Profondità nei File"],["p","Il comando octal dump (",["code","od"],") è spesso usato per il debug di applicazioni e vari file. Di per sé, il comando ",["code","od"]," elencherà semplicemente i contenuti di un file in formato ottale. Possiamo usare il nostro file ",["code","ftu.txt"]," in precedenza per esercitarci con questo comando:"],["pre","$ ",["strong","od ftu.txt"],"\n0000000 075142 060543 005164 060543 005164 072543 005164 062550\n0000020 062141 066012 071545 005163 062155 071465 066565 067012\n0000040 005154 062157 070012 071541 062564 071412 062145 071412\n0000060 060550 032462 071466 066565 071412 060550 030465 071462\n0000100 066565 071412 071157 005164 070163 064554 005164 060564\n0000120 066151 072012 005162 067165 070551 073412 005143 075170\n0000140 060543 005164 061572 072141 000012\n0000151"],["p","La prima colonna di output è il ",["em","byte offset"]," per ogni riga di output. Poiché ",["code","od"]," stampa le informazioni in formato ottale di default, ogni riga inizia con un byte offset di otto bit, seguito da otto colonne, ognuna contenente il valore ottale dei dati all’interno di quella colonna."],["note","Suggerimento",["p","Ricordiamoci che un ",["em","byte"]," è composto da 8 bit."]],["p","Se dovessi visualizzare il contenuto di un file in formato esadecimale, usa l’opzione ",["code","-x"],":"],["pre","$ ",["strong","od -x ftu.txt"],"\n0000000 7a62 6163 0a74 6163 0a74 7563 0a74 6568\n0000020 6461 6c0a 7365 0a73 646d 7335 6d75 6e0a\n0000040 0a6c 646f 700a 7361 6574 730a 6465 730a\n0000060 6168 3532 7336 6d75 730a 6168 3135 7332\n0000100 6d75 730a 726f 0a74 7073 696c 0a74 6174\n0000120 6c69 740a 0a72 6e75 7169 770a 0a63 7a78\n0000140 6163 0a74 637a 7461 000a\n0000151"],["p","Ora ciascuna delle otto colonne dopo il byte offset è rappresentata dal loro equivalente esadecimale."],["p","Un utile uso del comando ",["code","od"]," è per il debug degli script. Per esempio, il comando ",["code","od"]," può mostrarci caratteri normalmente non presenti in un file, come per esempio quelli di ",["em","newline"],". Possiamo farlo con l’opzione ",["code","-c"],", in modo che, invece di visualizzare la notazione numerica per ogni byte, queste voci di colonna verranno mostrate come equivalenti di carattere:"],["pre","$ ",["strong","od -c ftu.txt"],"\n0000000   b   z   c   a   t  \\n   c   a   t  \\n   c   u   t  \\n   h   e\n0000020   a   d  \\n   l   e   s   s  \\n   m   d   5   s   u   m  \\n   n\n0000040   l  \\n   o   d  \\n   p   a   s   t   e  \\n   s   e   d  \\n   s\n0000060   h   a   2   5   6   s   u   m  \\n   s   h   a   5   1   2   s\n0000100   u   m  \\n   s   o   r   t  \\n   s   p   l   i   t  \\n   t   a\n0000120   i   l  \\n   t   r  \\n   u   n   i   q  \\n   w   c  \\n   x   z\n0000140   c   a   t  \\n   z   c   a   t  \\n\n0000151"],["p","Tutte le voci ",["em","newline"]," all’interno del file sono rappresentate dai caratteri nascosti ",["code","\\n"],". Se si desidera solo visualizzare tutti i caratteri all’interno di un file e non è necessario visualizzare le informazioni di byte offset, questa colonna può essere rimossa dall’output in questo modo:"],["pre","$ ",["strong","od -An -c ftu.txt"],"\n   b   z   c   a   t  \\n   c   a   t  \\n   c   u   t  \\n   h   e\n   a   d  \\n   l   e   s   s  \\n   m   d   5   s   u   m  \\n   n\n   l  \\n   o   d  \\n   p   a   s   t   e  \\n   s   e   d  \\n   s\n   h   a   2   5   6   s   u   m  \\n   s   h   a   5   1   2   s\n   u   m  \\n   s   o   r   t  \\n   s   p   l   i   t  \\n   t   a\n   i   l  \\n   t   r  \\n   u   n   i   q  \\n   w   c  \\n   x   z\n   c   a   t  \\n   z   c   a   t  \\n"],["h2","Esercizi Guidati"],["ol",["li",["p","Qualcuno ha appena donato un laptop alla tua scuola e ora desideri installare Linux su di esso. Non esiste un manuale e sei stato costretto ad avviarlo senza interfaccia grafica da una chiavetta USB. Ottieni un terminale shell e sai che, per ogni processore, ci saranno una serie di riferimenti nel file ",["code","/proc/cpuinfo"],":"],"   ",["pre",["strong","processor\t: 0"],"\nvendor_id\t: GenuineIntel\ncpu family\t: 6\nmodel\t\t: 158\n\n(linee saltate)\n\n",["strong","processor\t: 1"],"\nvendor_id\t: GenuineIntel\ncpu family\t: 6\nmodel\t\t: 158\n\n(altre linee saltate)"],"    ",["ul",["li",["p","Usando i comandi ",["code","grep"]," e ",["code","wc"]," mostra quanti processori hai."]," ",["table",["tr",["td"]]]],["li",["p","Fai la stessa cosa con ",["code","sed"]," invece che con ",["code","grep"],"."]," ",["table",["tr",["td"]]]]]],["li",["p","Esplora il tuo file locale ",["code","/etc/passwd"]," con i comandi ",["code","grep"],", ",["code","sed"],", ",["code","head"]," e ",["code","tail"]," per le attività seguenti:"],"  ",["ul",["li",["p","Quali utenti hanno accesso a una shell Bash?"]," ",["table",["tr",["td"]]]],["li",["p","Il tuo sistema ha vari utenti che esistono per gestire programmi specifici o per scopi amministrativi. Non hanno accesso a una shell. Quanti ne esistono nel tuo sistema?"]," ",["table",["tr",["td"]]]],["li",["p","Quanti utenti esistono nel tuo sistema (ricorda: usa solo il file ",["code","/etc/passwd"],")?"]," ",["table",["tr",["td"]]]],["li",["p","Elenca solo la prima riga, l’ultima riga e la decima riga del tuo file ",["code","/etc/passwd"],"."]," ",["table",["tr",["td"]]]]]],["li",["p","Considera questo esempio di file ",["code","/etc/passwd"],". Copiare le righe seguenti in un file locale chiamato ",["code","mypasswd"]," per questo esercizio."],"   ",["pre","root:x:0:0:root:/root:/bin/bash\ndaemon:x:1:1:daemon:/usr/sbin:/usr/sbin/nologin\nbin:x:2:2:bin:/bin:/usr/sbin/nologin\nsys:x:3:3:sys:/dev:/usr/sbin/nologin\nsync:x:4:65534:sync:/bin:/bin/sync\nnvidia-persistenced:x:121:128:NVIDIA Persistence Daemon,,,:/nonexistent:/sbin/nologin\nlibvirt-qemu:x:64055:130:Libvirt Qemu,,,:/var/lib/libvirt:/usr/sbin/nologin\nlibvirt-dnsmasq:x:122:133:Libvirt Dnsmasq,,,:/var/lib/libvirt/dnsmasq:/usr/sbin/nologin\ncarol:x:1000:2000:Carol Smith,Finance,,,Main Office:/home/carol:/bin/bash\ndave:x:1001:1000:Dave Edwards,Finance,,,Main Office:/home/dave:/bin/ksh\nemma:x:1002:1000:Emma Jones,Finance,,,Main Office:/home/emma:/bin/bash\nfrank:x:1003:1000:Frank Cassidy,Finance,,,Main Office:/home/frank:/bin/bash\ngrace:x:1004:1000:Grace Kearns,Engineering,,,Main Office:/home/grace:/bin/ksh\nhenry:x:1005:1000:Henry Adams,Sales,,,Main Office:/home/henry:/bin/bash\njohn:x:1006:1000:John Chapel,Sales,,,Main Office:/home/john:/bin/bash"],"    ",["ul",["li",["p","Elenca tutti gli utenti nel gruppo ",["code","1000"]," (usa ",["code","sed"]," per selezionare solo il campo appropriato) dal tuo file ",["code","mypasswd"],"."]," ",["table",["tr",["td"]]]],["li",["p","Elenca solo i nomi completi di tutti gli utenti di questo gruppo (usa ",["code","sed"]," e ",["code","cut"],")."]," ",["table",["tr",["td"]]]]]]],["h2","Esercizi Esplorativi"],["ol",["li",["p","Ancora una volta usando il file ",["code","mypasswd"]," degli esercizi precedenti, creare un comando Bash che selezioni un individuo del ",["em","Main Office"]," per fargli vincere un concorso a premi. Utilizzare il comando ",["code","sed"]," per visualizzare solo le righe realative al main Office, quindi una sequenza di comandi ",["code","cut"]," per recuperare il nome di ciascun utente da queste righe. Successivamente si procederà a ordinare casualmente questi nomi e a visualizzare solo il nome in testa all’elenco."]," ",["table",["tr",["td"]]]],["li",["p","Quante persone lavorano in Finance, Engineering e Sales? (Prova a utilizzare il comando ",["code","uniq"],".)"]," ",["table",["tr",["td"]]]],["li",["p","Ora vuoi preparare un file CSV (valori separati da virgola) in modo da poter importare facilmente, dal file ",["code","mypasswd"]," nell’esempio precedente, il file ",["code","names.csv"]," in LibreOffice. Il contenuto del file avrà il seguente formato:"],"   ",["pre","First Name,Last Name,Position\nCarol,Smith,Finance\n...\nJohn,Chapel,Sales"],"   ",["note","Suggerimento","Utilizza i comandi ",["code","sed"],", ",["code","cut"]," e ",["code","paste"]," per ottenere i risultati desiderati. Nota che la virgola (",["code",","],") sarà il delimitatore per questo file."]],["li",["p","Supponiamo che il foglio di calcolo ",["code","names.csv"]," creato nell’esercizio precedente sia un file importante e vogliamo assicurarci che nessuno lo manometterà dal momento in cui lo inviamo a qualcuno fino a quando il nostro destinatario lo riceverà. Come possiamo assicurare l’integrità di questo file usando ",["code","md5sum"],"?"]," ",["table",["tr",["td"]]]],["li",["p","Ti sei ripromesso di leggere cento righe di un testo classico al giorno e hai deciso di iniziare con ",["em","Mariner and Mystic"]," di Herman Melville. Elabora un comando usando ",["code","split"]," che separerà questo libro in sezioni di 100 righe ciascuna. Per ottenere il libro in formato testo normale, cercalo su ",["a","https://www.gutenberg.org","https://www.gutenberg.org"],"."]," ",["table",["tr",["td"]]]],["li",["p","Usando ",["code","ls -l"]," nella directory ",["code","/etc"],", che tipo di elenco ottieni? Usando il comando ",["code","cut"]," sull’output del comando ",["code","ls"]," come visualizzeresti solo i nomi dei file? E come il nome del file e del proprietario dei file? Insieme ai comandi ",["code","ls -l"]," e ",["code","cut"],", usa il comando ",["code","tr"]," per ",["em","sostituire"]," più occorrenze di uno spazio con un singolo spazio per aiutare a formattare l’output generato da un comando ",["code","cut"],"."]," ",["table",["tr",["td"]]]],["li",["p","Questo esercizio presuppone che tu sia su una macchina reale (non una macchina virtuale). Devi anche avere una chiavetta USB con te. Esamina le pagine del manuale per il comando ",["code","tail"]," e scopri come ",["em","seguire"]," un file mentre il testo viene aggiunto ad esso. Durante il monitoraggio dell’output di un comando ",["code","tail"]," sul file ",["code","/var/log/syslog"],", inserire una chiavetta USB. Scrivi il comando completo che utilizzeresti per ottenere ",["em","Product"],", ",["em","Manufacturer"]," e ",["em","total amount of memory"]," della tua chiavetta USB."]," ",["table",["tr",["td"]],["tr",["td"]]]]],["h2","Sommario"],["p","La gestione dei flussi di testo è di grande importanza in qualsiasi sistema Linux. I flussi di testo possono essere elaborati utilizzando gli script per automatizzare le attività quotidiane o trovare informazioni di debug rilevanti nei file di log. Ecco un breve riassunto dei comandi trattati in questa lezione:"],["dl",["dt",["code","cat"]],["dd",["p","Usato per combinare o leggere file di testo semplice.."]],["dt",["code","bzcat"]],["dd",["p","Permette l’elaborazione o la lettura di file compressi usando il metodo ",["code","bzip2"],"."]],["dt",["code","xzcat"]],["dd",["p","Permette l’elaborazione o la lettura di file compressi usando il metodo ",["code","xz"],"."]],["dt",["code","zcat"]],["dd",["p","Permette l’elaborazione o la lettura di file compressi usando il metodo ",["code","gzip"],"."]],["dt",["code","less"]],["dd",["p","Questo comando impagina il contenuto di un file e consente la navigazione e la funzionalità di ricerca."]],["dt",["code","head"]],["dd",["p","Questo comando visualizza le prime 10 righe di un file per impostazione predefinita. Con l’uso dell’opzione ",["code","-n"]," è possibile visualizzare più o meno righe."]],["dt",["code","tail"]],["dd",["p","Questo comando visualizza le ultime 10 righe di un file per impostazione predefinita. Con l’uso dell’opzione ",["code","-n"]," è possibile visualizzare più o meno righe. L’opzione ",["code","-f"]," è usata per seguire l’output di un file di testo in cui vengono scritti nuovi dati."]],["dt",["code","wc"]],["dd",["p","Abbreviazione di “word count”, ma a seconda dei parametri che si utilizzano conterà caratteri, parole e righe."]],["dt",["code","sort"]],["dd",["p","Utilizzato per organizzare l’output di un elenco in ordine alfabetico, in ordine alfabetico inverso o in ordine casuale."]],["dt",["code","uniq"]],["dd",["p","Utilizzato per elencare (e contare) stringhe uguali."]],["dt",["code","od"]],["dd",["p","Il comando \"octal dump\" viene utilizzato per visualizzare un file binario in notazione ottale, decimale o esadecimale."]],["dt",["code","nl"]],["dd",["p","Il comando “number line” visualizza il numero di linee in un file, oltre che a ricreare un file con ogni riga preceduta dal suo numero di riga."]],["dt",["code","sed"]],["dd",["p","L’editor di flusso può essere utilizzato per trovare occorrenze corrispondenti delle stringhe utilizzando Regular Expressions e per modificare i file utilizzando modelli predefiniti."]],["dt",["code","tr"]],["dd",["p","Il comando \"translate\" può sostituire i caratteri e rimuove e comprime i caratteri ricorrenti."]],["dt",["code","cut"]],["dd",["p","Questo comando può estrapolare parti di file di testo come fossero campi, se identificati da un delimitatore di caratteri."]],["dt",["code","paste"]],["dd",["p","Unisce i file in colonne in base all’uso dei separatori di campo."]],["dt",["code","split"]],["dd",["p","Questo comando può dividere file più grandi in file più piccoli a seconda dei criteri impostati dalle opzioni del comando."]],["dt",["code","md5sum"]],["dd",["p","Utilizzato per il calcolo del valore ",["em","hash"]," MD5 di un file. Utilizzato anche per verificare un file rispetto a un valore hash esistente per garantirne l’integrità."]],["dt",["code","sha256sum"]],["dd",["p","Utilizzato per il calcolo del valore hash SHA256 di un file. Utilizzato anche per verificare un file rispetto a un valore hash esistente per garantirne l’integrità."]],["dt",["code","sha512sum"]],["dd",["p","Utilizzato per il calcolo del valore hash SHA512 di un file. Utilizzato anche per verificare un file rispetto a un valore hash esistente per garantirne l’integrità."]]],["h2","Risposte agli Esercizi Guidati"],["ol",["li",["p","Qualcuno ha appena donato un laptop alla tua scuola e ora desideri installare Linux su di esso. Non esiste un manuale e sei stato costretto ad avviarlo senza interfaccia grafica da una chiavetta USB. Ottieni un terminale shell e sai che, per ogni processore, ci saranno una serie di riferimenti nel file ",["code","/proc/cpuinfo"],":"],"   ",["pre",["strong","processor\t: 0"],"\nvendor_id\t: GenuineIntel\ncpu family\t: 6\nmodel\t\t: 158\n\n(linee saltate)\n\n",["strong","processor\t: 1"],"\nvendor_id\t: GenuineIntel\ncpu family\t: 6\nmodel\t\t: 158\n\n(altre linee saltate)"],"    ",["ul",["li",["p","Usando i comandi ",["code","grep"]," e ",["code","wc"]," mostra quanti processori hai."],"  ",["p","Ecco due varianti:"],"    ",["pre","$ ",["strong","cat /proc/cpuinfo | grep processor | wc -l"],"\n$ ",["strong","grep processor /proc/cpuinfo | wc -l"]],"    ",["p","Ora che sai che ci sono diversi modi in cui puoi fare la stessa cosa, ma quando dovresti usare l’uno o l’altro? Dipende davvero da diversi fattori, i due più importanti sono le prestazioni e la leggibilità. La maggior parte delle volte utilizzerai i comandi della shell all’interno di script per automatizzare le tue attività e più grandi e complessi saranno gli script, più dovrai preoccuparti di mantenerli veloci."]],["li",["p","Fai la stessa cosa con ",["code","sed"]," invece di ",["code","grep"]],"  ",["p","Ora, invece di ",["code","grep"],", proveremo con ",["code","sed"],":"],"    ",["pre","$ ",["strong","sed -n /processor/p /proc/cpuinfo | wc -l"]],"    ",["p","Qui abbiamo usato ",["code","sed"]," con l’opzione ",["code","-n"]," in modo che ",["code","sed"]," non stamperà nulla tranne ciò che corrisponde all’espressione ",["code","processor"],", come indicato dal comando ",["code","p"],". Come abbiamo fatto con le soluzioni ",["code","grep"],", ",["code","wc -l"]," conterà il numero di linee, quindi il numero di processori che abbiamo."],"   ",["p","Studia il prossimo esempio:"],"    ",["pre","$ ",["strong","sed -n /processor/p /proc/cpuinfo | sed -n '$='"]],"    ",["p","Questa sequenza di comandi fornisce risultati identici all’esempio precedente in cui l’output di ",["code","sed"]," è stato reindirizzato al comando ",["code","wc"],". La differenza qui è che invece di usare ",["code","wc -l"]," per contare il numero di righe, ",["code","sed"]," viene nuovamente invocato per fornire funzionalità equivalenti. Ancora una volta, stiamo sopprimendo l’output di ",["code","sed"]," con l’opzione ",["code","-n"],", ad eccezione dell’espressione che stiamo esplicitamente chiamando, che è ",["code","'$='"],". Questa espressione dice a ",["code","sed"]," di trovare l’ultima riga (",["code","$"],") e quindi di visualizzarne il numero relativo (",["code","="],")."]]]],["li",["p","Esplora il tuo file locale ",["code","/etc/passwd"]," con i comandi ",["code","grep"],", ",["code","sed"],", ",["code","head"]," e ",["code","tail"]," per le attività seguenti:"],"  ",["ul",["li",["p","Quali utenti hanno accesso a una shell Bash?"],"   ",["pre","$ ",["strong","grep \":/bin/bash$\" /etc/passwd"]],"    ",["p","Miglioreremo questa risposta visualizzando solo il nome dell’utente che utilizza la shell Bash."],"    ",["pre","$ ",["strong","grep \":/bin/bash$\" /etc/passwd | cut -d: -f1"]],"    ",["p","Il nome utente è il primo campo (parametro ",["code","-f1"]," del comando ",["code","cut"],") e il file ",["code","/etc/passwd"]," usa ",["code",":"]," come separatore (parametro ",["code","-d:"]," del comando ",["code","cut"],") così basta reindirizzare l’output del comando ",["code","grep"]," al comando ",["code","cut"]," appropriato."]],["li",["p","Il tuo sistema ha vari utenti per gestire programmi specifici o per scopi amministrativi. Non hanno accesso a una shell. Quanti ne esistono nel tuo sistema?"],"  ",["p","Il modo più semplice per trovarli è stampare le righe per gli account che non usano la shell Bash:"],"    ",["pre","$ ",["strong","grep -v \":/bin/bash$\" /etc/passwd | wc -l"]]],["li",["p","Quanti utenti e gruppi esistono nel tuo sistema (ricorda: usa solo il file ",["code","/etc/passwd"],")"],"  ",["p","Il primo campo di una determinata riga nel file ",["code","/etc/passwd"]," è il nome utente, il secondo è in genere una ",["code","x"]," che indica che la password dell’utente non è memorizzata qui (è crittografata nel file ",["code","/etc/shadow"]," ). Il terzo è l’id utente (UID) e il quarto è l’id gruppo (GID). Quindi questo dovrebbe darci il numero di utenti:"],"    ",["pre","$ ",["strong","cut -d: -f3 /etc/passwd | wc -l"]],"    ",["p","Bene, il più delle volte questo dovrebbe bastare. Tuttavia, ci sono situazioni in cui imposterai diversi super utenti o altri tipi speciali di utenti che condividono lo stesso UID (ID utente). Quindi, per essere al sicuro, inoltreremo il risultato del nostro comando ",["code","cut"]," al comando ",["code","sort"]," e poi conteremo il numero di righe."],"    ",["pre","$ ",["strong","cut -d: -f3 /etc/passwd | sort -u | wc -l"]],"    ",["p","Ora, il numero di gruppi:"],"    ",["pre","$ ",["strong","cut -d: -f4 /etc/passwd | sort -u | wc -l"]]],["li",["p","Elenca solo la prima riga, l’ultima riga e la decima riga del tuo file ",["code","/etc/passwd"]],"  ",["p","Questo si realizzerà attraverso:"],"    ",["pre","$ ",["strong","sed -n -e '1'p -e '10'p -e '$'p /etc/passwd"]],"    ",["p","Ricorda che il parametro ",["code","-n"]," dice a ",["code","sed"]," di non stampare altro che ciò che è specificato dal parametro ",["code","p"],". Il simbolo del dollaro (",["code","$"],") usato nell’esempio indica l’ultima riga del file."]]]],["li",["p","Considera questo esempio di file ",["code","/etc/passwd"],". Copia le righe seguenti in un file locale chiamato ",["code","mypasswd"]," per questo esercizio."],"   ",["pre","root:x:0:0:root:/root:/bin/bash\ndaemon:x:1:1:daemon:/usr/sbin:/usr/sbin/nologin\nbin:x:2:2:bin:/bin:/usr/sbin/nologin\nsys:x:3:3:sys:/dev:/usr/sbin/nologin\nsync:x:4:65534:sync:/bin:/bin/sync\nnvidia-persistenced:x:121:128:NVIDIA Persistence Daemon,,,:/nonexistent:/sbin/nologin\nlibvirt-qemu:x:64055:130:Libvirt Qemu,,,:/var/lib/libvirt:/usr/sbin/nologin\nlibvirt-dnsmasq:x:122:133:Libvirt Dnsmasq,,,:/var/lib/libvirt/dnsmasq:/usr/sbin/nologin\ncarol:x:1000:2000:Carol Smith,Finance,,,Main Office:/home/carol:/bin/bash\ndave:x:1001:1000:Dave Edwards,Finance,,,Main Office:/home/dave:/bin/ksh\nemma:x:1002:1000:Emma Jones,Finance,,,Main Office:/home/emma:/bin/bash\nfrank:x:1003:1000:Frank Cassidy,Finance,,,Main Office:/home/frank:/bin/bash\ngrace:x:1004:1000:Grace Kearns,Engineering,,,Main Office:/home/grace:/bin/ksh\nhenry:x:1005:1000:Henry Adams,Sales,,,Main Office:/home/henry:/bin/bash\njohn:x:1006:1000:John Chapel,Sales,,,Main Office:/home/john:/bin/bash"],"    ",["ul",["li",["p","Elenca tutti gli utenti nel gruppo ",["code","1000"]," (usa ",["code","sed"]," per selezionare solo il campo appropriato) dal tuo file ",["code","mypasswd"],"."],"  ",["p","Il GID è il quarto campo nel file ",["code","/etc/passwd"],". Potresti essere tentato di provare questo:"],"    ",["pre","$ ",["strong","sed -n /1000/p mypasswd"]],"    ",["p","In questo caso otterrai anche questa riga:"],"    ",["pre","carol:x:1000:2000:Carol Smith,Finance,,,Main Office:/home/carol:/bin/bash"],"    ",["p","Sai che questo non è corretto poiché Carol Smith è un membro del GID 2000 e la corrispondenza è avvenuta a causa dell’UID. Tuttavia, potresti aver notato che dopo il GID il campo successivo inizia con un carattere maiuscolo. Possiamo usare un’espressione regolare per risolvere questo problema."],"    ",["pre","$ ",["strong","sed -n /:1000:[A-Z]/p mypasswd"]],"    ",["p","L’espressione ",["code","[A-Z]"]," corrisponderà a ogni singolo carattere maiuscolo. Imparerai di più al riguardo nella lezione dedicata."]],["li",["p","Elenca solo i nomi completi di tutti gli utenti per questo gruppo (usa ",["code","sed"]," e ",["code","cut"],"):"],"  ",["p","Usa la stessa tecnica che hai usato per risolvere la prima parte di questo esercizio e inoltralo a un comando ",["code","cut"],"."],"    ",["pre","$ ",["strong","sed -n /:1000:[A-Z]/p mypasswd | cut -d: -f5"],"\nDave Edwards,Finance,,,Main Office\nEmma Jones,Finance,,,Main Office\nFrank Cassidy,Finance,,,Main Office\nGrace Kearns,Engineering,,,Main Office\nHenry Adams,Sales,,,Main Office\nJohn Chapel,Sales,,,Main Office"],"    ",["p","Non ci siamo ancora! Nota come i campi all’interno dei tuoi risultati possono essere separati da ",["code",","],". Quindi reindirizzeremo l’output ad un altro comando ",["code","cut"],", usando ",["code",","]," come delimitatore."],"    ",["pre","$ ",["strong","sed -n /:1000:[A-Z]/p mypasswd | cut -d: -f5 | cut -d, -f1"],"\nDave Edwards\nEmma Jones\nFrank Cassidy\nGrace Kearns\nHenry Adams\nJohn Chapel"]]]]],["h2","Risposte agli Esercizi Esplorativi"],["ol",["li",["p","Ancora una volta usando il file ",["code","mypasswd"]," degli esercizi precedenti, crea un comando Bash che selezionerà un individuo dal Main Office per vincere una lotteria. Usa il comando ",["code","sed"]," per stampare solo le righe per il Main Office, e poi una sequenza di comandi ",["code","cut"]," per recuperare il primo nome di ogni utente da queste righe. Successivamente dovrai ordinare in modo casuale questi nomi e stampare solo il nome superiore dall’elenco."],"  ",["p","Prima esplora come l’opzione ",["code","-R"]," manipoli l’output del comando ",["code","sort"],". Ripeti questo comando un paio di volte sulla tua macchina (nota che dovrai racchiudere 'Main Office' tra virgolette singole, quindi ",["code","sed"]," lo gestirà come una singola stringa):"],"    ",["pre","$ ",["strong","sed -n /'Main Office'/p mypasswd | cut -d: -f5 | cut -d, -f1 | sort -R"]],"    ",["p","Ecco la soluzione al tuo problema:"],"    ",["pre","$ ",["strong","sed -n /'Main Office'/p mypasswd | cut -d: -f5 | cut -d, -f1 | sort -R | head -1"]]],["li",["p","Quante persone lavorano in Finance, Engineering e Sales? (Prova a utilizzare il comando ",["code","uniq"],".)"],"  ",["p","Continua a sviluppare ciò che hai imparato dagli esercizi precedenti. Prova quanto segue:"],"    ",["pre","$ ",["strong","sed -n /'Main Office'/p mypasswd"],"\n$ ",["strong","sed -n /'Main Office'/p mypasswd | cut -d, -f2"]],"    ",["p","Nota ora che non ci interessa il delimitatore ",["code",":"],". Vogliamo solo il secondo campo quando dividiamo le righe con i caratteri \",\"."],"    ",["pre","$ ",["strong","sed -n /'Main Office'/p mypasswd | cut -d, -f2 | uniq -c"],"\n      4 Finance\n      1 Engineering\n      2 Sales"],"    ",["p","Il comando ",["code","uniq"]," produrrà solo le righe uniche (non le righe ripetute) e il parametro ",["code","-c"]," dice a ",["code","uniq"]," di contare le occorrenze delle righe uguali. C’è un avvertimento qui: ",["code","uniq"]," prenderà in considerazione solo le linee adiacenti. Quando questo non sarà il caso, dovrai usare il comando ",["code","sort"],"."]],["li",["p","Ora vuoi preparare un file CSV (valori separati da virgola) in modo da poter importare facilmente, dal file ",["code","mypasswd"]," nell’esempio precedente, il file ",["code","names.csv"]," in LibreOffice. Il contenuto del file avrà il seguente formato:"],"   ",["pre","First Name,Last Name,Position\nCarol,Smith,Finance\n...\nJohn,Chapel,Sales"],"    ",["p","Suggerimento: usa i comandi ",["code","sed"],", ",["code","cut"]," e ",["code","paste"]," per ottenere i risultati desiderati. Nota che la virgola (,) sarà il delimitatore per questo file."],"   ",["p","Inizia con i comandi ",["code","sed"]," e ",["code","cut"],", partendo da ciò che abbiamo imparato dagli esercizi precedenti:"],"    ",["pre","$ ",["strong","sed -n /'Main Office'/p mypasswd | cut -d: -f5 | cut -d\" \" -f1 > firstname"]],"    ",["p","Ora abbiamo il file ",["code","firstname"]," con i nomi dei nostri dipendenti."],"    ",["pre","$ ",["strong","sed -n /'Main Office'/p mypasswd | cut -d: -f5 | cut -d\" \" -f2 | cut -d, -f1 > lastname"]],"    ",["p","Ora abbiamo il file ",["code","lastname"]," contenente i cognomi di ogni dipendente."],"   ",["p","Successivamente determiniamo in quale reparto lavora ogni dipendente:"],"    ",["pre","$ ",["strong","sed -n /'Main Office'/p mypasswd | cut -d: -f5 | cut -d, -f2 > department"]],"    ",["p","Prima di lavorare alla soluzione finale, prova i seguenti comandi per vedere che tipo di output generano:"],"    ",["pre","$ ",["strong","cat firstname lastname department"],"\n$ ",["strong","paste firstname lastname department"]],"    ",["p","E ora per la soluzione finale:"],"    ",["pre","$ ",["strong","paste firstname lastname department | tr '\\t' ,"],"\n$ ",["strong","paste firstname lastname department | tr '\\t' , > names.csv"]],"    ",["p","Qui usiamo il comando ",["code","tr"]," per “translate” ",["code","\\t"],", il separatore di tabulazione, con un ",["code",","],". ",["code","tr"]," è molto utile quando dobbiamo sostituire un carattere con un altro. Assicurati di rivedere le pagine man sia per ",["code","tr"]," che per ",["code","paste"],". Per esempio, possiamo usare l’opzione ",["code","-d"]," per il delimitatore, per rendere meno complesso il comando precedente:"],"    ",["pre","$ ",["strong","paste -d, firstname lastname department"]],"    ",["p","Abbiamo usato il comando ",["code","paste"]," già una volta per familiarizzare con esso. Tuttavia avremmo potuto eseguire facilmente tutte le attività in una singola catena di comandi:"],"    ",["pre","$ ",["strong","sed -n /'Main Office'/p mypasswd | cut -d: -f5 | cut -d, -f1,2 | tr ' ' , > names.csv"]]],["li",["p","Supponiamo che il foglio di calcolo ",["code","names.csv"]," creato nell’esercizio precedente sia un file importante e vogliamo assicurarci che nessuno lo manometterà dal momento in cui lo inviamo a qualcuno fino a quando il nostro destinatario lo riceverà. Come possiamo assicurare l’integrità di questo file usando ",["code","md5sum"],"?"],"  ",["p","Se guardi nelle pagine man di ",["code","md5sum"],", ",["code","sha256sum"]," e ",["code","sha512sum"]," vedrai che iniziano tutte con il seguente testo:"],"   ",["p","“compute and check XXX message digest”"],"   ",["p","Dove “XXX” è l’algoritmo che verrà utilizzato per creare questo messaggio ",["em","digest"],"."],"   ",["p","Useremo ",["code","md5sum"]," come esempio e successivamente potrai provare con gli altri comandi."],"    ",["pre","$ ",["strong","md5sum names.csv"],"\n61f0251fcab61d9575b1d0cbf0195e25  names.csv"],"    ",["p","Ora, per esempio, puoi rendere disponibile il file tramite un servizio ftp sicuro e inviare il ",["em","message digest"]," generato utilizzando un altro mezzo di comunicazione sicuro. Se il file è stato in qualche modo alterato, il ",["em","message digest"]," sarà completamente diverso. Solo per dimostrarlo, modifica ",["code","names.csv"]," e cambia Jones in James come dimostrato qui:"],"    ",["pre","$ ",["strong","sed -i.backup s/Jones/James/ names.csv"],"\n$ ",["strong","md5sum names.csv"],"\nf44a0d68cb480466099021bf6d6d2e65  names.csv"],"    ",["p","Ogni volta che rendi i file disponibili per il download, è sempre buona norma distribuire anche un corrispondente ",["em","message digest"]," in modo che le persone che scaricano il tuo file possano produrre un nuovo ",["em","message digest"]," e confrontarlo con l’originale. Se navighi su ",["a","https://kernel.org","https://kernel.org"]," troverai la pagina ",["a","https://mirrors.edge.kernel.org/pub/linux/kernel/v5.x/sha256sums.asc","https://mirrors.edge.kernel.org/pub/linux/kernel/v5.x/sha256sums.asc"]," dove puoi ottenere lo sha256sum per tutti i file disponibili per il download."]],["li",["p","Ti sei ripromesso di leggere cento righe di un testo classico al giorno e hai deciso di iniziare con ",["em","Mariner and Mystic"]," di Herman Melville. Elabora un comando usando ",["code","split"]," che separerà questo libro in sezioni di 100 righe ciascuna. Per ottenere il libro in formato testo normale, cercalo su ",["a","https://www.gutenberg.org","https://www.gutenberg.org"],"."],"  ",["p","Per prima cosa otterremo l’intero libro dal sito di Project Gutenberg, dove è possibile ottenere questo e altri libri di pubblico dominio."],"    ",["pre","$ ",["strong","wget https://www.gutenberg.org/files/50461/50461-0.txt"]],"    ",["p","Potrebbe essere necessario installare ",["code","wget"]," se non è già installato nel tuo sistema. In alternativa, puoi anche usare ",["code","curl"],". Usa ",["code","less"]," per verificare il libro:"],"    ",["pre","$ ",["strong","less 50461-0.txt"]],"    ",["p","Ora divideremo il libro in blocchi di 100 righe ciascuno:"],"    ",["pre","$ ",["strong","split -l 100 -d 50461-0.txt melville"]],"    ",["p",["code","50461-0.txt"]," è il file che divideremo. ",["code","melville"]," sarà il prefisso del nome per i file divisi. ",["code","-L 100"]," specifica il numero di righe e l’opzione ",["code","-d"]," dice a ",["code","split"]," di numerare i file attraverso un suffisso. Puoi usare ",["code","nl"]," su uno qualsiasi dei file divisi (probabilmente non sull’ultimo) e confermare che ognuno di essi abbia 100 righe."]],["li",["p","Usando ",["code","ls -l"]," nella directory ",["code","/etc"],", che tipo di elenco ottieni? Usando il comando ",["code","cut"]," sull’output del comando ",["code","ls"]," come visualizzeresti solo i nomi dei file? E come il nome del file e del proprietario dei file? Insieme ai comandi ",["code","ls -l"]," e ",["code","cut"],", usa il comando ",["code","tr"]," per ",["em","sostituire"]," più occorrenze di uno spazio con un singolo spazio per aiutare a formattare l’output generato da un comando ",["code","cut"],"."],"  ",["p","Il comando ",["code","ls"]," darà solo i nomi dei file. Possiamo, tuttavia, elaborare l’output di ",["code","ls -l"]," (lunga lista) per estrarre informazioni più specifiche."],"    ",["pre","$ ",["strong","ls -l /etc | tr -s ' ' ,"],"\ndrwxr-xr-x,3,root,root,4096,out,24,16:58,acpi\n-rw-r--r--,1,root,root,3028,dez,17,2018,adduser.conf\n-rw-r--r--,1,root,root,10,out,2,17:38,adjtime\ndrwxr-xr-x,2,root,root,12288,out,31,09:40,alternatives\n-rw-r--r--,1,root,root,401,mai,29,2017,anacrontab\n-rw-r--r--,1,root,root,433,out,1,2017,apg.conf\ndrwxr-xr-x,6,root,root,4096,dez,17,2018,apm\ndrwxr-xr-x,3,root,root,4096,out,24,16:58,apparmor\ndrwxr-xr-x,9,root,root,4096,nov,6,20:20,apparmor.d"],"    ",["p","L’opzione ",["code","-s"]," indica a ",["code","tr"]," di ridurre gli spazi ripetuti in un singolo spazio. Il comando ",["code","tr"]," funziona per qualsiasi tipo di carattere ripetitivo specificato. Quindi sostituiamo gli spazi con una virgola ",["code",","],". In realtà non abbiamo bisogno di sostituire gli spazi nel nostro esempio, quindi ometteremo ",["code",","],"."],"    ",["pre","$ ",["strong","ls -l /etc | tr -s ' '"],"\ndrwxr-xr-x 3 root root 4096 out 24 16:58 acpi\n-rw-r--r-- 1 root root 3028 dez 17 2018 adduser.conf\n-rw-r--r-- 1 root root 10 out 2 17:38 adjtime\ndrwxr-xr-x 2 root root 12288 out 31 09:40 alternatives\n-rw-r--r-- 1 root root 401 mai 29 2017 anacrontab\n-rw-r--r-- 1 root root 433 out 1 2017 apg.conf\ndrwxr-xr-x 6 root root 4096 dez 17 2018 apm\ndrwxr-xr-x 3 root root 4096 out 24 16:58 apparmor"],"    ",["p","Se voglio solo i nomi dei file, tutto ciò di cui abbiamo bisogno è il nono campo:"],"    ",["pre","$ ",["strong","ls -l /etc | tr -s ' ' | cut -d\" \" -f9"]],"    ",["p","Per il nome file e il proprietario di un file avremo bisogno del nono e del terzo campo:"],"    ",["pre","$ ",["strong","ls -l /etc | tr -s ' ' | cut -d\" \" -f9,3"]],"    ",["p","E se avessimo solo bisogno dei nomi delle cartelle e del loro proprietario?"],"    ",["pre","$ ",["strong","ls -l /etc | grep ^d | tr -s ' ' | cut -d\" \" -f9,3"]]],["li",["p","Questo esercizio presuppone che tu sia su una macchina reale (non una macchina virtuale). Devi anche avere una chiavetta USB con te. Esamina le pagine del manuale per il comando ",["code","tail"]," e scopri come ",["em","seguire"]," un file mentre il testo viene aggiunto ad esso. Durante il monitoraggio dell’output di un comando ",["code","tail"]," sul file ",["code","/var/log/syslog"],", inserire una chiavetta USB. Scrivi il comando completo che utilizzeresti per ottenere ",["em","Product"],", ",["em","Manufacturer"]," e ",["em","total amount of memory"]," della tua chiavetta USB."],"   ",["pre","$ ",["strong","tail -f /var/log/syslog | grep -i 'product\\:\\|blocks\\|manufacturer'"],"\nNov  8 06:01:35 brod-avell kernel: [124954.369361] usb 1-4.3: Product: Cruzer Blade\nNov  8 06:01:35 brod-avell kernel: [124954.369364] usb 1-4.3: Manufacturer: SanDisk\nNov  8 06:01:37 brod-avell kernel: [124955.419267] sd 2:0:0:0: [sdc] 61056064 512-byte logical blocks: (31.3 GB/29.1 GiB)"],"    ",["p","Ovviamente questo è un esempio e i risultati possono variare a seconda del produttore della memory stick USB. Notate ora che usiamo il parametro ",["code","-i"]," con il comando ",["code","grep"]," poiché non siamo sicuri che le stringhe, che stiamo cercando, siano in maiuscolo o minuscolo. Abbiamo anche usato ",["code","|"]," come OR logico, quindi cerchiamo le linee che contengono ",["code","product"]," o ",["code","blocks"]," o ",["code","manufacturer"],"."]]]]},{"id":"103.4_01","objective":"103.4","title":"103.4 Lezione 1","url":"https://learning.lpi.org/it/learning-materials/101-500/103/103.4/103.4_01/","notice":"Linux Professional Institute Inc. Tutti i diritti riservati. Visita il sito Learning Materials: https://learning.lpi.org Quest'opera è sotto la licenza 'Creative Commons Attribution-NonCommercial-NoDerivatives 4.0 International License'.","body":[["h1","103.4 Lezione 1"],["table",["tr",["th",["p","Certificazione:"]],["td",["p","LPIC-1 (101)"]]],["tr",["th",["p","Versione:"]],["td",["p","5.0"]]],["tr",["th",["p","Argomento:"]],["td",["p","103 Comandi GNU e Unix"]]],["tr",["th",["p","Obiettivo:"]],["td",["p","103.4 Utilizzare stream, pipe e reindirizzamenti"]]],["tr",["th",["p","Lezione:"]],["td",["p","1 di 2"]]]],["h2","Introduzione"],["p","Tutti i programmi per computer seguono lo stesso principio generale: i dati ricevuti da qualche fonte vengono trasformati per generare un risultato intelligibile. Nel contesto della shell di Linux, l’origine dati può essere un file locale, un file remoto, un dispositivo (come una tastiera), e altro ancora. L’output del programma viene solitamente visualizzato su uno schermo, ma è anche comune memorizzare i dati di output in un filesystem locale, inviarlo a un dispositivo remoto, riprodurlo tramite altoparlanti audio, ecc."],["p","I sistemi operativi ispirati a Unix, come Linux, offrono una grande varietà di metodi di input/output. In particolare il metodo dei ",["em","file descriptors"]," consente di associare dinamicamente numeri interi ai canali dati, in modo che un processo possa riferirli come propri flussi di dati di input/output."],["p","I processi Linux standard hanno tre canali di comunicazione aperti per impostazione predefinita: il canale ",["em","standard input"]," (il più delle volte chiamato semplicemente ",["em","stdin"],"), il canale ",["em","standard output"]," (",["em","stdout"],") e il canale ",["em","standard error"]," (",["em","stderr"],"). I descrittori di file numerici assegnati a questi canali sono ",["code","0"]," per ",["em","stdin"],", ",["code","1"]," per ",["em","stdout"]," e ",["code","2"]," per ",["em","stderr"],". I canali di comunicazione sono anche accessibili tramite i dispositivi speciali ",["code","/dev/stdin"],", ",["code","/dev/stdout"]," e ",["code","/dev/stderr"],"."],["p","Questi tre canali di comunicazione standard consentono ai programmatori di scrivere codice che legge e scrive dati senza preoccuparsi del tipo di supporto da cui provengono o a cui vanno. Per esempio, se un programma ha bisogno di un insieme di dati come input, può semplicemente chiedere i dati allo standard input e qualsiasi cosa venga utilizzata come standard input fornirà quei dati. Allo stesso modo, il metodo più semplice che un programma possa utilizzare per visualizzare il proprio output è scriverlo nell’output standard. In una sessione di shell standard, la tastiera è definita come ",["em","stdin"]," e lo schermo del monitor è definito come ",["em","stdout"]," e ",["em","stderr"],"."],["p","La shell Bash ha la capacità di riassegnare i canali di comunicazione durante il caricamento di un programma. Consente, per esempio, di sovrascrivere lo schermo come output standard e di utilizzare un file nel filesystem locale come ",["em","stdout"],"."],["h3","Reindirizzamenti"],["p","La riassegnazione del descrittore di file di un canale nell’ambiente della shell è chiamata ",["em","redirect"],". Un reindirizzamento è definito da un carattere speciale all’interno della riga di comando. Per esempio, per reindirizzare l’output standard di un processo su un file, il simbolo ",["em","maggiore di"]," ",["code",">"]," è posizionato alla fine del comando e seguito dal percorso del file che riceverà l’output reindirizzato:"],["pre","$ ",["strong","cat /proc/cpuinfo >/tmp/cpu.txt"]],["p","Per impostazione predefinita, viene reindirizzato solo il contenuto che arriva a ",["em","stdout"],". Ciò accade perché il valore numerico del descrittore di file deve essere specificato appena prima del simbolo ",["em","maggiore di"]," e, se non specificato, Bash reindirizza l’output standard. Pertanto, usare ",["code",">"]," equivale a usare ",["code","1>"]," (il valore del descrittore di file di ",["em","stdout"]," è ",["code","1"],")."],["p","Per catturare il contenuto di ",["em","stderr"],", si dovrebbe invece usare il reindirizzamento ",["code","2>"],". La maggior parte dei programmi da riga di comando invia informazioni di debug e messaggi di errore al canale di errore standard. È possibile, per esempio, catturare il messaggio di errore innescato da un tentativo di leggere un file inesistente:"],["pre","$ ",["strong","cat /proc/cpu_info 2>/tmp/error.txt"],"\n$ ",["strong","cat /tmp/error.txt"],"\ncat: /proc/cpu_info: No such file or directory"],["p","Sia ",["em","stdout"]," che ",["em","stderr"]," vengono reindirizzati alla stessa destinazione con ",["code","&>"]," o ",["code",">&"],". È importante non inserire spazi accanto alla ",["em","e commerciale"],", altrimenti Bash lo prenderà come istruzione per eseguire il processo in background e non per eseguire il reindirizzamento."],["p","La destinazione deve essere un percorso a un file scrivibile, come ",["code","/tmp/cpu.txt"],", o un descrittore di file scrivibile. La destinazione di un descrittore di file è rappresentata da una ",["em","e commerciale"]," seguita dal valore numerico del descrittore di file. Per esempio, ",["code","1>&2"]," reindirizza ",["em","stdout"]," a ",["em","stderr"],". Per fare l’opposto, da ",["em","stderr"]," a ",["em","stdout"],", dovrebbero essere usati ",["code","2>&1"],"."],["p","Sebbene non sia molto utile, dato che esiste un modo più breve per eseguire la stessa operazione, è possibile reindirizzare ",["em","stderr"]," a ",["em","stdout"]," e quindi reindirizzarlo a un file. Per esempio, un redirect per scrivere sia ",["em","stderr"]," che ",["em","stdout"]," in un file chiamato ",["code","log.txt"]," può essere scritto come ",["code",">log.txt 2>&1"],". Tuttavia, il motivo principale per reindirizzare ",["em","stderr"]," a ",["em","stdout"]," è consentire l’analisi dei messaggi di debug e di errore. È possibile reindirizzare lo standard output di un programma allo standard input di un altro programma, ma ",["em","non è"]," possibile reindirizzare direttamente lo standard error allo standard input di un altro programma. Pertanto, i messaggi del programma inviati a ",["em","stderr"]," devono prima essere reindirizzati a ",["em","stdout"]," per essere letti dallo ",["em","stdin"]," di un altro programma."],["p","Per scartare semplicemente l’output di un comando, il suo contenuto può essere reindirizzato al file speciale ",["code","/dev/null"],". Per esempio, ",["code",">log.txt 2>/dev/null"]," salva il contenuto di ",["em","stdout"]," nel file ",["code","log.txt"]," e scarta lo ",["em","stderr"],". Il file ",["code","/dev/null"]," è scrivibile da qualsiasi utente ma nessun dato può essere recuperato da esso, poiché non è memorizzato da nessuna parte."],["p","Viene visualizzato un messaggio di errore se la destinazione specificata non è scrivibile (se il percorso punta a una directory o a un file di sola lettura) e non viene apportata alcuna modifica alla destinazione. Tuttavia, un reindirizzamento dell’output sovrascrive una destinazione scrivibile esistente senza alcuna conferma. I file vengono sovrascritti dai reindirizzamenti di output a meno che non sia abilitata l’opzione Bash ",["code","noclobber"],", che può essere eseguita per la sessione corrente con il comando ",["code","set -o noclobber"]," o ",["code","set -C"],":"],["pre","$ ",["strong","set -o noclobber"],"\n$ ",["strong","cat /proc/cpu_info 2>/tmp/error.txt"],"\n-bash: /tmp/error.txt: cannot overwrite existing file"],["p","Per annullare l’impostazione dell’opzione ",["code","noclobber"]," per la sessione corrente, eseguire ",["code","set +o noclobber"]," o ",["code","set +C"],". Per rendere persistente l’opzione ",["code","noclobber"],", deve essere inclusa nel profilo Bash dell’utente o nel profilo a livello di sistema."],["p","Anche con l’opzione ",["code","noclobber"]," abilitata è possibile aggiungere dati reindirizzati a contenuto esistente. Ciò si ottiene con un reindirizzamento scritto con due simboli ",["em","maggiore di"]," ",["code",">>"],":"],["pre","$ ",["strong","cat /proc/cpu_info 2>>/tmp/error.txt"],"\n$ ",["strong","cat /tmp/error.txt"],"\ncat: /proc/cpu_info: No such file or directory\ncat: /proc/cpu_info: No such file or directory"],["p","Nell’esempio precedente, il nuovo messaggio di errore è stato aggiunto a quello esistente nel file ",["code","/tmp/error.txt"],". Se il file non esiste ancora, verrà creato con i nuovi dati."],["p","Anche l’origine dati dello standard input di un processo può essere riassegnata. Il simbolo ",["em","minore di"]," ",["code","<"]," viene utilizzato per reindirizzare il contenuto di un file allo ",["em","stdin"]," di un processo. In questo caso, i dati scorrono da destra a sinistra: si assume che il descrittore riassegnato sia 0 a sinistra del simbolo ",["em","minore di"]," e l’origine dati (un percorso di un file) deve essere a destra del simbolo ",["em","minore di"],". Il comando ",["code","uniq"],", come la maggior parte delle utilità della riga di comando per l’elaborazione del testo, accetta i dati inviati allo ",["em","stdin"]," per impostazione predefinita:"],["pre","$ ",["strong","uniq -c </tmp/error.txt"],"\n      2 cat: /proc/cpu_info: No such file or directory"],["p","L’opzione ",["code","-c"]," fa visualizzare a ",["code","uniq"]," quante volte una riga ripetuta appare nel testo. Poiché il valore numerico del descrittore di file reindirizzato è stato soppresso, il comando di esempio è equivalente a ",["code","uniq -c 0</tmp/error.txt"],". Usare un descrittore di file diverso da ",["code","0"]," in un reindirizzamento dell’input ha senso solo in contesti specifici, perché è possibile che un programma richieda dati ai descrittori di file ",["code","3"],", ",["code","4"]," e così via. Infatti, i programmi possono usare qualsiasi numero intero superiore a 2 come nuovi descrittori di file per l’input/output dei dati. Per esempio il seguente codice C legge i dati dal descrittore di file ",["code","3"]," e li replica semplicemente nel descrittore di file ",["code","4"],":"],["note","Nota",["p","Il programma deve gestire correttamente tali descrittori di file, altrimenti potrebbe tentare un’operazione di lettura o scrittura non valida con conseguente crash applicativo."]],["pre","#include <stdio.h>\n\nint main(int argc, char **argv){\n  FILE *fd_3, *fd_4;\n  // Open file descriptor 3\n  fd_3 = fdopen(3, \"r\");\n  // Open file descriptor 4\n  fd_4 = fdopen(4, \"w\");\n  // Read from file descriptor 3\n  char buf[32];\n  while ( fgets(buf, 32, fd_3) != NULL ){\n    // Write to file descriptor 4\n    fprintf(fd_4, \"%s\", buf);\n  }\n  // Close both file descriptors\n  fclose(fd_3);\n  fclose(fd_4);\n}"],["p","Per testarlo, salva il codice di esempio come ",["code","fd.c"]," e compilalo con ",["code","gcc -o fd fd.c"],". Questo programma richiede che i descrittori di file 3 e 4 siano disponibili in modo da poterli leggere e scrivere. Per esempio, il file precedentemente creato ",["code","/tmp/error.txt"]," può essere utilizzato come sorgente per il descrittore di file ",["code","3"]," e il descrittore di file ",["code","4"]," può essere reindirizzato a ",["em","stdout"],":"],["pre","$ ",["strong","./fd 3</tmp/error.txt 4>&1"],"\ncat: /proc/cpu_info: No such file or directory\ncat: /proc/cpu_info: No such file or directory"],["p","Dal punto di vista di un programmatore, l’uso di descrittori di file evita di dover gestire l’analisi delle opzioni e i percorsi del file system. Lo stesso descrittore di file può anche essere utilizzato come input e output. In questo caso, il descrittore di file è definito nella riga di comando con simboli sia ",["em","minore di"]," che ",["em","maggiore di"],", come in ",["code","3<>/tmp/error.txt"],"."],["h3","Here Document e Here String"],["p","Un altro modo per reindirizzare l’input coinvolge i metodi ",["em","Here document"]," e ",["em","Here string"],". Il reindirizzamento del ",["em","Here document"]," consente di digitare del testo su più righe che verrà utilizzato come contenuto reindirizzato. Due simboli ",["em","meno di"]," ",["code","<<"]," indicano un reindirizzamento del ",["em","Here document"],":"],["pre","$ ",["strong","wc -c <<EOF"],"\n> How many characters\n> in this Here document?\n> EOF\n43"],["p","A destra dei due simboli meno di ",["code","<<"]," è il termine di fine ",["code","EOF"],". La modalità di inserimento terminerà non appena verrà inserita una riga contenente solo il termine di fine. Qualsiasi altro termine può essere utilizzato come termine di fine, ma è importante non inserire caratteri vuoti tra il simbolo ",["em","minore di"]," e il termine di fine. Nell’esempio sopra, le due righe di testo sono state inviate allo ",["em","stdin"]," del comando ",["code","wc -c"],", che mostra il conteggio dei caratteri. Come per i reindirizzamenti di input per i file, viene assunto lo ",["em","stdin"]," (descrittore di file ",["code","0"],") se il descrittore di file reindirizzato viene soppresso."],["p","Il metodo Here string è molto simile al metodo ",["code","Here document"],", ma solo per una riga:"],["pre","$ wc -c <<< \"How many characters in this Here string?\"\n41"],["p","In questo esempio, la stringa viene inviata allo ",["em","stdin"]," di ",["code","wc -c"],", che conta il numero di caratteri. Le stringhe contenenti spazi devono essere racchiuse tra virgolette, altrimenti solo la prima parola verrà utilizzata come ",["code","Here string"]," e le restanti verranno passate come argomenti al comando."],["h2","Esercizi Guidati"],["ol",["li",["p","Oltre ai file di testo, il comando ",["code","cat"]," può funzionare anche con dati binari, come l’invio del contenuto di un dispositivo a blocchi a un file. Usando il reindirizzamento, come può ",["code","cat"]," inviare il contenuto del dispositivo ",["code","/dev/sdc"]," al file ",["code","sdc.img"]," nella directory corrente?"]," ",["table",["tr",["td"]]]],["li",["p","Qual è il nome del canale standard reindirizzato dal comando ",["code","date 1> now.txt"],"?"]," ",["table",["tr",["td"]]]],["li",["p","Dopo aver provato a sovrascrivere un file usando il reindirizzamento, un utente riceve un errore che informa che l’opzione ",["code","noclobber"]," è abilitata. Come si può disattivare l’opzione ",["code","noclobber"]," per la sessione corrente?"]," ",["table",["tr",["td"]]]],["li",["p","Quale sarà il risultato del comando ",["code","cat <<.>/dev/stdout"],"?"]," ",["table",["tr",["td"]]]]],["h2","Esercizi Esplorativi"],["ol",["li",["p","Il comando ",["code","cat /proc/cpu_info"]," mostra un messaggio di errore perché ",["code","/proc/cpu_info"]," è inesistente. Il comando ",["code","cat /proc/cpu_info 2>1"]," dove reindirizza il messaggio di errore?"]," ",["table",["tr",["td"]]]],["li",["p","Sarà ancora possibile scartare il contenuto inviato a ",["code","/dev/null"]," se l’opzione ",["code","noclobber"]," è abilitata per la sessione corrente della shell?"]," ",["table",["tr",["td"]]]],["li",["p","Utilizzando ",["code","echo"],", come è possibile reindirizzare il contenuto della variabile ",["code","$USER"]," allo stdin del comando ",["code","sha1sum"],"?"]," ",["table",["tr",["td"]]]],["li",["p","Il kernel Linux mantiene collegamenti simbolici in ",["code","/proc/PID/fd/"]," a ogni file aperto da un processo, dove ",["em","PID"]," è il numero di identificazione del processo corrispondente. Come potrebbe l’amministratore di sistema utilizzare quella directory per verificare la posizione dei file di log aperti da ",["code","nginx"],", supponendo che il suo PID sia ",["code","1234"],"?"]," ",["table",["tr",["td"]]]],["li",["p","È possibile eseguire calcoli aritmetici utilizzando solo i comandi incorporati della shell, ma i calcoli in virgola mobile richiedono programmi specifici, come ",["code","bc"]," (",["em","basic calculator"],"). Con ",["code","bc"]," è anche possibile specificare il numero di cifre decimali, con il parametro ",["code","scale"],". Tuttavia, ",["code","bc"]," accetta operazioni solo tramite il suo standard input, solitamente inserito in modalità interattiva. Usando una ",["em","Here string"],", come può l’operazione in virgola mobile ",["code","scale = 6; 1 / 3"]," essere inviato allo standard input di ",["code","bc"],"?"]," ",["table",["tr",["td"]]]]],["h2","Sommario"],["p","Questa lezione copre i metodi per eseguire un programma reindirizzando i suoi canali di comunicazione standard. I processi Linux utilizzano questi canali standard come descrittori di file generici per leggere e scrivere dati, rendendo possibile modificarli arbitrariamente in file o dispositivi. La lezione tratta i seguenti argomenti:"],["ul",["li",["p","Cosa sono i descrittori di file e il ruolo che svolgono in Linux."]],["li",["p","I canali di comunicazione standard di ogni processo: ",["em","stdin"],", ",["em","stdout"]," e ",["em","stderr"],"."]],["li",["p","Come eseguire correttamente un comando utilizzando il reindirizzamento dei dati, sia per l’input che per l’output."]],["li",["p","Come utilizzare ",["em","Here Documents"]," e ",["em","Here Strings"]," nei reindirizzamenti di input."]]],["p","I comandi e le procedure trattate erano:"],["ul",["li",["p","Operatori di Reindirizzamento: ",["code",">"],", ",["code","<"],", ",["code",">>"],", ",["code","<<"],", ",["code","<<<"],"."]],["li",["p","Commandi ",["code","cat"],", ",["code","set"],", ",["code","uniq"]," e ",["code","wc"],"."]]],["h2","Risposte agli Esercizi Guidati"],["ol",["li",["p","Oltre ai file di testo, il comando ",["code","cat"]," può funzionare anche con dati binari, come l’invio del contenuto di un dispositivo a blocchi a un file. Usando il reindirizzamento, come può ",["code","cat"]," inviare il contenuto del dispositivo ",["code","/dev/sdc"]," al file ",["code","sdc.img"]," nella directory corrente?"],"   ",["pre","$ ",["strong","cat /dev/sdc > sdc.img"]]],["li",["p","Qual è il nome del canale standard reindirizzato dal comando ",["code","date 1> now.txt"],"?"],"  ",["p","Standard output o ",["em","stdout"]]],["li",["p","Dopo aver provato a sovrascrivere un file usando il reindirizzamento, un utente riceve un errore che informa che l’opzione ",["code","noclobber"]," è abilitata. Come si può disattivare l’opzione ",["code","noclobber"]," per la sessione corrente?"],"  ",["p",["code","set +C"]," o ",["code","set +o noclobber"]]],["li",["p","Quale sarà il risultato del comando ",["code","cat <<.>/dev/stdout"],"?"],"  ",["p","Bash entrerà in modalità di immissione ",["em","Heredoc"],", quindi uscirà quando un punto appare in una riga da solo. Il testo digitato verrà reindirizzato a ",["em","stdout"]," (stampato sullo schermo)."]]],["h2","Risposte agli Esercizi Esplorativi"],["ol",["li",["p","Il comando ",["code","cat /proc/cpu_info"]," mostra un messaggio di errore perché ",["code","/proc/cpu_info"]," è inesistente. Il comando ",["code","cat /proc/cpu_info 2>1"]," dove reindirizza il messaggio di errore?"],"  ",["p","A un file chiamato ",["code","1"]," nella directory corrente."]],["li",["p","Sarà ancora possibile scartare il contenuto inviato a ",["code","/dev/null"]," se l’opzione ",["code","noclobber"]," è abilitata per la sessione corrente della shell?"],"  ",["p","Si. ",["code","/dev/null"]," è un file speciale non influenzato da ",["code","noclobber"],"."]],["li",["p","Utilizzando ",["code","echo"],", come è possibile reindirizzare il contenuto della variabile ",["code","$USER"]," allo stdin del comando ",["code","sha1sum"],"?"],"   ",["pre","$ ",["strong","echo -n \"$USER\" | sha1sum"]]],["li",["p","Il kernel Linux mantiene collegamenti simbolici in ",["code","/proc/PID/fd/"]," a ogni file aperto da un processo, dove ",["em","PID"]," è il numero di identificazione del processo corrispondente. Come potrebbe l’amministratore di sistema utilizzare quella directory per verificare la posizione dei file di log aperti da ",["code","nginx"],", supponendo che il suo PID sia ",["code","1234"],"?"],"  ",["p","Eseguendo il comando ",["code","ls -l /proc/1234/fd"],", che mostrerà le destinazioni di ogni collegamento simbolico nella directory."]],["li",["p","È possibile eseguire calcoli aritmetici utilizzando solo i comandi incorporati della shell, ma i calcoli in virgola mobile richiedono programmi specifici, come ",["code","bc"]," (",["em","basic calculator"],"). Con ",["code","bc"]," è anche possibile specificare il numero di cifre decimali, con il parametro ",["code","scale"],". Tuttavia, ",["code","bc"]," accetta operazioni solo tramite il suo standard input, solitamente inserito in modalità interattiva. Usando una ",["em","Here string"],", come può l’operazione in virgola mobile ",["code","scale = 6; 1 / 3"]," essere inviato allo standard input di ",["code","bc"],"?"],"   ",["pre","$ ",["strong","bc <<<\"scale=6; 1/3\""]]]]]},{"id":"103.4_02","objective":"103.4","title":"103.4 Lezione 2","url":"https://learning.lpi.org/it/learning-materials/101-500/103/103.4/103.4_02/","notice":"Linux Professional Institute Inc. Tutti i diritti riservati. Visita il sito Learning Materials: https://learning.lpi.org Quest'opera è sotto la licenza 'Creative Commons Attribution-NonCommercial-NoDerivatives 4.0 International License'.","body":[["h1","103.4 Lezione 2"],["table",["tr",["th",["p","Certificazione:"]],["td",["p","LPIC-1 (101)"]]],["tr",["th",["p","Versione:"]],["td",["p","5.0"]]],["tr",["th",["p","Argomento:"]],["td",["p","103 I Comandi GNU e Unix"]]],["tr",["th",["p","Obiettivo:"]],["td",["p","103.4 Utilizzare stream, pipe e reindirizzamenti"]]],["tr",["th",["p","Lezione:"]],["td",["p","2 di 2"]]]],["h2","Introduzione"],["p","Un principio della filosofia Unix afferma che ogni programma dovrebbe avere uno scopo specifico e non dovrebbe cercare di incorporare funzionalità al di fuori del suo ambito. Ma mantenere le cose semplici non significa risultati meno elaborati, perché diversi programmi possono essere concatenati insieme per produrre un output combinato. Il carattere della barra verticale ",["code","|"],", noto anche come simbolo ",["em","pipe"],", può essere utilizzato per creare una pipeline che collega l’output di un programma direttamente all’ingresso di un altro programma, mentre la ",["em","command substitution"]," consente di memorizzare l’output di un programma in una variabile oppure usarlo direttamente come argomento per un altro comando."],["h3","Le Pipe"],["p","A differenza dei reindirizzamenti, con le pipe i dati fluiscono da sinistra a destra nella riga di comando e l’obiettivo è un altro processo, non un percorso del file system, un descrittore di file o un ",["em","Here document"],". Il carattere pipe ",["code","|"]," dice alla shell di avviare tutti i comandi distintamente e di collegare l’output del comando precedente all’input del comando successivo, da sinistra a destra. Per esempio, invece di usare i redirect, il contenuto del file ",["code","/proc/cpuinfo"]," inviato allo standard output da ",["code","cat"]," può essere reindirizzato allo ",["em","stdin"]," di ",["code","wc"]," con il seguente comando:"],["pre","$ ",["strong","cat /proc/cpuinfo | wc"],"\n   208    1184    6096"],["p","In assenza di un percorso a un file, ",["code","wc"]," conta il numero di righe, parole e caratteri che riceve sul suo ",["em","stdin"],", come nel caso dell’esempio. Molte pipe possono essere presenti in un comando composto. Nell’esempio seguente vengono utilizzate due pipe:"],["pre","$ ",["strong","cat /proc/cpuinfo | grep 'model name' | uniq"],"\nmodel name      : Intel(R) Xeon(R) CPU           X5355  @ 2.66GHz"],["p","Il contenuto del file ",["code","/proc/cpuinfo"]," prodotto da ",["code","cat /proc/cpuinfo"]," è stato reindirizzato al comando ",["code","grep 'model name'"],", che quindi seleziona solo le righe contenenti il termine ",["code","model name"],". Il sistema che esegue l’esempio ha molte CPU, quindi ci sono righe ripetute con ",["code","model name"],". L’ultima pipe collega ",["code","grep 'model name'"]," a ",["code","uniq"],", che si preoccuperà di eliminare qualsiasi riga uguale alla precedente."],["p","Le pipe possono essere combinate con i reindirizzamenti nella stessa riga di comando. L’esempio precedente può essere riscritto in una forma più semplice:"],["pre","$ ",["strong","grep 'model name' </proc/cpuinfo | uniq"],"\nmodel name      : Intel(R) Xeon(R) CPU           X5355  @ 2.66GHz"],["p","Il reindirizzamento dell’input per ",["code","grep"]," non è strettamente necessario in quanto ",["code","grep"]," accetta un percorso di file come argomento, ma l’esempio dimostra come costruire tali comandi combinati."],["p","Le pipe e i reindirizzamenti sono esclusivi, ovvero una sorgente può essere mappata su una sola destinazione. Tuttavia, è possibile reindirizzare un output su un file e vederlo ancora sullo schermo con il programma ",["code","tee"],". Per farlo, il primo programma invia il suo output allo ",["em","stdin"]," di ",["code","tee"]," e a quest’ultimo viene fornito un nome di file dove memorizzare i dati:"],["pre","$ ",["strong","grep 'model name' </proc/cpuinfo | uniq | tee cpu_model.txt"],"\nmodel name      : Intel(R) Xeon(R) CPU           X5355  @ 2.66GHz\n$ ",["strong","cat cpu_model.txt"],"\nmodel name      : Intel(R) Xeon(R) CPU           X5355  @ 2.66GHz"],["p","L’output dell’ultimo programma della catena, generato da ",["code","uniq"],", viene visualizzato e memorizzato nel file ",["code","cpu_model.txt"],". Per non sovrascrivere il contenuto del file fornito ma per aggiungere dati a esso, l’opzione ",["code","-a"]," deve essere fornita a ",["code","tee"],"."],["p","Solo l’output standard di un processo viene catturato da una pipe. Supponiamo che sia necessario eseguire un lungo processo di compilazione sullo schermo e allo stesso tempo salvare sia lo standard output che lo standard error in un file per un’ispezione successiva. Supponendo che la tua directory corrente non abbia un ",["em","Makefile"],", il seguente comando restituirà un errore:"],["pre","$ ",["strong","make | tee log.txt"],"\nmake: *** No targets specified and no makefile found.  Stop."],["p","Sebbene mostrato sullo schermo, il messaggio di errore generato da ",["code","make"]," non è stato catturato da ",["code","tee"]," e il file ",["em","log.txt"]," è stato creato vuoto. È necessario eseguire un reindirizzamento prima che una pipe possa acquisire lo ",["em","stderr"],":"],["pre","$ ",["strong","make 2>&1 | tee log.txt"],"\nmake: *** No targets specified and no makefile found.  Stop.\n$ ",["strong","cat log.txt"],"\nmake: *** No targets specified and no makefile found.  Stop."],["p","In questo esempio lo ",["em","stderr"]," di ",["code","make"]," è stato reindirizzato allo ",["em","stdout"],", quindi ",["code","tee"]," è stato in grado di catturarlo con una pipe, visualizzarlo sullo schermo e salvarlo nel file ",["code","log.txt"],". In casi come questo, può essere utile salvare i messaggi di errore per un controllo successivo."],["h3","Sostituzione dei Comandi"],["p","Un altro metodo per catturare l’output di un comando è attraverso la ",["em","command substitution"],". Inserendo un comando all’interno delle virgolette ",["em","``"],", Bash lo sostituisce con il suo output standard. L’esempio seguente mostra come utilizzare lo ",["em","stdout"]," di un programma come argomento per un altro programma:"],["pre","$ ",["strong","mkdir `date +%Y-%m-%d`"],"\n$ ",["strong","ls"],"\n2019-09-05"],["p","L’output del programma ",["code","date"],", la data corrente formattata come ",["em","year-month-day"],", è stato usato come argomento per creare una directory con ",["code","mkdir"],". Un risultato identico si ottiene usando ",["code","$()"]," invece delle virgolette"],["pre","$ ",["strong","rmdir 2019-09-05"],"\n$ ",["strong","mkdir $(date +%Y-%m-%d)"],"\n$ ",["strong","ls"],"\n2019-09-05"],["p","Lo stesso metodo può essere utilizzato per memorizzare l’output di un comando come variabile:"],["pre","$ ",["strong","OS=`uname -o`"],"\n$ ",["strong","echo $OS"],"\nGNU/Linux"],["p","Il comando ",["code","uname -o"]," restituisce il nome generico del sistema operativo corrente, che è stato memorizzato nella variabile di sessione ",["code","OS"],". Assegnare l’output di un comando a una variabile è molto utile negli script, poiché consente di memorizzare e valutare i dati in molti modi distinti."],["p","A seconda dell’output generato dal comando sostituito, la sostituzione del comando integrato potrebbe non essere appropriata. Un metodo più sofisticato per usare l’output di un programma come argomento di un altro programma impiega un intermedio chiamato ",["code","xargs"],". Il programma ",["code","xargs"]," usa il contenuto che riceve tramite ",["em","stdin"]," per eseguire un dato comando con il contenuto come argomento. Il seguente esempio mostra ",["code","xargs"]," che esegue il programma ",["code","identify"]," con gli argomenti forniti dal programma ",["code","find"],":"],["pre","$ ",["strong","find /usr/share/icons -name 'debian*' | xargs identify -format \"%f: %wx%h\\n\""],"\ndebian-swirl.svg: 48x48\ndebian-swirl.png: 22x22\ndebian-swirl.png: 32x32\ndebian-swirl.png: 256x256\ndebian-swirl.png: 48x48\ndebian-swirl.png: 16x16\ndebian-swirl.png: 24x24\ndebian-swirl.svg: 48x48"],["p","Il programma ",["code","identify"]," fa parte di ",["em","ImageMagick"],", un insieme di strumenti a riga di comando per ispezionare, convertire e modificare la maggior parte dei tipi di file immagine. Nell’esempio, ",["code","xargs"]," ha preso tutti i percorsi elencati da ",["code","find"]," e li ha inseriti come argomenti di ",["code","identify"],", che poi mostra le informazioni per ogni file formattato come richiesto dall’opzione ",["code","-format"],". I file trovati da ",["code","find"]," nell’esempio sono immagini contenenti il logo della distribuzione in un filesystem Debian. ",["code","-format"]," è un parametro per ",["code","identify"],", non per ",["code","xargs"],"."],["p","L’opzione ",["code","-n 1"]," richiede che ",["code","xargs"]," esegua il comando dato con un solo argomento alla volta. Nel caso dell’esempio, invece di passare tutti i percorsi trovati da ",["code","find"]," come un elenco di argomenti a ",["code","identify"],", usando ",["code","xargs -n 1"]," si eseguirà il comando ",["code","identify"]," per ogni percorso separatamente. Usando ",["code","-n 2"]," si eseguirà ",["code","identify"]," con due percorsi come argomenti, ",["code","-n 3"]," con tre percorsi come argomenti e così via. Allo stesso modo, quando ",["code","xargs"]," elabora contenuti multilinea — come nel caso dell’input fornito da ",["code","find"]," — l’opzione ",["code","-L"]," può essere usata per limitare il numero di righe che saranno usate come argomenti per l’esecuzione del comando."],["note","Nota",["p","Usare ",["code","xargs"]," con l’opzione ",["code","-n 1"]," o ",["code","-L 1"]," per elaborare l’output generato da ",["code","find"]," potrebbe non essere necessario. Il comando ",["code","find"]," ha l’opzione ",["code","-exec"]," per eseguire un dato comando per ogni elemento del risultato di ricerca."]],["p","Se i percorsi hanno caratteri di spazio, è importante eseguire ",["code","find"]," con l’opzione ",["code","-print0"],". Questa opzione indica a ",["code","find"]," di usare un carattere nullo tra ogni voce in modo che l’elenco possa essere correttamente analizzato da ",["code","xargs"]," (l’output è stato soppresso):"],["pre","$ ",["strong","find . -name '*avi' -print0 -o -name '*mp4' -print0 -o -name '*mkv' -print0 | xargs -0 du | sort -n"]],["p","L’opzione ",["code","-0"]," dice a ",["code","xargs"]," che il carattere nullo dovrebbe essere usato come separatore. In questo modo i percorsi dei file forniti da ",["code","find"]," vengono analizzati correttamente anche se contengono caratteri vuoti o altri caratteri speciali. L’esempio precedente mostra come utilizzare il comando ",["code","du"]," per scoprire l’utilizzo del disco di ogni file trovato e quindi ordinare i risultati per dimensione. L’output è stato soppresso per concisione. Nota che per ogni criterio di ricerca è necessario inserire l’opzione ",["code","-print0"]," per ",["code","find"],"."],["p","Per impostazione predefinita, ",["code","xargs"]," inserisce gli argomenti del comando eseguito per ultimo. Per cambiare quel comportamento, dovrebbe essere usata l’opzione ",["code","-I"],":"],["pre","$ ",["strong","find . -mindepth 2 -name '*avi' -print0 -o -name '*mp4' -print0 -o -name '*mkv' -print0 | xargs -0 -I PATH mv PATH ./"]],["p","Nell’ultimo esempio, ogni file trovato da ",["code","find"]," viene spostato nella directory corrente. Poiché il percorso di origine deve essere dato a ",["code","mv"]," prima del percorso di destinazione, viene fornito un termine di sostituzione all’opzione ",["code","-I"]," di ",["code","xargs"]," che viene poi opportunamente posizionato accanto a ",["code","mv"],". Utilizzando il carattere ",["em","null"]," come separatore, non è necessario racchiudere il termine di sostituzione tra virgolette."],["h2","Esercizi Guidati"],["ol",["li",["p","È conveniente salvare la data di esecuzione delle azioni eseguite dagli script automatici. Il comando ",["code","date +% Y-% m-% d"]," mostra la data corrente nel formato ",["em","year-month-day"],". Come può l’output di un tale comando essere memorizzato in una variabile di shell chiamata ",["code","TODAY"]," usando la sostituzione del comando?"]," ",["table",["tr",["td"]]]],["li",["p","Usando il comando ",["code","echo"],", come può il contenuto della variabile ",["code","TODAY"]," essere inviato allo standard input del comando ",["code","sed s /-/./ g"],"?"]," ",["table",["tr",["td"]]]],["li",["p","In che modo l’output del comando ",["code","date +%Y-%m-%d"]," può essere usato come ",["em","Here string"]," da fornire a ",["code","sed s /-/./ g"],"?"]," ",["table",["tr",["td"]]]],["li",["p","Il comando ",["code","convert image.jpeg -resize 25% small/image.jpeg"]," crea una versione più piccola di ",["code","image.jpeg"]," e colloca l’immagine risultante in un file con lo stesso nome all’interno della sottodirectory ",["code","small"],". Usando ",["code","xargs"],", come è possibile eseguire lo stesso comando per ogni immagine elencata nel file ",["code","filelist.txt"],"?"]," ",["table",["tr",["td"]]]]],["h2","Esercizi Esplorativi"],["ol",["li",["p","Una semplice routine di backup crea periodicamente un’immagine della partizione ",["code","/dev/sda1"]," con ",["code","dd < /dev/sda1> sda1.img"],". Per eseguire futuri controlli di integrità dei dati, la routine genera anche un hash SHA1 del file con ",["code","sha1sum < sda1.img > sda1.sha1"],". Aggiungendo pipe e il comando ",["code","tee"],", come sarebbero combinati questi due comandi in uno?"]," ",["table",["tr",["td"]]]],["li",["p","Il comando ",["code","tar"]," viene utilizzato per archiviare molti file in un unico file, preservando la struttura delle directory. L’opzione ",["code","-T"]," permette di specificare un file contenente i percorsi da archiviare. Per esempio, ",["code","find /etc -type f | tar -cJ -f /srv/backup/etc.tar.xz -T -"]," crea un file tar compresso ",["code","etc.tar.xz"]," dalla lista fornita dal comando ",["code","find"]," (l’opzione ",["code","-T -"]," indica lo standard input come elenco dei percorsi). Al fine di evitare possibili errori di analisi dovuti a percorsi contenenti spazi, quali opzioni di comando dovrebbero essere presenti per ",["code","find"]," e ",["code","tar"],"?"]," ",["table",["tr",["td"]]]],["li",["p","Invece di aprire una nuova sessione di shell remota, il comando ",["code","ssh"]," può semplicemente eseguire un comando indicato come argomento: ",["code","ssh user@storage \"remote command\""],". Dato che ",["code","ssh"]," permette anche di reindirizzare l’output standard di un programma locale allo standard input del programma remoto, come potrebbe il comando ",["code","cat"]," reindirizzare un file locale chiamato ",["code","etc.tar.gz"]," a ",["code","/srv/backup/etc.tar.gz"]," in ",["code","user@storage"]," tramite ",["code","ssh"],"?"]," ",["table",["tr",["td"]]]]],["h2","Sommario"],["p","Questa lezione copre le tradizionali tecniche di comunicazione tra processi impiegate da Linux. La ",["em","command pipelining"]," crea un canale di comunicazione unidirezionale tra due processi e la ",["em","command substitution"]," consente di memorizzare l’output di un processo in una variabile di shell. La lezione segue i seguenti passaggi:"],["ul",["li",["p","Come la ",["em","pipe"]," può essere utilizzata per trasmettere l’output di un processo all’input di un altro processo."]],["li",["p","Lo scopo dei comandi ",["code","tee"]," e ",["code","xargs"],"."]],["li",["p","Come catturare l’output di un processo con la ",["em","command substitution"],", memorizzandolo in una variabile o usandolo direttamente come parametro per un altro comando."]]],["p","I comandi e le procedure trattate erano:"],["ul",["li",["p","Comand pipelining con ",["code","|"],"."]],["li",["p","Sostituzione dei comandi con backtick e ",["code","$()"],"."]],["li",["p","Comandi ",["code","tee"],", ",["code","xargs"]," e ",["code","find"],"."]]],["h2","Risposte agli Esercizi Guidati"],["ol",["li",["p","È conveniente salvare la data di esecuzione delle azioni eseguite dagli script automatici. Il comando ",["code","date +% Y-% m-% d"]," mostra la data corrente nel formato ",["em","year-month-day"],". Come può l’output di un tale comando essere memorizzato in una variabile di shell chiamata ",["code","TODAY"]," usando la sostituzione del comando?"],"   ",["pre","$ ",["strong","TODAY=`date +%Y-%m-%d`"]],"    ",["p","o"],"    ",["pre","$ ",["strong","TODAY=$(date +%Y-%m-%d)"]]],["li",["p","Usando il comando ",["code","echo"],", come può il contenuto della variabile ",["code","TODAY"]," essere inviato allo standard input del comando ",["code","sed s /-/./ g"],"?"],"   ",["pre","$ ",["strong","echo $TODAY | sed s/-/./g"]]],["li",["p","In che modo l’output del comando ",["code","date +%Y-%m-%d"]," può essere usato come ",["em","Here string"]," da fornire a ",["code","sed s /-/./ g"],"?"],"   ",["pre","$ ",["strong","sed s/-/./g <<< `date +%Y-%m-%d`"]],"    ",["p","o"],"    ",["pre","$ ",["strong","sed s/-/./g <<< $(date +%Y-%m-%d)"]]],["li",["p","Il comando ",["code","convert image.jpeg -resize 25% small/image.jpeg"]," crea una versione più piccola di ",["code","image.jpeg"]," e colloca l’immagine risultante in un file con lo stesso nome all’interno della sottodirectory ",["code","small"],". Usando ",["code","xargs"],", come è possibile eseguire lo stesso comando per ogni immagine elencata nel file ",["code","filelist.txt"],"?"],"   ",["pre","$ ",["strong","xargs -I IMG convert IMG -resize 25% small/IMG < filelist.txt"]],"    ",["p","o"],"    ",["pre","$ ",["strong","cat filelist.txt | xargs -I IMG convert IMG -resize 25% small/IMG"]]]],["h2","Risposte agli Esercizi Esplorativi"],["ol",["li",["p","Una semplice routine di backup crea periodicamente un’immagine della partizione ",["code","/dev/sda1"]," con ",["code","dd < /dev/sda1> sda1.img"],". Per eseguire futuri controlli di integrità dei dati, la routine genera anche un hash SHA1 del file con ",["code","sha1sum < sda1.img > sda1.sha1"],". Aggiungendo pipe e il comando ",["code","tee"],", come sarebbero combinati questi due comandi in uno?"],"   ",["pre","# ",["strong","dd < /dev/sda1 | tee sda1.img | sha1sum > sda1.sha1"]]],["li",["p","Il comando ",["code","tar"]," viene utilizzato per archiviare molti file in un unico file, preservando la struttura delle directory. L’opzione ",["code","-T"]," permette di specificare un file contenente i percorsi da archiviare. Per esempio, ",["code","find /etc -type f | tar -cJ -f /srv/backup/etc.tar.xz -T -"]," crea un file tar compresso ",["code","etc.tar.xz"]," dalla lista fornita dal comando ",["code","find"]," (l’opzione ",["code","-T -"]," indica lo standard input come elenco dei percorsi). Al fine di evitare possibili errori di analisi dovuti a percorsi contenenti spazi, quali opzioni di comando dovrebbero essere presenti per ",["code","find"]," e ",["code","tar"],"?"],"  ",["p","Opzioni ",["code","-print0"]," e ",["code","--null"],":"],"    ",["pre","$ ",["strong","find /etc -type f -print0 | tar -cJ -f /srv/backup/etc.tar.xz --null -T -"]]],["li",["p","Invece di aprire una nuova sessione di shell remota, il comando ",["code","ssh"]," può semplicemente eseguire un comando indicato come argomento: ",["code","ssh user@storage \"remote command\""],". Dato che ",["code","ssh"]," permette anche di reindirizzare l’output standard di un programma locale allo standard input del programma remoto, come potrebbe il comando ",["code","cat"]," reindirizzare un file locale chiamato ",["code","etc.tar.gz"]," a ",["code","/srv/backup/etc.tar.gz"]," in ",["code","user@storage"]," tramite ",["code","ssh"],"?"],"   ",["pre","$ ",["strong","cat etc.tar.gz | ssh user@storage \"cat > /srv/backup/etc.tar.gz\""]],"    ",["p","or"],"    ",["pre","$ ",["strong","ssh user@storage \"cat > /srv/backup/etc.tar.gz\" < etc.tar.gz"]]]]]},{"id":"103.7_01","objective":"103.7","title":"103.7 Lezione 1","url":"https://learning.lpi.org/it/learning-materials/101-500/103/103.7/103.7_01/","notice":"Linux Professional Institute Inc. Tutti i diritti riservati. Visita il sito Learning Materials: https://learning.lpi.org Quest'opera è sotto la licenza 'Creative Commons Attribution-NonCommercial-NoDerivatives 4.0 International License'.","body":[["h1","103.7 Lezione 1"],["table",["tr",["th",["p","Certificazione:"]],["td",["p","LPIC-1"]]],["tr",["th",["p","Versione:"]],["td",["p","5.0"]]],["tr",["th",["p","Argomento:"]],["td",["p","103 Comandi GNU e Unix"]]],["tr",["th",["p","Obiettivo:"]],["td",["p","103.7 Cercare file di testo utilizzando espressioni regolari"]]],["tr",["th",["p","Lezione:"]],["td",["p","1 di 2"]]]],["h2","Introduzione"],["p","Gli algoritmi di ricerca delle stringhe sono ampiamente utilizzati in diversi compiti di elaborazione dati, tanto che i sistemi operativi ",["em","Unix-like"]," hanno la loro onnipresente implementazione: ",["em","Espressioni regolari (Regular expressions)"],", spesso abbreviate in ",["em","REs"],". Le espressioni regolari sono costituite da sequenze di caratteri che costituiscono un modello generico utilizzato per individuare e talvolta modificare una sequenza corrispondente in una stringa di caratteri più grande. Le espressioni regolari espandono notevolmente la capacità di:"],["ul",["li",["p","Scrivere regole di analisi per le richieste nei server HTTP, in particolare ",["em","nginx"],"."]],["li",["p","Scrivere script che convertono set di dati basati su testo in un altro formato."]],["li",["p","Ricercare le occorrenze di interesse in voci di diario o documenti."]],["li",["p","Filtrare i documenti di markup, mantenendo il contenuto semantico."]]],["p","L’espressione regolare più semplice contiene almeno un ",["em","atomo"],". Un atomo, così chiamato perché è l’elemento base di un’espressione regolare, è solo un carattere che può avere o meno un significato speciale. La maggior parte dei caratteri ordinari non sono ambigui, mantengono il loro significato letterale, mentre altri hanno un significato speciale:"],["dl",["dt",["code","."]," (punto)"],["dd",["p","Il carattere corrisponde a un qualsiasi carattere."]],["dt",["code","^"]," (segno d’omissione)"],["dd",["p","Il carattere corrisponde all’inizio della linea."]],["dt",["code","$"]," (simbolo del dollaro)"],["dd",["p","Il carattere corrisponde alla fine della linea."]]],["p","Per esempio, l’espressione regolare ",["code","bc"],", composta dagli atomi letterali ",["code","b"]," e ",["code","c"],", può essere trovata nella stringa ",["code","abcd"],", ma non può essere trovata nella stringa ",["code","a1cd"],". D’altra parte, l’espressione regolare ",["code",".c"]," può essere trovata in entrambe le stringhe ",["code","abcd"]," e ",["code","a1cd"],", poiché il punto ",["code","."]," corrisponde a qualsiasi carattere."],["p","Gli atomi del segno di omissione e del dollaro vengono utilizzati quando interessano solo le corrispondenze all’inizio o alla fine della stringa. Per questo motivo sono anche chiamati ",["em","anchors"],". ",["code","cd"]," può essere trovato in ",["code","abcd"],", ma ",["code","^cd"]," no. Allo stesso modo, ",["code","ab"]," può essere trovato in ",["code","abcd"],", ma ",["code","ab$"]," non può. Il simbolo di omissione ",["code","^"]," è un carattere letterale tranne quando all’inizio e ",["code","$"]," è un carattere letterale tranne quando alla fine dell’espressione regolare."],["h3","Espressioni tra Parentesi Quadre"],["p","Esiste un altro tipo di atomo denominato ",["em","bracket expression"],". Sebbene non sia un singolo carattere, le parentesi ",["code","[]"]," (incluso il loro contenuto) sono considerate un singolo atomo. Un’espressione tra parentesi quadre di solito è solo un elenco di caratteri letterali racchiusi da ",["code","[]"],", facendo sì che l’atomo corrisponda a ogni singolo carattere dell’elenco. Per esempio, l’espressione ",["code","[1b]"]," può essere trovata in entrambe le stringhe ",["code","abcd"]," e ",["code","a1cd"],". Per specificare i caratteri a cui l’atomo non deve corrispondere, l’elenco deve iniziare con ",["code","^"],", come in ",["code","[^ 1b]"],". È anche possibile specificare intervalli di caratteri nelle espressioni di parentesi. Per esempio, ",["code","[0-9]"]," corrisponde alle cifre da 0 a 9 e ",["code","[a-z]"]," corrisponde a qualsiasi lettera minuscola. Gli intervalli devono essere utilizzati con cautela, poiché potrebbero non essere coerenti tra le diverse impostazioni locali."],["p","Gli elenchi di espressioni tra parentesi quadre accettano anche classi invece di singoli caratteri e intervalli. Le classi sono:"],["dl",["dt",["code","[:alnum:]"]],["dd",["p","Rappresenta un carattere alfanumerico."]],["dt",["code","[:alpha:]"]],["dd",["p","Rappresenta un carattere alfabetico."]],["dt",["code","[:ascii:]"]],["dd",["p","Rappresenta un carattere che si adatta al set di caratteri ASCII."]],["dt",["code","[:blank:]"]],["dd",["p","Rappresenta un carattere vuoto, ovvero uno spazio o una tabulazione."]],["dt",["code","[:cntrl:]"]],["dd",["p","Rappresenta un carattere di controllo."]],["dt",["code","[:digit:]"]],["dd",["p","Rappresenta una cifra (da 0 a 9)."]],["dt",["code","[:graph:]"]],["dd",["p","Rappresenta qualsiasi carattere stampabile tranne lo spazio."]],["dt",["code","[:lower:]"]],["dd",["p","Rappresenta un carattere minuscolo."]],["dt",["code","[:print:]"]],["dd",["p","Rappresenta qualsiasi carattere stampabile compreso lo spazio."]],["dt",["code","[:punct:]"]],["dd",["p","Rappresenta qualsiasi carattere stampabile che non sia uno spazio o un carattere alfanumerico."]],["dt",["code","[:space:]"]],["dd",["p","Rappresenta i caratteri spazi vuoti: spazio, avanzamento modulo (",["code","\\f"],"), nuova riga (",["code","\\n"],"), ritorno a capo (",["code","\\r"],"), tabulazione orizzontale (",["code","\\t"],") e tabulazione verticale (",["code","\\v"],")."]],["dt",["code","[:upper:]"]],["dd",["p","Rappresenta un carattere maiuscolo."]],["dt",["code","[:xdigit:]"]],["dd",["p","Rappresenta cifre esadecimali (da 0 a F)"]]],["p","Le classi di caratteri possono essere combinate con singoli caratteri e intervalli, ma non possono essere utilizzate come punto finale di un intervallo. Inoltre, le classi di caratteri possono essere utilizzate solo nelle espressioni di parentesi, non come un atomo indipendente al di fuori delle parentesi."],["h3","Quantificatori"],["p","La portata di un atomo, sia di un singolo carattere che di una parentesi, può essere regolata utilizzando un ",["em","quantificatore"],". I quantificatori atomici definiscono le sequenze atomiche, ovvero le corrispondenze si verificano quando nella stringa viene trovata una ripetizione contigua per l’atomo. La sottostringa corrispondente alla corrispondenza è chiamata ",["em","parte"],". Tuttavia, i quantificatori e altre caratteristiche delle espressioni regolari vengono trattati in modo diverso a seconda dello standard utilizzato."],["p","Come definito dallo standard POSIX, ci sono due forme di espressioni regolari: espressioni regolari “basic” ed espressioni regolari “extended”. La maggior parte dei programmi relativi al testo in qualsiasi distribuzione Linux convenzionale supporta entrambe le forme, quindi è importante conoscere le loro differenze al fine di evitare problemi di compatibilità e scegliere l’implementazione più adatta per l’attività prevista."],["p","Il quantificatore ",["code","*"]," ha la stessa funzione sia nelle RE di base che in quelle estese (l’atomo ricorre zero o più volte) ed è un carattere letterale se appare all’inizio dell’espressione regolare o se è preceduto da un back slash ",["code","\\"],". Il quantificatore del segno più ",["code","` selezionerà i \"pezzi\" contenenti uno o più corrispondenze di atomi in sequenza. Con il quantificatore del punto interrogativo `?`, Si verificherà una corrispondenza se l'atomo corrispondente appare una volta o se non compare affatto. Se preceduto da un _back slash_ `\\`, il loro significato speciale non viene considerato. Le espressioni regolari di base supportano anche i quantificatori `"]," e ",["code","?"],", Ma devono essere preceduti da un back slash. A differenza delle espressioni regolari estese, ",["code","+"]," e ",["code","?"]," sono di per sé caratteri letterali nelle espressioni regolari di base."],["h3","Limiti"],["p","Un ",["em","bound"]," è un quantificatore di atomi che, come suggerisce il nome, consente a un utente di specificare limiti di quantità precisi per un atomo. Nelle espressioni regolari estese un limite può apparire in tre forme:"],["dl",["dt",["code","{i}"]],["dd",["p","L’atomo deve apparire esattamente ",["code","i"]," volte (",["code","i"]," è un numero intero). Per esempio, ",["code","[[:blank:]]{2}"]," corrisponde esattamente a due caratteri vuoti."]],["dt",["code","{i,}"]],["dd",["p","L’atomo deve apparire almeno ",["code","i"]," volte (",["code","i"]," è un numero intero). Per esempio, ",["code","[[:blank:]]{2,}"]," corrisponde a qualsiasi sequenza di due o più caratteri vuoti."]],["dt",["code","{i,j}"]],["dd",["p","L’atomo deve apparire almeno ",["code","i"]," volte e al massimo ",["code","j"]," volte (",["code","i"]," e ",["code","j"]," sono numeri interi, ",["code","j"]," è maggiore di ",["code","i"],"). Per esempio, ",["code","xyz{2,4}"]," corrisponde alla stringa xy seguita da due a quattro del carattere ",["code","z"],"."]]],["p","In ogni caso, se una sottostringa corrisponde a un’espressione regolare e anche una sottostringa più lunga che inizia nello stesso punto corrisponde, verrà considerata la sottostringa più lunga."],["p","Anche le espressioni regolari di base supportano i limiti, ma i delimitatori devono essere preceduti da ",["code","\\"],": ",["code","\\{"]," e ",["code","\\}"],". Di per sé, ",["code","{"]," e ",["code","}"]," vengono interpretati come caratteri letterali. Una ",["code","\\{"]," seguita da un carattere diverso da una cifra è un carattere letterale, non l’inizio di un limite."],["h3","Rami e Riferimenti all’Indietro"],["p","Le espressioni regolari di base differiscono dalle espressioni regolari estese anche per un altro aspetto importante: un’espressione regolare estesa può essere suddivisa in ",["em","remi (branches)"],", ciascuna un’espressione regolare indipendente. I rami sono separati da ",["code","|"]," e l’espressione regolare combinata corrisponderà a tutto ciò che corrisponde a uno qualsiasi dei rami. Per esempio, ",["code","he|him"]," corrisponderà se nella stringa in esame si trova la sottostringa ",["code","he"]," o ",["code","him"],". Le espressioni regolari di base interpretano ",["code","|"]," come un carattere letterale. Tuttavia, la maggior parte dei programmi che supportano le espressioni regolari di base consentiranno i rami con ",["code","\\ |"],"."],["p","Un’espressione regolare estesa racchiusa tra ",["code","()"]," può essere utilizzata in un ",["em","riferimento all’indietro"],". Per esempio: ",["code","([[:digit:]])\\1"]," corrisponderà a qualsiasi espressione regolare che si ripete almeno una volta, perché ",["code","\\1"]," nell’espressione è il riferimento all’indietro al pezzo corrispondente alla prima parentesi sottoespressione. Se nell’espressione regolare esiste più di una sottoespressione tra parentesi, è possibile fare riferimento a ",["code","\\2"],",",["code","\\3"]," e così via."],["p","Per le RE di base, le sottoespressioni devono essere racchiuse tra ",["code","\\("]," e ",["code","\\)"],", con ",["code","("]," e ",["code",")"]," da sole saranno considerate come caratteri ordinari. L’indicatore di riferimento all’indietro viene utilizzato come nelle espressioni regolari estese"],["h3","Ricerca con Espressioni Regolari"],["p","Il vantaggio immediato offerto dalle espressioni regolari è quello di migliorare le ricerche sui filesystem e nei documenti di testo. L’opzione ",["code","-regex"]," del comando ",["code","find"]," permette di testare ogni percorso in una gerarchia di directory rispetto a un’espressione regolare. Per esempio:"],["pre","$ ",["strong","find $HOME -regex '.*/\\..*' -size +100M"]],["p","Cerca file più grandi di 100 megabyte (100 unità di 1048576 byte), ma solo nei percorsi all’interno della directory ",["em","home"]," dell’utente che contengono una corrispondenza con ",["code",".*/\\..*"],", cioè un ",["code","/ ."]," circondato da qualsiasi altro numero di caratteri. In altre parole, verranno elencati solo i file nascosti o i file all’interno di directory nascoste, indipendentemente dalla posizione di ",["code","/."],", nel percorso corrispondente. Per le espressioni regolari senza distinzione tra maiuscole e minuscole, dovrebbe essere utilizzata l’opzione ",["code","-iregex"],":"],["pre","$ ",["strong","find /usr/share/fonts -regextype posix-extended -iregex '.*(dejavu|liberation).*sans.*(italic|oblique).*'"],"\n/usr/share/fonts/dejavu/DejaVuSansCondensed-BoldOblique.ttf\n/usr/share/fonts/dejavu/DejaVuSansCondensed-Oblique.ttf\n/usr/share/fonts/dejavu/DejaVuSans-BoldOblique.ttf\n/usr/share/fonts/dejavu/DejaVuSans-Oblique.ttf\n/usr/share/fonts/dejavu/DejaVuSansMono-BoldOblique.ttf\n/usr/share/fonts/dejavu/DejaVuSansMono-Oblique.ttf\n/usr/share/fonts/liberation/LiberationSans-BoldItalic.ttf\n/usr/share/fonts/liberation/LiberationSans-Italic.ttf"],["p","In questo esempio, l’espressione regolare contiene rami (scritti in stile ",["em","extended"],") per elencare solo file di font specifici nella gerarchia di directory ",["code","/usr/share/fonts"],". Le espressioni regolari estese non sono supportate di default, ma ",["code","find"]," permette di abilitarle con ",["code","-regextype posix-extended"]," o ",["code","-regextype egrep"],". Lo standard RE predefinito per ",["code","find"]," è ",["em","findutils-default"],", che è virtualmente un clone di espressioni regolari di base."],["p","Spesso è necessario passare l’output di un programma al comando ",["code","less"]," quando non si adatta allo schermo. Il comando ",["code","less"]," divide il suo input in pagine, una schermata alla volta, consentendo all’utente di navigare facilmente nel testo su e giù. Inoltre, ",["code","less"]," consente anche a un utente di eseguire ricerche basate su espressioni regolari. Questa caratteristica è particolarmente importante perché ",["code","less"]," è il paginatore predefinito usato per molte attività quotidiane, come l’ispezione delle voci del diario o la consultazione delle pagine di manuale. Quando si legge una pagina di manuale, per esempio, premendo il tasto ",["kbd","/"]," si aprirà un prompt di ricerca. Questo è uno scenario tipico in cui le espressioni regolari sono utili, poiché le opzioni di comando sono elencate subito dopo un margine di pagina nel layout generale della pagina del manuale. Tuttavia, la stessa opzione potrebbe apparire molte volte nel testo, rendendo irrealizzabili le ricerche letterali. Indipendentemente da ciò, digitando ",["code","^[[:blank:]]",["strong","-o"]],["strong"," — o più semplicemente: ",["code","^"]],["code","-o"]," — nel prompt di ricerca si salterà immediatamente all’opzione della sezione ",["code","-o"]," (se esiste) dopo aver premuto Invio, consentendo così di consultare più rapidamente la descrizione di un’opzione."],["h2","Esercizi Guidati"],["pre","Quale espressione regolare estesa corrisponderebbe a qualsiasi indirizzo email, come `info@example.org`?"],["p","+"],["table",["tr",["td"]]],["ol",["li",["p","Quale espressione regolare estesa corrisponderebbe solo a qualsiasi indirizzo IPv4 nel formato standard a quattro punti, come ",["code","192.168.15.1"],"?"]," ",["table",["tr",["td"]]]],["li",["p","Come può essere usato il comando ",["code","grep"]," per elencare il contenuto del file ",["code","/etc/services"],", scartando tutti i commenti (righe che iniziano con ",["code","#"],")?"]," ",["table",["tr",["td"]]]],["li",["p","Il file ",["code","domains.txt"]," contiene un elenco di nomi di dominio, uno per riga. Come sarebbe usato il comando ",["code","egrep"]," per elencare solo i domini ",["code",".org"]," o ",["code",".com"],"?"]," ",["table",["tr",["td"]]]]],["h2","Esercizi Esplorativi"],["ol",["li",["p","Dalla directory corrente, in che modo il comando ",["code","find"]," userebbe un’espressione regolare estesa per cercare tutti i file che non contengono un suffisso di file standard (i nomi di file non terminano con ",["code",".txt"]," o ",["code",".c"],", per esempio)?"]," ",["table",["tr",["td"]]]],["li",["p","Il comando ",["code","less"]," è il paginatore predefinito per visualizzare file di testo lunghi nell’ambiente shell. Digitando ",["code","/"]," è possibile inserire un’espressione regolare nel prompt di ricerca per passare alla prima corrispondenza trovata. Per rimanere nella posizione del documento corrente ed evidenziare solo le corrispondenze, quale combinazione di tasti deve essere inserita al prompt di ricerca?"]," ",["table",["tr",["td"]]]],["li",["p","In ",["code","less"],", come sarebbe possibile filtrare l’output in modo che vengano visualizzate solo le righe che corrispondono a un’espressione regolare?"]," ",["table",["tr",["td"]]]]],["h2","Sommario"],["p","Questa lezione tratta del supporto generale di Linux alle espressioni regolari, uno standard ampiamente utilizzato le cui capacità di corrispondenza dei modelli sono supportate dalla maggior parte dei programmi relativi al testo. La lezione segue i seguenti passaggi:"],["ul",["li",["p","Che cos’è un’espressione regolare."]],["li",["p","I componenti principali di un’espressione regolare."]],["li",["p","Le differenze tra espressioni regolari basiche ed estese."]],["li",["p","Come eseguire semplici ricerche di testo e file utilizzando espressioni regolari."]]],["h2","Risposte agli Esercizi Guidati"],["ol",["li",["p","Quale espressione regolare estesa corrisponderebbe a qualsiasi indirizzo email, come ",["code","info@example.org"],"?"],"   ",["pre","egrep \"\\S+@\\S+\\.\\S+\""]],["li",["p","Quale espressione regolare estesa corrisponderebbe solo a qualsiasi indirizzo IPv4 nel formato standard a quattro punti, come ",["code","192.168.15.1"],"?"],"   ",["pre","egrep \"[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}\""]],["li",["p","Come può essere usato il comando ",["code","grep"]," per elencare il contenuto del file ",["code","/etc/services"],", scartando tutti i commenti (righe che iniziano con ",["code","#"],")?"],"   ",["pre","grep -v ^# /etc/services"]],["li",["p","Il file ",["code","domains.txt"]," contiene un elenco di nomi di dominio, uno per riga. Come sarebbe usato il comando ",["code","egrep"]," per elencare solo i domini ",["code",".org"]," o ",["code",".com"],"?"],"   ",["pre","egrep \".org$|.com$\" domains.txt"]]],["h2","Risposte agli Esercizi Esplorativi"],["ol",["li",["p","Dalla directory corrente, in che modo il comando ",["code","find"]," userebbe un’espressione regolare estesa per cercare tutti i file che non contengono un suffisso di file standard (i nomi di file non terminano con ",["code",".txt"]," o ",["code",".c"],", per esempio)?"],"   ",["pre","find . -type f -regextype egrep -not -regex '.*\\.[[:alnum:]]{1,}$'"]],["li",["p","Il comando ",["code","less"]," è il paginatore predefinito per visualizzare file di testo lunghi nell’ambiente shell. Digitando ",["code","/"]," è possibile inserire un’espressione regolare nel prompt di ricerca per passare alla prima corrispondenza trovata. Per rimanere nella posizione del documento corrente ed evidenziare solo le corrispondenze, quale combinazione di tasti deve essere inserita al prompt di ricerca?"],"  ",["p","Premendo ",["kbd","Ctrl"],"+",["kbd","K"]," prima di inserire l’espressione di ricerca."]],["li",["p","In ",["code","less"],", come sarebbe possibile filtrare l’output in modo che vengano visualizzate solo le righe che corrispondono a un’espressione regolare?"],"  ",["p","Premendo ",["kbd","&"]," e inserendo l’espressione di ricerca."]]]]},{"id":"103.7_02","objective":"103.7","title":"103.7 Lezione 2","url":"https://learning.lpi.org/it/learning-materials/101-500/103/103.7/103.7_02/","notice":"Linux Professional Institute Inc. Tutti i diritti riservati. Visita il sito Learning Materials: https://learning.lpi.org Quest'opera è sotto la licenza 'Creative Commons Attribution-NonCommercial-NoDerivatives 4.0 International License'.","body":[["h1","103.7 Lezione 2"],["table",["tr",["th",["p","Certificazione:"]],["td",["p","LPIC-1"]]],["tr",["th",["p","Versione:"]],["td",["p","5.0"]]],["tr",["th",["p","Argomento:"]],["td",["p","103 Comandi GNU e Unix"]]],["tr",["th",["p","Obiettivo:"]],["td",["p","103.7 Cercare file di testo utilizzando espressioni regolari"]]],["tr",["th",["p","Lezione:"]],["td",["p","2 di 2"]]]],["h2","Introduzione"],["p","Lo streaming dei dati attraverso una catena di comandi in ",["em","pipe"]," consente l’applicazione di filtri composti basati su espressioni regolari. Le espressioni regolari sono una tecnica importante utilizzata non solo nell’amministrazione del sistema, ma anche nel ",["em","data mining"]," e nelle aree correlate. Due comandi sono particolarmente adatti per manipolare file e dati di testo usando espressioni regolari: ",["code","grep"]," e ",["code","sed"],". ",["code","grep"]," è un cercatore di pattern e ",["code","sed"]," è un editor di flussi. Sono utili da soli, ma è quando lavorano insieme ad altri processi che diventano insostituibili."],["h3","Il \"Cercatore\" di Pattern: grep"],["p","Uno degli usi più comuni di ",["code","grep"]," è quello di facilitare l’ispezione di file lunghi, utilizzando l’espressione regolare come filtro applicato a ciascuna riga. Può essere utilizzato per mostrare solo le righe che iniziano con un certo termine. ",["code","grep"]," può essere usato per cercare in un file di configurazione i moduli del kernel, elencando solo le righe delle opzioni:"],["pre","$ ",["strong","grep '^options' /etc/modprobe.d/alsa-base.conf"],"\noptions snd-pcsp index=-2\noptions snd-usb-audio index=-2\noptions bt87x index=-2\noptions cx88_alsa index=-2\noptions snd-atiixp-modem index=-2\noptions snd-intel8x0m index=-2\noptions snd-via82xx-modem index=-2"],["p","Il carattere pipe ",["code","|"]," può essere impiegato per reindirizzare l’output di un comando direttamente all’input di ",["code","grep"],". L’esempio seguente utilizza un’espressione con parentesi quadre per selezionare le righe dall’output di ",["code","fdisk -l"],", che iniziano con ",["code","Disk /dev/sda"]," o ",["code","Disk /dev/sdb"],":"],["pre","# ",["strong","fdisk -l | grep '^Disk /dev/sd[ab]'"],"\nDisk /dev/sda: 320.1 GB, 320072933376 bytes, 625142448 sectors\nDisk /dev/sdb: 7998 MB, 7998537728 bytes, 15622144 sectors"],["p","La semplice selezione di linee con corrispondenze potrebbe non essere appropriata per un compito particolare, richiedendo aggiustamenti al comportamento di ",["code","grep"]," attraverso le sue opzioni. Per esempio, l’opzione ",["code","-c"]," o ",["code","--count"]," dice a ",["code","grep"]," di mostrare quante righe hanno corrispondenze:"],["pre","# ",["strong","fdisk -l | grep '^Disk /dev/sd[ab]' -c"],"\n2"],["p","L’opzione può essere inserita prima o dopo l’espressione regolare. Altre importanti opzioni di ",["code","grep"]," sono:"],["dl",["dt",["code","-c"]," o ",["code","--count"]],["dd",["p","Invece di visualizzare i risultati della ricerca, visualizza solo il conteggio totale del numero di volte in cui si verifica una corrispondenza in un determinato file."]],["dt",["code","-i"]," o ",["code","--ignore-case"]],["dd",["p","Imposta la ricerca senza distinzione tra maiuscole e minuscole."]],["dt",["code","-f FILE"]," o ",["code","--file=FILE"]],["dd",["p","Indica un file contenente l’espressione regolare da utilizzare."]],["dt",["code","-n"]," o ",["code","--line-number"]],["dd",["p","Mostra il numero della riga."]],["dt",["code","-v"]," o ",["code","--invert-match"]],["dd",["p","Seleziona ogni riga, tranne quelle che contengono corrispondenze."]],["dt",["code","-H"]," o ",["code","--with-filename"]],["dd",["p","Stampa anche il nome del file contenente la riga."]],["dt",["code","-z"]," o ",["code","--null-data"]],["dd",["p","Invece di fare in modo che ",["code","grep"]," tratti i flussi di dati di input e output come linee separate (usando ",["em","newline"]," per impostazione predefinita), prendi l’input o l’output come una sequenza di righe. Quando si combina l’output del comando ",["code","find"]," usando la sua opzione ",["code","-print0"]," con il comando ",["code","grep"],", l’opzione ",["code","-z"]," o ",["code","--null-data"]," dovrebbe essere usata per elaborare lo ",["em","stream"]," nello stesso modo."]]],["p","Sebbene sia attivata per impostazione predefinita quando vengono forniti più percorsi di file come input, l’opzione ",["code","-H"]," non è attivata per singoli file. Ciò può essere critico in situazioni speciali, come quando ",["code","grep"]," viene chiamato direttamente da ",["code","find"],", per esempio:"],["pre","$ ",["strong","find /usr/share/doc -type f -exec grep -i '3d modeling' \"{}\" \\; | cut -c -100"],"\nartistic aspects of 3D modeling. Thus this might be the application you are\nThis major approach of 3D modeling has not been supported\noce is a C++ 3D modeling library. It can be used to develop CAD/CAM softwares, for instance [FreeCad"],["p","In questo esempio, ",["code","find"]," elenca tutti i file in ",["code","/usr/share/doc"],", quindi li passa ciascuno a ",["code","grep"],", che a sua volta esegue una ricerca senza distinzione tra maiuscole e minuscole per ",["code","3d modeling"]," all’interno del file. Il flusso da tagliare (",["code","cut"],") serve solo per limitare la lunghezza di output a 100 colonne. Notare, tuttavia, che non c’è modo di sapere da quale file provengano le righe. Questo problema viene risolto aggiungendo ",["code","-H"]," a ",["code","grep"],":"],["pre","$ ",["strong","find /usr/share/doc -type f -exec grep -i -H '3d modeling' \"{}\" \\; | cut -c -100"],"\n/usr/share/doc/openscad/README.md:artistic aspects of 3D modeling. Thus this might be the applicatio\n/usr/share/doc/opencsg/doc/publications.html:This major approach of 3D modeling has not been support"],["p","Ora è possibile identificare i file in cui è stata trovata ogni corrispondenza. Per rendere l’elenco ancora più informativo, è possibile aggiungere righe iniziali e finali alle righe con corrispondenze:"],["pre","$ ",["strong","find /usr/share/doc -type f -exec grep -i -H -1 '3d modeling' \"{}\" \\; | cut -c -100"],"\n/usr/share/doc/openscad/README.md-application Blender), OpenSCAD focuses on the CAD aspects rather t\n/usr/share/doc/openscad/README.md:artistic aspects of 3D modeling. Thus this might be the applicatio\n/usr/share/doc/openscad/README.md-looking for when you are planning to create 3D models of machine p\n/usr/share/doc/opencsg/doc/publications.html-3D graphics library for Constructive Solid Geometry (CS\n/usr/share/doc/opencsg/doc/publications.html:This major approach of 3D modeling has not been support\n/usr/share/doc/opencsg/doc/publications.html-by real-time computer graphics until recently."],["p","L’opzione ",["code","-1"]," dice a ",["code","grep"]," di includere una riga prima e una riga dopo la riga trovata con una corrispondenza. Queste righe aggiuntive sono chiamate ",["em","linee di contesto"]," e sono identificate nell’output da un segno meno dopo il nome del file. Lo stesso risultato può essere ottenuto con ",["code","-C 1"]," o ",["code","--context=1"]," e possono essere indicate altre quantità di righe di contesto."],["p","Ci sono due programmi complementari a grep: ",["code","egrep"]," e ",["code","fgrep"],". Il programma ",["code","egrep"]," è equivalente al comando ",["code","grep -E"],", che incorpora funzionalità extra oltre alle espressioni regolari di base. Per esempio, con ",["code","egrep"]," è possibile utilizzare funzionalità di espressioni regolari estese, come la ramificazione:"],["pre","$ ",["strong","find /usr/share/doc -type f -exec egrep -i -H -1 '3d (modeling|printing)' \"{}\" \\; | cut -c -100"],"\n/usr/share/doc/openscad/README.md-application Blender), OpenSCAD focuses on the CAD aspects rather t\n/usr/share/doc/openscad/README.md:artistic aspects of 3D modeling. Thus this might be the applicatio\n/usr/share/doc/openscad/README.md-looking for when you are planning to create 3D models of machine p\n/usr/share/doc/openscad/RELEASE_NOTES.md-* Support for using 3D-Mouse / Joystick / Gamepad input dev\n/usr/share/doc/openscad/RELEASE_NOTES.md:* 3D Printing support: Purchase from a print service partne\n/usr/share/doc/openscad/RELEASE_NOTES.md-* New export file formats: SVG, 3MF, AMF\n/usr/share/doc/opencsg/doc/publications.html-3D graphics library for Constructive Solid Geometry (CS\n/usr/share/doc/opencsg/doc/publications.html:This major approach of 3D modeling has not been support\n/usr/share/doc/opencsg/doc/publications.html-by real-time computer graphics until recently."],["p","In questo esempio, ",["code","3D modeling"]," o ",["code","3D printing"]," corrisponderanno all’espressione, senza distinzione tra maiuscole e minuscole. Per visualizzare solo le parti di un flusso di testo che corrispondono all’espressione usata da ",["code","egrep"],", utilizzare l’opzione ",["code","-o"],"."],["p","Il programma ",["code","fgrep"]," è equivalente a ",["code","grep -F"],", cioè non analizza le espressioni regolari: è utile nelle ricerche semplici in cui l’obiettivo è trovare una corrispondenza con un’espressione letterale. Pertanto, caratteri speciali come il simbolo del dollaro e il punto verranno presi alla lettera e non dal loro significato in un’espressione regolare."],["h3","L’Editor di Stream: sed"],["p","Lo scopo del programma ",["code","sed"]," è quello di modificare i dati basati su testo in modo non interattivo. Questo significa che tutte le modifiche vengono effettuate tramite istruzioni predefinite, non digitando direttamente su un testo visualizzato a schermo. In termini \"moderni\", ",["code","sed"]," può essere inteso come un ",["em","template parser"],": dato un testo come input, colloca il contenuto personalizzato in posizioni predefinite o quando trova una corrispondenza per un’espressione regolare."],["p","Sed, come suggerisce il nome, è adatto per il testo trasmesso tramite pipeline. La sua sintassi di base è ",["code","sed -f SCRIPT"]," quando le istruzioni di modifica sono memorizzate nel file ",["code","SCRIPT"]," o ",["code","sed -e COMMANDS"]," per eseguire ",["code","COMMANDS"]," direttamente dalla riga di comando. Se non sono presenti ne ",["code","-f"]," ne ",["code","-e"],", ",["code","sed"]," utilizza il primo parametro non di opzione come file di script. È anche possibile usare un file come input semplicemente dando il suo percorso come argomento a ",["code","sed"],"."],["p","Le istruzioni ",["code","sed"]," sono composte da un singolo carattere, possibilmente preceduto da un indirizzo o seguite da una o più opzioni, e vengono applicate ad una riga alla volta. Gli indirizzi possono essere un numero di riga singola, un’espressione regolare o un intervallo di righe. Per esempio, la prima riga di un flusso di testo può essere eliminata con ",["code","1d"],", dove ",["code","1"]," specifica la riga in cui verrà applicato il comando di eliminazione ",["code","d"],". Per chiarire l’uso di ",["code","sed"],", prendi l’output del comando ",["code","factor `seq 12`"],", che restituisce i fattori primi per i numeri da 1 a 12:"],["pre","$ ",["strong","factor `seq 12`"],"\n1:\n2: 2\n3: 3\n4: 2 2\n5: 5\n6: 2 3\n7: 7\n8: 2 2 2\n9: 3 3\n10: 2 5\n11: 11\n12: 2 2 3"],["p","L’eliminazione della prima riga con ",["code","sed"]," si ottiene con ",["code","1d"],":"],["pre","$ ",["strong","factor `seq 12` | sed 1d"],"\n2: 2\n3: 3\n4: 2 2\n5: 5\n6: 2 3\n7: 7\n8: 2 2 2\n9: 3 3\n10: 2 5\n11: 11\n12: 2 2 3"],["p","È possibile specificare un intervallo di righe con una virgola di separazione:"],["pre","$ ",["strong","factor `seq 12` | sed 1,7d"],"\n8: 2 2 2\n9: 3 3\n10: 2 5\n11: 11\n12: 2 2 3"],["p","È possibile utilizzare più di un’istruzione nella stessa esecuzione, separate da punto e virgola. In questo caso, però, è importante racchiuderli tra virgolette in modo che il punto e virgola non venga interpretato dalla shell:"],["pre","$ ",["strong","factor `seq 12` | sed \"1,7d;11d\""],"\n8: 2 2 2\n9: 3 3\n10: 2 5\n12: 2 2 3"],["p","In questo esempio, sono state eseguite due istruzioni di cancellazione, prima sulle righe da 1 a 7 e poi sulla riga 11. Un indirizzo può anche essere un’espressione regolare, quindi solo le righe con una corrispondenza saranno influenzate dall’istruzione:"],["pre","$ ",["strong","factor `seq 12` | sed \"1d;/:.*2.*/d\""],"\n3: 3\n5: 5\n7: 7\n9: 3 3\n11: 11"],["p","L’espressione regolare ",["code",":.*2.*"]," corrisponde a qualsiasi occorrenza del numero 2 in qualsiasi punto dopo i due punti, causando la cancellazione delle righe corrispondenti ai numeri con 2 come fattore. Con ",["code","sed"],", qualsiasi cosa inserita tra gli slash (",["code","/"],") è considerata un’espressione regolare e per impostazione predefinita sono supportate tutte le RE di base. Per esempio, ",["code","sed -e \"/^#/d\" /etc/services"]," mostra il contenuto del file ",["code","/etc/services"]," senza le righe che iniziano con ",["code","#"]," (righe di commento)."],["p","L’istruzione di cancellazione ",["code","d"]," è solo una delle tante istruzioni di modifica fornite da ",["code","sed"],". Invece di eliminare una riga, ",["code","sed"]," può sostituirla con un dato testo:"],["pre","$ ",["strong","factor `seq 12` | sed \"1d;/:.*2.*/c REMOVED\""],"\nREMOVED\n3: 3\nREMOVED\n5: 5\nREMOVED\n7: 7\nREMOVED\n9: 3 3\nREMOVED\n11: 11\nREMOVED"],["p","L’istruzione ",["code","c REMOVED"]," sostituisce semplicemente una riga con il testo ",["code","REMOVED"],". Nel caso dell’esempio, ogni riga con una sottostringa che corrisponde all’espressione regolare ",["code",":.*2.*"]," è influenzata dall’istruzione ",["code","c REMOVED"],". L’istruzione ",["code","a TEXT"]," copia il testo indicato da ",["code","TEXT"]," in una nuova riga dopo la riga con una corrispondenza. L’istruzione ",["code","r FILE"]," fa lo stesso, ma copia il contenuto del file indicato da ",["code","FILE"],". L’istruzione ",["code","w"]," fa l’opposto di ",["code","r"],", cioè la riga verrà aggiunta al file indicato."],["p","Di gran lunga l’istruzione ",["code","sed"]," più usata è ",["code","s/FIND/REPLACE/"],", che viene usata per sostituire una corrispondenza all’espressione regolare ",["code","FIND"]," con il testo indicato da ",["code","REPLACE"],". Per esempio, l’istruzione ",["code","s/hda/sda/"]," sostituisce una sottostringa che corrisponde al letterale RE ",["code","hda"]," con ",["code","sda"],". Solo la prima corrispondenza trovata nella riga verrà sostituita, a meno che il ",["em","flag"]," ",["code","g"]," non sia posto dopo l’istruzione, come in ",["code","s/hda/sda/g"],"."],["p","Un caso più realistico aiuterà a illustrare le caratteristiche di ",["code","sed"],". Supponiamo che una clinica medica desideri inviare messaggi di testo ai propri clienti, ricordando loro gli appuntamenti programmati per il giorno successivo. Uno scenario di implementazione tipico si basa su un servizio di messaggistica istantanea professionale, che fornisce un’API per accedere al sistema responsabile della consegna dei messaggi. Questi messaggi di solito provengono dallo stesso sistema che esegue l’applicazione controllando gli appuntamenti del cliente, messaggi attivati a un momento specifico della giornata o da qualche specifico evento. In questa ipotetica situazione l’applicazione potrebbe generare un file chiamato ",["code","appointments.csv"]," contenente i dati tabulati con tutti gli appuntamenti per il giorno successivo, poi usato da ",["code","sed"]," per visualizzare i messaggi di testo da un file modello chiamato ",["code","template.txt"]," . I file CSV sono un modo standard per esportare i dati dalle query del database, quindi gli appuntamenti di esempio potrebbero essere forniti come segue:"],["pre","$ ",["strong","cat appointments.csv"],"\n\"NAME\",\"TIME\",\"PHONE\"\n\"Carol\",\"11am\",\"55557777\"\n\"Dave\",\"2pm\",\"33334444\""],["p","La prima riga contiene le etichette per ogni colonna, che verranno utilizzate per abbinare i tag all’interno del file modello di esempio:"],["pre","$ ",["strong","cat template.txt"],"\nHey <NAME>, don't forget your appointment tomorrow at <TIME>."],["p","I segni minore di ",["code","<"]," e maggiore di ",["code",">"]," sono stati posti attorno alle etichette solo per aiutare a identificarli come tag. Il seguente script Bash analizza tutti gli appuntamenti accodati usando ",["code","template.txt"]," come modello di messaggio:"],["pre","#! /bin/bash\n\nTEMPLATE=`cat template.txt`\nTAGS=(`sed -ne '1s/^\"//;1s/\",\"/\\n/g;1s/\"$//p' appointments.csv`)\nmapfile -t -s 1 ROWS < appointments.csv\nfor (( r = 0; r < ${#ROWS[*]}; r++ ))\ndo\n  MSG=$TEMPLATE\n  VALS=(`sed -e 's/^\"//;s/\",\"/\\n/g;s/\"$//' <<<${ROWS[$r]}`)\n  for (( c = 0; c < ${#TAGS[*]}; c++ ))\n  do\n    MSG=`sed -e \"s/<${TAGS[$c]}>/${VALS[$c]}/g\" <<<\"$MSG\"`\n  done\n  echo curl --data message=\\\"$MSG\\\" --data phone=\\\"${VALS[2]}\\\" https://mysmsprovider/api\ndone"],["p","Uno script in produzione gestirà anche l’autenticazione, il controllo degli errori e la registrazione, ma l’esempio ha funzionalità di base con cui iniziare. Le prime istruzioni eseguite da ",["code","sed"]," sono applicate solo alla prima riga: l’indirizzo ",["code","1"]," in ",["code","1s/^\"//;1s/\",\"/\\n/g;1s/\"$//p"]," — per rimuovere le virgolette iniziali e finali — ",["code","1s/^\"//"]," e ",["code","1s/\"$//"]," — e per sostituire i separatori di campo con un carattere di nuova riga: ",["code","1s /\",\"/\\n/g"],". Solo la prima riga è necessaria per caricare i nomi delle colonne, quindi le righe non corrispondenti verranno soppresse dall’opzione ",["code","-n"],", richiedendo che il flag ",["code","p"]," sia posto dopo l’ultimo comando ",["code","sed"]," per stampare la riga corrispondente. I tag vengono quindi memorizzati nella variabile ",["code","TAGS"]," come un array Bash. Un’altra variabile dell'",["em","array"]," Bash viene creata dal comando ",["code","mapfile"]," per memorizzare le righe contenenti gli appuntamenti nella variabile dell’array ",["code","ROWS"],"."],["p","Un ciclo ",["code","for"]," viene utilizzato per elaborare ogni riga di appuntamento trovata in ",["code","ROWS"],". Quindi, virgolette e separatori nell’appuntamento — l’appuntamento è nella variabile ",["code","${ROWS[$r]}"]," usata come ",["em","here string"]," — vengono sostituiti da ",["code","sed"],", in modo simile ai comandi usati per caricare i tag. I valori separati per l’appuntamento vengono quindi memorizzati nella variabile di array ",["code","VALS"],", dove gli indici di array 0, 1 e 2 corrispondono ai valori di ",["code","NAME"],", ",["code","TIME"]," e ",["code","PHONE"],"."],["p","Infine, un ciclo annidato ",["code","for"]," percorre l’array ",["code","TAGS"]," e sostituisce ogni tag trovato nel modello con il valore corrispondente in ",["code","VALS"],". La variabile ",["code","MSG"]," contiene una copia del modello renderizzato, aggiornato dal comando di sostituzione ",["code","s/<${TAGS[$ c]}>/${VALS[$c]}/g"]," ad ogni ciclo che passa attraverso ",["code","TAGS"],"."],["p","Ciò si traduce in un messaggio visualizzato come: ",["code","\"Ehi Carol, non dimenticare il tuo appuntamento domani alle 11:00.\""]," Il messaggio visualizzato può quindi essere inviato come parametro tramite una richiesta HTTP con ",["code","curl"],", come messaggio di posta elettronica o un altro metodo simile"],["h3","Combinare grep e sed"],["p","I comandi ",["code","grep"]," e ",["code","sed"]," possono essere usati insieme quando sono richieste procedure di ",["em","text mining"]," più complesse. In qualità di amministratore di sistema, potresti voler controllare tutti i tentativi di accesso a un server. Per esempio, il file ",["code","/var/log/wtmp"]," registra tutti i login e logout, mentre il file ",["code","/var/log/btmp"]," registra i tentativi di login falliti. Sono scritti in un formato binario, che può essere letto rispettivamente dai comandi ",["code","last"]," e ",["code","lastb"],"."],["p","L’output di ",["code","lastb"]," mostra non solo il nome utente utilizzato nel tentativo di accesso errato, ma anche il suo indirizzo IP:"],["pre","# ",["strong","lastb -d -a -n 10 --time-format notime"],"\nuser     ssh:notty       (00:00)     81.161.63.251\nnrostagn ssh:notty       (00:00)     vmd60532.contaboserver.net\npi       ssh:notty       (00:00)     132.red-88-20-39.staticip.rima-tde.net\npi       ssh:notty       (00:00)     132.red-88-20-39.staticip.rima-tde.net\npi       ssh:notty       (00:00)     46.6.11.56\npi       ssh:notty       (00:00)     46.6.11.56\nnps      ssh:notty       (00:00)     vmd60532.contaboserver.net\nnarmadan ssh:notty       (00:00)     vmd60532.contaboserver.net\nnominati ssh:notty       (00:00)     vmd60532.contaboserver.net\nnominati ssh:notty       (00:00)     vmd60532.contaboserver.net"],["p","L’opzione ",["code","-d"]," traduce l’indirizzo IP nel nome host corrispondente. Il nome host può fornire indizi sull’ISP o sul servizio di hosting utilizzato per eseguire questi tentativi di accesso errati. L’opzione ",["code","-a"]," inserisce il nome host nell’ultima colonna, il che facilita il filtraggio ancora da applicare. L’opzione ",["code","--time-format notime"]," sopprime l’ora in cui si è verificato il tentativo di accesso. Il comando ",["code","lastb"]," può richiedere del tempo per terminare se ci sono stati troppi tentativi di accesso errati, quindi l’output è stato limitato a dieci voci con l’opzione ",["code","-n 10"],"."],["p","Non tutti gli IP remoti hanno un nome host associato, quindi il DNS inverso non si applica a loro e possono essere ignorati. Sebbene sia possibile scrivere un’espressione regolare che corrisponda al formato previsto per un nome host alla fine della riga, è probabilmente più semplice scrivere un’espressione regolare da abbinare a una lettera dell’alfabeto o a una singola cifra alla fine del linea. L’esempio seguente mostra come il comando ",["code","grep"]," prende l’elenco nel suo standard input e rimuove le righe senza nomi host:"],["pre","# ",["strong","lastb -d -a --time-format notime | grep -v '[0-9]$' | head -n 10"],"\nnvidia   ssh:notty       (00:00)     vmd60532.contaboserver.net\nn_tonson ssh:notty       (00:00)     vmd60532.contaboserver.net\nnrostagn ssh:notty       (00:00)     vmd60532.contaboserver.net\npi       ssh:notty       (00:00)     132.red-88-20-39.staticip.rima-tde.net\npi       ssh:notty       (00:00)     132.red-88-20-39.staticip.rima-tde.net\nnps      ssh:notty       (00:00)     vmd60532.contaboserver.net\nnarmadan ssh:notty       (00:00)     vmd60532.contaboserver.net\nnominati ssh:notty       (00:00)     vmd60532.contaboserver.net\nnominati ssh:notty       (00:00)     vmd60532.contaboserver.net\nnominati ssh:notty       (00:00)     vmd60532.contaboserver.net"],["p","L’opzione ",["code","-v"]," del comando ",["code","grep"]," mostra solo le righe che non corrispondono all’espressione regolare data. Un’espressione regolare che corrisponde a qualsiasi riga che termina con un numero (per esempio ",["code","[0-9]$"],") catturerà solo le voci senza un nome host. Pertanto, ",["code","grep -v '[0-9]$'"]," mostrerà solo le righe che finiscono con un nome host."],["p","L’output può essere ulteriormente filtrato, mantenendo solo il nome di dominio e rimuovendo le altre parti da ogni riga. Il comando ",["code","sed"]," può farlo con un comando di sostituzione per modificare l’intera riga con un riferimento al nome di dominio in essa contenuto:"],["pre","# ",["strong","lastb -d -a --time-format notime | grep -v '[0-9]$' | sed -e 's/.* \\(.*\\)$/\\1/' | head -n 10"],"\nvmd60532.contaboserver.net\nvmd60532.contaboserver.net\nvmd60532.contaboserver.net\n132.red-88-20-39.staticip.rima-tde.net\n132.red-88-20-39.staticip.rima-tde.net\nvmd60532.contaboserver.net\nvmd60532.contaboserver.net\nvmd60532.contaboserver.net\nvmd60532.contaboserver.net\nvmd60532.contaboserver.net"],["p","La parentesi con ",["em","escape"]," in ",["code",".* \\(.*\\)$"]," indica a ",["code","sed"]," di ricordare quella parte della riga, cioè la parte tra l’ultimo carattere di spazio e la fine della riga. Nell’esempio, questa parte viene referenziata con ",["code","\\ 1"]," e viene utilizzata la sostituzione dell’intera riga."],["p","È chiaro che la maggior parte degli host remoti tenta di accedere più di una volta, quindi lo stesso nome di dominio si ripete. Per sopprimere le voci ripetute, prima devono essere ordinate (con il comando ",["code","sort"],") quindi passate al comando ",["code","uniq"],":"],["pre","# ",["strong","lastb -d -a --time-format notime | grep -v '[0-9]$' | sed -e 's/.* \\(.*\\)$/\\1/' | sort | uniq | head -n 10"],"\n116-25-254-113-on-nets.com\n132.red-88-20-39.staticip.rima-tde.net\n145-40-33-205.power-speed.at\ntor.laquadrature.net\ntor.momx.site\nua-83-226-233-154.bbcust.telenor.se\nvmd38161.contaboserver.net\nvmd60532.contaboserver.net\nvmi488063.contaboserver.net\nvmi515749.contaboserver.net"],["p","Questo mostra come sia possibile combinare diversi comandi per produrre il risultato desiderato. L’elenco dei nomi host può quindi essere utilizzato per scrivere regole di blocco del firewall o per adottare altre misure per rafforzare la sicurezza del server."],["h2","Esercizi Guidati"],["ol",["li",["p","Il comando ",["code","last"]," mostra un elenco degli ultimi utenti che hanno effettuato un accesso sul sistema, inclusi i loro IP di origine. Come verrebbe usato il comando ",["code","egrep"]," per filtrare l’output di ",["code","last"],", mostrando solo le occorrenze di un indirizzo IPv4, scartando qualsiasi informazione aggiuntiva nella riga corrispondente?"]," ",["table",["tr",["td"]]]],["li",["p","Quale opzione dovrebbe essere data a ",["code","grep"]," per filtrare correttamente l’output generato dal comando ",["code","find"]," eseguito con l’opzione ",["code","-print0"],"?"]," ",["table",["tr",["td"]]]],["li",["p","Il comando ",["code","uptime -s"]," mostra l’ultima data in cui il sistema è stato acceso, come in ",["code","2019-08-05 20:13:22"],". Quale sarà il risultato del comando ",["code","uptime -s | sed -e 's/(.*) (.*)/\\1/'"],"?"]," ",["table",["tr",["td"]]]],["li",["p","Quale opzione dovrebbe essere data a ",["code","grep"]," in modo che conti le linee corrispondenti invece di visualizzarle?"]," ",["table",["tr",["td"]]]]],["h2","Esercizi Esplorativi"],["ol",["li",["p","La struttura di base di un file HTML inizia con gli elementi ",["code","html"],", ",["code","head"]," e ",["code","body"],", per esempio:"],"   ",["pre","<html>\n<head>\n  <title>News Site</title>\n</head>\n<body>\n  <h1>Headline</h1>\n  <p>Information of interest.</p>\n</body>\n</html>"],"    ",["p","Descrivi come gli indirizzi potrebbero essere usati in ",["code","sed"]," per visualizzare solo l’elemento ",["code","body"]," e il suo contenuto."],"  ",["table",["tr",["td"]]]],["li",["p","Quale espressione di ",["code","sed"]," rimuoverà tutti i tag da un documento HTML, mantenendo solo il testo visualizzato?"]," ",["table",["tr",["td"]]]],["li",["p","I file con estensione ",["code",".ovpn"]," sono molto popolari per configurare i client VPN poiché contengono non solo le impostazioni, ma anche il contenuto delle chiavi e dei certificati per il client. Queste chiavi e certificati sono originariamente in file separati, quindi devono essere copiati nel file ",["code",".ovpn"],". Dato il seguente estratto di un modello ",["code",".ovpn"],":"],"   ",["pre","client\ndev tun\nremote 192.168.1.155 1194\n<ca>\nca.crt\n</ca>\n<cert>\nclient.crt\n</cert>\n<key>\nclient.key\n</key>\n<tls-auth>\nta.key\n</tls-auth>"],"    ",["p","Supponendo che i file ",["code","ca.crt"],", ",["code","client.crt"],", ",["code","client.key"]," e ",["code","ta.key"]," si trovino nella directory corrente, come verrebbe modificata la configurazione del modello di ",["code","sed"]," per sostituire ogni nome di file con il suo contenuto?"],"  ",["table",["tr",["td"]]]]],["h2","Sommario"],["p","Questa lezione copre i due comandi Linux più importanti relativi alle espressioni regolari: ",["code","grep"]," e ",["code","sed"],". Script e comandi composti si basano su ",["code","grep"]," e ",["code","sed"]," per eseguire un’ampia gamma di operazioni di filtraggio e analisi del testo. La lezione segue i seguenti passaggi"],["ul",["li",["p","Come usare ",["code","grep"]," e le sue varianti come ",["code","egrep"]," e ",["code","fgrep"],"."]],["li",["p","Come usare ",["code","sed"]," e le sue istruzioni interne per manipolare il testo."]],["li",["p","Esempi di applicazioni di espressioni regolari che utilizzano ",["code","grep"]," e ",["code","sed"],"."]]],["h2","Risposte agli Esercizi Guidati"],["ol",["li",["p","Il comando ",["code","last"]," mostra un elenco degli ultimi utenti che hanno effettuato un accesso sul sistema, inclusi i loro IP di origine. Come verrebbe usato il comando ",["code","egrep"]," per filtrare l’output di ",["code","last"],", mostrando solo le occorrenze di un indirizzo IPv4, scartando qualsiasi informazione aggiuntiva nella riga corrispondente?"],"  ",["p",["code","last -i | egrep -o '[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}'"]]],["li",["p","Quale opzione dovrebbe essere data a ",["code","grep"]," per filtrare correttamente l’output generato dal comando ",["code","find"]," eseguito con l’opzione ",["code","-print0"],"?"],"  ",["p","L’opzione ",["code","-z"]," o ",["code","--null-data"],", come in ",["code","find . -print0 | grep -z expression"],"."]],["li",["p","Il comando ",["code","uptime -s"]," mostra l’ultima data in cui il sistema è stato acceso, come in ",["code","2019-08-05 20:13:22"],". Quale sarà il risultato del comando ",["code","uptime -s | sed -e 's/(.*) (.*)/\\1/'"],"?"],"  ",["p","Si verificherà un errore. Per impostazione predefinita, le parentesi dovrebbero essere precedute da caratteri di escape per utilizzare i riferimenti a ritroso in ",["code","sed"],"."]],["li",["p","Quale opzione dovrebbe essere data a ",["code","grep"]," in modo che conti le linee corrispondenti invece di visualizzarle?"],"  ",["p","L’opzione ",["code","-c"],"."]]],["h2","Risposte agli Esercizi Esplorativi"],["ol",["li",["p","La struttura di base di un file HTML inizia con gli elementi ",["code","html"],", ",["code","head"]," e ",["code","body"],", per esempio:"],"   ",["pre","<html>\n<head>\n  <title>News Site</title>\n</head>\n<body>\n  <h1>Headline</h1>\n  <p>Information of interest.</p>\n</body>\n</html>"],"    ",["p","Descrivi come gli indirizzi potrebbero essere usati in ",["code","sed"]," per visualizzare solo l’elemento ",["code","body"]," e il suo contenuto."],"   ",["p","Per mostrare solo ",["code","body"],", gli indirizzi dovrebbero essere ",["code","/<body>/,/<\\/body>/"],", come in ",["code","sed -n -e '/<body>/,/<\\/body>/p'"],". L’opzione ",["code","-n"]," è data a ",["code","sed"]," quindi non stampa le righe per impostazione predefinita, da qui il comando ",["code","p"]," alla fine dell’espressione ",["code","sed"]," per stampare le righe corrispondenti."]],["li",["p","Quale espressione di ",["code","sed"]," rimuoverà tutti i tag da un documento HTML, mantenendo solo il testo visualizzato?"],"  ",["p","L’espressione ",["code","sed"]," ",["code","s/<[^>]*>//g"]," sostituirà qualsiasi contenuto racchiuso in ",["code","<>"]," con una stringa vuota."]],["li",["p","I file con estensione ",["code",".ovpn"]," sono molto popolari per configurare i client VPN poiché contengono non solo le impostazioni, ma anche il contenuto delle chiavi e dei certificati per il client. Queste chiavi e certificati sono originariamente in file separati, quindi devono essere copiati nel file ",["code",".ovpn"],". Dato il seguente estratto di un modello ",["code",".ovpn"],":"],"   ",["pre","client\ndev tun\nremote 192.168.1.155 1194\n<ca>\nca.crt\n</ca>\n<cert>\nclient.crt\n</cert>\n<key>\nclient.key\n</key>\n<tls-auth>\nta.key\n</tls-auth>"],"    ",["p","Supponendo che i file ",["code","ca.crt"],", ",["code","client.crt"],", ",["code","client.key"]," e ",["code","ta.key"]," si trovino nella directory corrente, come verrebbe modificata la configurazione del modello di ",["code","sed"]," per sostituire ogni nome di file con il suo contenuto?"],"   ",["p","Il comando"],"    ",["pre","sed -r -e 's/(^[^.]*)\\.(crt|key)$/cat \\1.\\2/e' < client.template > client.ovpn"],"    ",["p","sostituisce qualsiasi riga che termini in ",["code",".crt"]," o ",["code",".key"]," con il contenuto di un file il cui nome è uguale alla riga. L’opzione ",["code","-r"]," dice a ",["code","sed"]," di usare espressioni regolari estese, mentre ",["code","e"]," alla fine dell’espressione dice a ",["code","sed"]," di sostituire le corrispondenze con l’output del comando ",["code","cat \\1.\\2"],". I riferimenti a ritroso ",["code","\\1"]," e ",["code","\\2"]," corrispondono al nome del file e all’estensione trovati nella corrispondenza."]]]]},{"id":"105.2_01","objective":"105.2","title":"105.2 Lezione 1","url":"https://learning.lpi.org/it/learning-materials/102-500/105/105.2/105.2_01/","notice":"Linux Professional Institute Inc. Tutti i diritti riservati. Visita il sito Learning Materials: https://learning.lpi.org Quest'opera è sotto la licenza 'Creative Commons Attribution-NonCommercial-NoDerivatives 4.0 International License'.","body":[["h1","105.2 Lezione 1"],["table",["tr",["th",["p","Certificazione:"]],["td",["p","LPIC-1"]]],["tr",["th",["p","Versione:"]],["td",["p","5.0"]]],["tr",["th",["p","Argomento:"]],["td",["p","105 Shell e Script di Shell"]]],["tr",["th",["p","Obiettivo:"]],["td",["p","105.2 Personalizzare o scrivere semplici script"]]],["tr",["th",["p","Lezione:"]],["td",["p","1 di 2"]]]],["h2","Introduzione"],["p","L’ambiente shell di Linux consente l’uso di file — chiamati ",["em","script"]," — contenenti comandi disponibili nel sistema in combinazione con comandi incorporati nella shell per automatizzare le attività di un utente e/o di un sistema. In effetti, molte delle attività di manutenzione del sistema operativo vengono eseguite da script costituiti da sequenze di comandi, strutture decisionali e cicli condizionali. Sebbene gli script siano per la maggior parte del tempo destinati ad attività relative al sistema operativo stesso, sono utili anche per attività orientate all’utente, come la ridenominazione di massa dei file, la raccolta e l’analisi dei dati o qualsiasi attività da riga di comando altrimenti ripetitiva."],["p","Gli script non sono altro che file di testo che si comportano come programmi. L'",["em","interprete"],", un programma vero e proprio, legge ed esegue le istruzioni elencate nel file di script. L’interprete può anche avviare una sessione interattiva in cui i comandi, inclusi gli script, vengono letti ed eseguiti non appena vengono immessi, come nel caso delle sessioni della shell di Linux. I file di script possono raggruppare tali istruzioni e comandi quando diventano troppo complessi per essere implementati come alias o come funzione di shell personalizzata. Inoltre, i file di script possono essere mantenuti come i programmi convenzionali e, essendo solo file di testo, possono essere creati e modificati con qualsiasi semplice editor di testo."],["h3","Struttura degli Script ed Esecuzione"],["p","Fondamentalmente, un file di script è una sequenza ordinata di comandi che deve essere eseguita da un interprete di comandi corrispondente. Il modo in cui un interprete legge un file di script varia e ci sono modi diversi per farlo in una sessione della shell Bash, ma l’interprete predefinito per un file di script sarà quello indicato nella prima riga dello script, subito dopo i caratteri ",["code","#!"],"(noto come ",["em","shebang"],"). In uno script con le istruzioni per la shell Bash, la prima riga dovrebbe essere ",["code","#!/bin/bash"],". Indicando questa riga, l’interprete per tutte le istruzioni nel file sarà ",["code","/bin/bash"],". Ad eccezione della prima riga, tutte le altre righe che iniziano con il carattere cancelletto \"#\" verranno ignorate, quindi possono essere utilizzate per inserire promemoria e commenti. Anche le righe vuote vengono ignorate. Un file script di shell molto conciso può quindi essere scritto come segue:"],["pre","#!/bin/bash\n\n# Uno script molto semplice\n\necho \"Cheers from the script file! Current time is: \"\n\ndate +%H:%M"],["p","Questo script ha solo due istruzioni per l’interprete ",["code","/bin/bash"],": il comando integrato ",["code","echo"]," e il comando ",["code","date"],". Il modo più semplice per eseguire un file di script è eseguire l’interprete con il percorso dello script come argomento. Quindi, supponendo che l’esempio precedente sia stato salvato in un file di script chiamato ",["code","script.sh"]," nella directory corrente, verrà letto e interpretato da Bash con il seguente comando:"],["pre","$ ",["strong","bash script.sh"],"\nCheers from the script file! Current time is:\n10:57"],["p","Il comando ",["code","echo"]," aggiungerà automaticamente una nuova riga dopo aver visualizzato il contenuto, ma l’opzione ",["code","-n"]," sopprimerà questo comportamento. Quindi, usando ",["code","echo -n"]," nello script, l’output di entrambi i comandi apparirà nella stessa riga:"],["pre","$ ",["strong","bash script.sh"],"\nCheers from the script file! Current time is: 10:57"],["p","Sebbene non sia richiesto, il suffisso ",["code",".sh"]," aiuta a identificare gli script di shell quando si elencano e si cercano i file."],["note","Suggerimento",["p","Bash chiamerà qualunque comando sia indicato dopo ",["code","#!"]," come interprete per il file di script. Può essere utile, per esempio, utilizzare lo ",["em","shebang"]," per altri linguaggi di scripting, come ",["em","Python"]," (",["code","#!/usr/bin/python"],"), ",["em","Perl"]," (",["code","#!/usr/bin/perl"],") o ",["em","awk"]," (",["code","#!/usr/bin/awk"],")."]],["p","Se il file di script deve essere eseguito da altri utenti nel sistema, è importante verificare se sono impostate le autorizzazioni di lettura corrette. Il comando ",["code","chmod o+r script.sh"]," darà il permesso di lettura a tutti gli utenti nel sistema, consentendo loro di eseguire ",["code","script.sh"]," inserendo il percorso del file script come argomento del comando ",["code","bash"],". In alternativa, il file di script può avere il permesso di esecuzione impostato in modo che il file possa essere eseguito come un comando convenzionale. Il bit di esecuzione viene attivato sul file di script con il comando ",["code","chmod"],":"],["pre","$ ",["strong","chmod +x script.sh"]],["p","Con il bit di esecuzione abilitato, il file di script denominato ",["code","script.sh"]," nella directory corrente può essere eseguito direttamente con il comando ",["code","./script.sh"],". Gli script inseriti in una directory elencata nella variabile d’ambiente ",["code","PATH"]," saranno accessibili anche senza il loro percorso completo."],["note","Nota",["p","Uno script che esegue azioni limitate può avere il suo permesso SUID attivato, quindi gli utenti ordinari possono anche eseguire lo script con i privilegi di root. In questo caso, è molto importante assicurarsi che nessun utente diverso da root abbia il permesso di scrivere nel file. In caso contrario, un utente normale potrebbe modificare il file per eseguire operazioni arbitrarie e potenzialmente dannose."]],["p","Il posizionamento e il rientro dei comandi nei file di script non sono troppo rigidi. Ogni riga in uno script di shell verrà eseguita come un normale comando di shell, nella stessa sequenza in cui la riga appare nel file di script e le stesse regole che si applicano al prompt della shell si applicano anche a ciascuna riga di script individualmente. È possibile inserire due o più comandi nella stessa riga, separati da punto e virgola:"],["pre","echo \"Cheers from the script file! Current time is:\" ; date +%H:%M"],["p","Sebbene questo formato possa essere a volte conveniente, il suo utilizzo è facoltativo, poiché i comandi sequenziali possono essere inseriti un comando per riga e verranno eseguiti proprio come se fossero separati da punto e virgola. In altre parole, il punto e virgola può essere sostituito da un nuovo carattere di riga nei file di script Bash."],["p","Quando viene eseguito uno script, i comandi in esso contenuti non vengono eseguiti direttamente nella sessione corrente, ma vengono invece eseguiti da un nuovo processo Bash, chiamato ",["em","sub-shell"],". Impedisce allo script di sovrascrivere le variabili di ambiente della sessione corrente e di lasciare le modifiche automatiche nella sessione corrente. Se l’obiettivo è eseguire il contenuto dello script nella sessione corrente della shell, allora dovrebbe essere eseguito con ",["code","source script.sh"]," o ",["code",". script.sh"]," (nota che c’è uno spazio tra il punto e il nome dello script)."],["p","Come accade con l’esecuzione di qualsiasi altro comando, il prompt della shell sarà nuovamente disponibile solo quando lo script avrà terminato la sua esecuzione e il suo codice di stato di uscita sarà disponibile nella variabile ",["code","$?"],". Per cambiare questo comportamento, in modo che anche la shell corrente termini quando lo script finisce, lo script — o qualsiasi altro comando — può essere preceduto dal comando ",["code","exec"],". Questo comando sostituirà anche il codice dello stato di uscita della sessione di shell corrente con il proprio."],["h3","Variabili"],["p","Le variabili negli script di shell si comportano allo stesso modo delle sessioni interattive, dato che l’interprete è lo stesso. Per esempio, il formato ",["code","SOLUTION=42"]," (senza spazi attorno al segno di uguale) assegnerà il valore ",["code","42"]," alla variabile denominata ",["code","SOLUTION"],". Per convenzione, le lettere maiuscole vengono utilizzate per i nomi delle variabili, ma non è obbligatorio. Tuttavia, i nomi delle variabili non possono iniziare con caratteri non alfabetici."],["p","Oltre alle normali variabili create dall’utente, gli script Bash hanno anche una serie di variabili speciali chiamate parametri o ",["em","parameters"],". A differenza delle variabili ordinarie, i nomi dei parametri iniziano con un carattere non alfabetico che ne designa la funzione. Gli argomenti passati a uno script e altre informazioni utili sono memorizzati in parametri come ",["code","$0"],", ",["code","$*"],", ",["code","$?"],", ecc., Dove il carattere che segue il segno del dollaro indica le informazioni da recuperare:"],["dl",["dt",["code","$*"]],["dd",["p","Tutti gli argomenti passati allo script."]],["dt",["code","$@"]],["dd",["p","Tutti gli argomenti passati allo script. Se usato con virgolette doppie, come in ",["code","\"$@\""],", ogni argomento sarà racchiuso tra virgolette doppie."]],["dt",["code","$#"]],["dd",["p","Il numero degli argomenti."]],["dt",["code","$0"]],["dd",["p","Il nome del file di script."]],["dt",["code","$!"]],["dd",["p","PID dell’ultimo programma eseguito."]],["dt",["code","$$"]],["dd",["p","PID della shell corrente."]],["dt",["code","$?"]],["dd",["p","Codice numerico di stato di uscita dell’ultimo comando terminato. Per i processi standard POSIX, un valore numerico di ",["code","0"]," significa che l’ultimo comando è stato eseguito con successo, il che si applica anche agli script di shell."]]],["p","Un ",["em","parametro posizionale"]," è un parametro indicato da una o più cifre, diverse dalla singola cifra ",["code","0"],". Per esempio, la variabile ",["code","$1"]," corrisponde al primo argomento fornito allo script (parametro posizionale uno), ",["code","$2"]," corrisponde al secondo argomento e così via. Se la posizione di un parametro è maggiore di nove, deve essere referenziato con parentesi graffe, come in ",["code","${10}"],", ",["code","${11}"],", ecc."],["p","Le variabili ordinarie, invece, hanno lo scopo di memorizzare valori inseriti manualmente o l’output generato da altri comandi. Il comando ",["code","read"],", per esempio, può essere utilizzato all’interno dello script per chiedere all’utente un input durante l’esecuzione dello script:"],["pre","echo \"Do you want to continue (y/n)?\"\nread ANSWER"],["p","Il valore restituito verrà memorizzato nella variabile ",["code","ANSWER"],". Se il nome della variabile non viene fornito, per impostazione predefinita verrà utilizzato il nome della variabile ",["code","REPLY"],". È anche possibile utilizzare il comando ",["code","read"]," per leggere più di una variabile contemporaneamente:"],["pre","echo \"Type your first name and last name:\"\nread NAME SURNAME"],["p","In questo caso, ogni termine separato da spazi verrà assegnato rispettivamente alle variabili ",["code","NAME"]," e ",["code","SURNAME"],". Se il numero di termini dati è maggiore del numero di variabili, i termini in eccesso verranno memorizzati nell’ultima variabile. Lo stesso ",["code","read"]," può mostrare il messaggio all’utente con l’opzione ",["code","-p"],", rendendo ridondante il comando ",["code","echo"]," in questo caso:"],["pre","read -p \"Type your first name and last name:\" NAME SURNAME"],["p","Gli script che eseguono attività di sistema richiedono spesso informazioni fornite da altri programmi. La notazione ",["em","backtick"]," può essere utilizzata per memorizzare l’output di un comando in una variabile:"],["pre","$ ",["strong","OS=`uname -o`"]],["p","Nell’esempio, l’output del comando ",["code","uname -o"]," sarà memorizzato nella variabile ",["code","OS"],". Un risultato identico verrà prodotto con ",["code","$()"],":"],["pre","$ ",["strong","OS=$(uname -o)"]],["p","La lunghezza di una variabile, ovvero la quantità di caratteri che contiene, viene restituita anteponendo un cancelletto ",["code","#"]," prima del nome della variabile. Questa caratteristica, tuttavia, richiede l’uso della sintassi delle parentesi graffe per indicare la variabile:"],["pre","$ ",["strong","OS=$(uname -o)"],"\n$ ",["strong","echo $OS"],"\nGNU/Linux\n$ ",["strong","echo ${#OS}"],"\n9"],["p","Bash dispone anche di ",["em","variabili array unidimensionali"],", quindi un insieme di elementi correlati può essere memorizzato con un unico nome di variabile. Ogni elemento in un array ha un indice numerico, che deve essere utilizzato per scrivere e leggere i valori nell’elemento corrispondente. Diversamente dalle variabili ordinarie, gli array devono essere dichiarati con il comando integrato di Bash ",["code","declare"],". Per esempio, per dichiarare una variabile denominata ",["code","SIZES"]," come un array:"],["pre","$ ",["strong","declare -a SIZES"]],["p","Gli array possono anche essere dichiarati implicitamente quando popolati da un elenco predefinito di elementi, utilizzando la notazione tra parentesi:"],["pre","$ ",["strong","SIZES=( 1048576 1073741824 )"]],["p","Nell’esempio, i due valori interi grandi sono stati memorizzati nell’array ",["code","SIZES"],". Gli elementi della matrice devono essere referenziati utilizzando parentesi graffe e parentesi quadre, altrimenti Bash non modificherà o visualizzerà l’elemento correttamente. Poiché gli indici dell’array iniziano da 0, il contenuto del primo elemento è in ",["code","${SIZES[0]}"],", il secondo elemento è in ",["code","${SIZES[1]}"]," e così via:"],["pre","$ ",["strong","echo ${SIZES[0]}"],"\n1048576\n$ ",["strong","echo ${SIZES[1]}"],"\n1073741824"],["p","A differenza della lettura, la modifica del contenuto di un elemento dell’array viene eseguita senza le parentesi graffe (Per esempio, ",["code","SIZES[0]=1048576"],"). Come con le variabili ordinarie, la lunghezza di un elemento in un array viene restituita con il carattere cancelletto (per esempio, ",["code","${#SIZES[0]}"]," per la lunghezza del primo elemento nell’array ",["code","SIZES"],"). Il numero totale di elementi in un array viene restituito se ",["code","@"]," o ",["code","*"]," sono usati come indice:"],["pre","$ ",["strong","echo ${#SIZES[@]}"],"\n2\n$ ",["strong","echo ${#SIZES[*]}"],"\n2"],["p","Gli array possono anche essere dichiarati utilizzando l’output di un comando come elementi iniziali tramite la sostituzione del comando. Il seguente esempio mostra come creare un array Bash i cui elementi sono i filesystem supportati dal sistema corrente:"],["pre","$ ",["strong","FS=( $(cut -f 2 < /proc/filesystems) )"]],["p","Il comando ",["code","cut -f 2 < /proc/filesystems"]," mostrerà tutti i filesystem attualmente supportati dal kernel in esecuzione (come elencato nella seconda colonna del file ",["code","/proc/filesystems"],"), quindi l’array ",["code","FS"]," ora contiene un elemento per ogni filesystem supportato. Qualsiasi contenuto di testo può essere utilizzato per inizializzare un array poiché, per impostazione predefinita, qualsiasi termine delimitato da caratteri ",["em","space"],", ",["em","tab"]," o ",["em","newline"]," diventerà un elemento dell’array."],["note","Suggerimento",["p","Bash tratta ogni carattere di ",["code","$IFS"]," (",["em","Input Field Separator"],") di una variabile d’ambiente come un delimitatore. Per cambiare il delimitatore di campo solo con caratteri di nuova riga, per esempio, la variabile IFS dovrebbe essere reimpostata con il comando ",["code","IFS=$'\\n'"],"."]],["h3","Espressioni Aritmetiche"],["p","Bash fornisce un metodo pratico per eseguire operazioni aritmetiche su interi con il comando incorporato ",["code","expr"],". Due variabili numeriche, per esempio ",["code","$VAL1"]," e ",["code","$VAL2"],", possono essere aggiunte insieme al seguente comando:"],["pre","$ ",["strong","SUM=`expr $VAL1 + $VAL2`"]],["p","Il valore risultante dell’esempio sarà disponibile nella variabile ",["code","$SUM"],". Il comando ",["code","expr"]," può essere sostituito da ",["code","$(())"],", quindi l’esempio precedente può essere riscritto come ",["code","SUM=$(($VAL1+$VAL2))"],". Le espressioni di potenza sono consentite anche con l’operatore doppio asterisco, quindi la precedente dichiarazione di array ",["code","SIZES=(1048576 1073741824)"]," potrebbe essere riscritta come ",["code","SIZES=( $((1024**2)) $((1024**3)) )"],"."],["p","La sostituzione dei comandi può essere utilizzata anche nelle espressioni aritmetiche. Per esempio, il file ",["code","/proc/meminfo"]," contiene informazioni dettagliate sulla memoria di sistema, incluso il numero di byte liberi nella RAM:"],["pre","$ ",["strong","FREE=$(( 1000 * `sed -nre '2s/[^[:digit:]]//gp' < /proc/meminfo` ))"]],["p","L’esempio mostra come utilizzare il comando ",["code","sed"]," per analizzare il contenuto di ",["code","/proc/meminfo"]," all’interno dell’espressione aritmetica. La seconda riga del file ",["code","/proc/meminfo"]," contiene la quantità di memoria libera in migliaia di byte, quindi l’espressione aritmetica la moltiplica per 1000 per ottenere il numero di byte liberi nella RAM."],["h3","Esecuzione Condizionale"],["p","Alcuni script di solito non hanno lo scopo di eseguire tutti i comandi nel file di script, ma solo quei comandi che corrispondono a criteri predefiniti. Per esempio, uno script di manutenzione può inviare un messaggio di avviso all’e-mail dell’amministratore solo se l’esecuzione di un comando non riesce. Bash fornisce metodi specifici per valutare il successo dell’esecuzione dei comandi e strutture condizionali generali, più simili a quelle che si trovano nei linguaggi di programmazione più diffusi."],["p","Separando i comandi con ",["code","&&"],", il comando a destra verrà eseguito solo se il comando a sinistra non ha riscontrato un errore, cioè se il suo stato di uscita era uguale a ",["code","0"],":"],["pre","COMMAND A && COMMAND B && COMMAND C"],["p","Il comportamento opposto si verifica se i comandi sono separati da ",["code","||"],". In questo caso, il comando seguente verrà eseguito solo se il comando precedente ha riscontrato un errore, cioè se il suo codice di stato restituito è diverso da 0."],["p","Una delle caratteristiche più importanti di tutti i linguaggi di programmazione è la capacità di eseguire comandi in base a condizioni definite in precedenza. Il modo più semplice per eseguire comandi in modo condizionale è usare il comando incorporato di Bash ",["code","if"],", che esegue uno o più comandi solo se il comando dato come argomento restituisce un codice di stato 0 (successo). Un altro comando, ",["code","test"],", può essere usato per valutare molti differenti criteri speciali, quindi è usato principalmente insieme a ",["code","if"],". Nell’esempio seguente, il messaggio ",["code","Confirmed: /bin/bash is executable."]," verrà visualizzato solo se il file ",["code","/bin/bash"]," esiste ed è eseguibile:"],["pre","if test -x /bin/bash ; then\n  echo \"Confirmed: /bin/bash is executable.\"\nfi"],["p","L’opzione ",["code","-x"]," fa sì che il comando ",["code","test"]," restituisca un codice di stato 0 solo se il percorso specificato è un file eseguibile. L’esempio seguente mostra un altro modo per ottenere lo stesso identico risultato, poiché le parentesi quadre possono essere utilizzate in sostituzione di ",["code","test"],":"],["pre","if [ -x /bin/bash ] ; then\n  echo \"Confirmed: /bin/bash is executable.\"\nfi"],["p","L’istruzione ",["code","else"]," è opzionale alla struttura ",["code","if"]," e può, se presente, definire un comando o una sequenza di comandi da eseguire se l’espressione condizionale non è vera:"],["pre","if [ -x /bin/bash ] ; then\n  echo \"Confirmed: /bin/bash is executable.\"\nelse\n  echo \"No, /bin/bash is not executable.\"\nfi"],["p","Le strutture ",["code","if"]," devono sempre finire con ",["code","fi"],", quindi l’interprete di Bash sa dove terminano i comandi condizionali."],["h3","Output di uno Script"],["p","Anche quando lo scopo di uno script coinvolge solo operazioni orientate ai file, è importante visualizzare i messaggi relativi allo stato di avanzamento nell'",["em","output standard"],", in modo che l’utente sia informato di eventuali problemi e possa eventualmente utilizzare quei messaggi per generare i log delle operazioni."],["p","Il comando integrato di Bash ",["code","echo"]," è comunemente usato per visualizzare semplici stringhe di testo, ma fornisce anche alcune funzionalità estese. Con l’opzione ",["code","-e"],", il comando ",["code","echo"]," è in grado di visualizzare caratteri speciali usando sequenze di ",["em","escape"]," (una sequenza di ",["em","backslash"]," che designa un carattere speciale). Per esempio:"],["pre","#!/bin/bash\n\n# Get the operating system's generic name\nOS=$(uname -o)\n\n# Get the amount of free memory in bytes\nFREE=$(( 1000 * `sed -nre '2s/[^[:digit:]]//gp' < /proc/meminfo` ))\n\necho -e \"Operating system:\\t$OS\"\necho -e \"Unallocated RAM:\\t$(( $FREE / 1024**2 )) MB\""],["p","Sebbene l’uso delle virgolette sia opzionale quando si usa ",["code","echo"]," senza opzioni, è necessario aggiungerle quando si usa l’opzione ",["code","-e"],", altrimenti i caratteri speciali potrebbero non essere visualizzati correttamente. Nello script precedente, entrambi i comandi ",["code","echo"]," usano il carattere di tabulazione ",["code","\\t"]," per allineare il testo, ottenendo il seguente output:"],["pre","Operating system:       GNU/Linux\nUnallocated RAM:        1491 MB"],["p","Il carattere di nuova riga ",["code","\\n"]," può essere utilizzato per separare le righe di output, quindi lo stesso identico output si ottiene combinando i due comandi ",["code","echo"]," in uno solo:"],["pre","echo -e \"Operating system:\\t$OS\\nUnallocated RAM:\\t$(( $FREE / 1024**2 )) MB\""],["p","Sebbene sia adatto per visualizzare la maggior parte dei messaggi di testo, il comando ",["code","echo"]," potrebbe non essere adatto per visualizzare modelli di testo più specifici. Il comando integrato di Bash ",["code","printf"]," dà più controllo su come visualizzare le variabili. Il comando ",["code","printf"]," usa il primo argomento come formato dell’output, dove i segnaposto saranno sostituiti dai seguenti argomenti nell’ordine in cui appaiono nella riga di comando. Per esempio, il messaggio dell’esempio precedente potrebbe essere generato con il seguente comando ",["code","printf"],":"],["pre","printf \"Operating system:\\t%s\\nUnallocated RAM:\\t%d MB\\n\" $OS $(( $FREE / 1024**2 ))"],["p","Il segnaposto ",["code","%s"]," è destinato per il contenuto di testo (sarà rimpiazzato dalla variabile ",["code","$OS"],") e il segnaposto ",["code","%d"]," è destinato a numeri interi (sarà rimpiazzato dal numero risultante di megabyte liberi nella RAM ). ",["code","printf"]," non aggiunge un carattere di nuova riga alla fine del testo, quindi il carattere di nuova riga ",["code","\\n"]," dovrebbe essere posizionato alla fine del modello se necessario. L’intero modello deve essere interpretato come un singolo argomento, quindi deve essere racchiuso tra virgolette."],["note","Suggerimento",["p","Il formato di sostituzione del segnaposto eseguita da ",["code","printf"]," può essere personalizzato usando lo stesso formato usato dalla funzione ",["code","printf"]," dal linguaggio di programmazione C. Il riferimento completo per la funzione ",["code","printf"]," può essere trovato nella sua pagina di manuale, accessibile con il comando ",["code","man 3 printf"],"."]],["p","Con ",["code","printf"],", le variabili sono poste al di fuori del ",["em","pattern"]," di testo, il che rende possibile memorizzarlo in una variabile separata:"],["pre","MSG='Operating system:\\t%s\\nUnallocated RAM:\\t%d MB\\n'\nprintf \"$MSG\" $OS $(( $FREE / 1024**2 ))"],["p","Questo metodo è particolarmente utile per visualizzare formati di output distinti, a seconda delle esigenze dell’utente. Rende più semplice, per esempio, scrivere uno script che utilizza un ",["em","pattern"]," di testo distinto se l’utente richiede un elenco CSV (",["em","Comma Separated Values"],") piuttosto che un messaggio di output predefinito."],["h2","Esercizi Guidati"],["ol",["li",["p","L’opzione ",["code","-s"]," per il comando ",["code","read"]," è utile per inserire le password, poiché non mostrerà il contenuto digitato sullo schermo. Come potrebbe essere usato il comando ",["code","read"]," per memorizzare l’input dell’utente nella variabile ",["code","PASSWORD"]," nascondendo il contenuto digitato?"]," ",["table",["tr",["td"]]]],["li",["p","L’unico scopo del comando ",["code","whoami"]," è quello di visualizzare il nome utente dell’utente che lo ha eseguito, quindi viene utilizzato principalmente all’interno degli script per identificare l’utente che lo sta eseguendo. All’interno di uno script Bash, come potrebbe essere memorizzato l’output del comando ",["code","whoami"]," nella variabile chiamata ",["code","WHO"],"?"]," ",["table",["tr",["td"]]]],["li",["p","Quale operatore Bash dovrebbe esserci tra i comandi ",["code","apt-get dist-upgrade"]," e ",["code","systemctl reboot"]," se l’utente root vuole eseguire ",["code","systemctl reboot"]," solo se ",["code","apt-get dist-upgrade"]," è terminato con successo?"]," ",["table",["tr",["td"]]]]],["h2","Esercizi Esplorativi"],["ol",["li",["p","Dopo aver tentato di eseguire uno script Bash appena creato, un utente riceve il seguente messaggio di errore:"],"   ",["pre","bash: ./script.sh: Permission denied"],"    ",["p","Considerando che il file ",["code","./script.sh"]," è stato creato dallo stesso utente, quale potrebbe essere la probabile causa di questo errore?"],"  ",["table",["tr",["td"]]]],["li",["p","Supponiamo che un file di script chiamato ",["code","do.sh"]," sia eseguibile e il collegamento simbolico chiamato ",["code","undo.sh"]," punti ad esso. Dall’interno dello script, come potresti identificare se il nome del file chiamante era ",["code","do.sh"]," o ",["code","undo.sh"],"?"]," ",["table",["tr",["td"]]]],["li",["p","In un sistema con un servizio di posta elettronica configurato correttamente, il comando ",["code","mail -s \"Maintenance Error\" root <<<\"Scheduled task error\""]," invia il messaggio di posta elettronica di avviso all’utente root. Tale comando potrebbe essere utilizzato in attività non assistite, come ",["em","cronjob"],", per informare l’amministratore di sistema di un problema imprevisto. Scrivete un costrutto ",["em","if"]," che eseguirà il suddetto comando ",["code","mail"]," se lo stato di uscita del comando precedente - -qualunque esso sia — non ha successo."]," ",["table",["tr",["td"]]]]],["h2","Sommario"],["p","Questa lezione copre i concetti base per la comprensione e la scrittura di script nella shell Bash. Gli script di shell sono una parte fondamentale di qualsiasi distribuzione Linux in quanto offrono un modo molto flessibile per automatizzare le attività dell’utente e del sistema. La lezione segue i seguenti passaggi:"],["ul",["li",["p","Struttura dello script di shell e autorizzazioni corrette del file di script"]],["li",["p","Parametri di script"]],["li",["p","Utilizzo di variabili per leggere l’input dell’utente e memorizzare l’output dei comandi"]],["li",["p","Bash array"]],["li",["p","Test semplici ed esecuzione condizionale"]],["li",["p","Formattazione dell’output"]]],["p","I comandi e le procedure affrontati sono stati:"],["ul",["li",["p","Notazione incorporata di Bash per la sostituzione dei comandi, espansione di array e espressioni aritmetiche"]],["li",["p","Esecuzione condizionale di comandi con gli operatori ",["code","||"]," e ",["code","&&"]]],["li",["p",["code","echo"]]],["li",["p",["code","chmod"]]],["li",["p",["code","exec"]]],["li",["p",["code","read"]]],["li",["p",["code","declare"]]],["li",["p",["code","test"]]],["li",["p",["code","if"]]],["li",["p",["code","printf"]]]],["h2","Risposte agli Esercizi Guidati"],["ol",["li",["p","L’opzione ",["code","-s"]," per il comando ",["code","read"]," è utile per inserire le password, poiché non mostrerà il contenuto digitato sullo schermo. Come potrebbe essere usato il comando ",["code","read"]," per memorizzare l’input dell’utente nella variabile ",["code","PASSWORD"]," nascondendo il contenuto digitato?"],"  ",["p",["code","read -s PASSWORD"]]],["li",["p","L’unico scopo del comando ",["code","whoami"]," è quello di visualizzare il nome utente dell’utente che lo ha eseguito, quindi viene utilizzato principalmente all’interno degli script per identificare l’utente che lo sta eseguendo. All’interno di uno script Bash, come potrebbe essere memorizzato l’output del comando ",["code","whoami"]," nella variabile chiamata ",["code","WHO"],"?"],"  ",["p",["code","WHO=`whoami`"]," o ",["code","WHO=$(whoami)"]]],["li",["p","Quale operatore Bash dovrebbe esserci tra i comandi ",["code","apt-get dist-upgrade"]," e ",["code","systemctl reboot"]," se l’utente root vuole eseguire ",["code","systemctl reboot"]," solo se ",["code","apt-get dist-upgrade"]," è terminato con successo?"],"  ",["p","L’operatore ",["code","&&"],", come in ",["code","apt-get dist-upgrade && systemctl reboot"],"."]]],["h2","Risposte agli Esercizi Esplorativi"],["ol",["li",["p","Dopo aver tentato di eseguire uno script Bash appena creato, un utente riceve il seguente messaggio di errore:"],"   ",["pre","bash: ./script.sh: Permission denied"],"    ",["p","Considerando che il file ",["code","./script.sh"]," è stato creato dallo stesso utente, quale potrebbe essere la probabile causa di questo errore?"],"   ",["p","Il file ",["code","./script.sh"]," non possiede il permesso di esecuzione attivo."]],["li",["p","Supponiamo che un file di script chiamato ",["code","do.sh"]," sia eseguibile e il collegamento simbolico chiamato ",["code","undo.sh"]," punti ad esso. Dall’interno dello script, come potresti identificare se il nome del file chiamante era ",["code","do.sh"]," o ",["code","undo.sh"],"?"],"  ",["p","La variabile speciale ",["code","$0"]," contiene il nome del file utilizzato per richiamare lo script."]],["li",["p","In un sistema con un servizio di posta elettronica configurato correttamente, il comando ",["code","mail -s \"Maintenance Error\" root <<<\"Scheduled task error\""]," invia il messaggio di posta elettronica di avviso all’utente root. Tale comando potrebbe essere utilizzato in attività non assistite, come ",["em","cronjob"],", per informare l’amministratore di sistema di un problema imprevisto. Scrivete un costrutto ",["em","if"]," che eseguirà il suddetto comando ",["code","mail"]," se lo stato di uscita del comando precedente - -qualunque esso sia — non ha successo."],"  ",["p",["code","if [ \"$?\" -ne 0 ]; then mail -s \"Maintenance Error\" root <<<\"Scheduled task error\"; fi"]]]]]},{"id":"105.2_02","objective":"105.2","title":"105.2 Lezione 2","url":"https://learning.lpi.org/it/learning-materials/102-500/105/105.2/105.2_02/","notice":"Linux Professional Institute Inc. Tutti i diritti riservati. Visita il sito Learning Materials: https://learning.lpi.org Quest'opera è sotto la licenza 'Creative Commons Attribution-NonCommercial-NoDerivatives 4.0 International License'.","body":[["h1","105.2 Lezione 2"],["table",["tr",["th",["p","Certificazione:"]],["td",["p","LPIC-1"]]],["tr",["th",["p","Versione:"]],["td",["p","5.0"]]],["tr",["th",["p","Argomento:"]],["td",["p","105 Shell e Script di Shell"]]],["tr",["th",["p","Obiettivo:"]],["td",["p","105.2 Personalizzare o scrivere semplici script"]]],["tr",["th",["p","Lezione:"]],["td",["p","2 di 2"]]]],["h2","Introduzione"],["p","Gli script di shell sono generalmente destinati ad automatizzare le operazioni relative a file e directory, le stesse operazioni che potrebbero essere eseguite manualmente dalla riga di comando. Tuttavia, la copertura degli script di shell non è limitata ai soli documenti di un utente, poiché anche la configurazione e l’interazione con molti aspetti di un sistema operativo Linux vengono eseguite tramite file di script. La ",["em","shell Bash"]," offre molti utili comandi ",["em","builtin"]," per scrivere script di shell, ma la piena potenza di questi script si basa sulla combinazione dei comandi incorporati di Bash con le numerose utilità della riga di comando disponibili su un sistema Linux."],["h3","Test Estesi"],["p","Bash, come linguaggio di script, è principalmente orientato a lavorare con i file, quindi il comando integrato di Bash ",["code","test"]," ha molte opzioni per valutare le proprietà degli oggetti del filesystem (essenzialmente file e directory). I test incentrati su file e directory sono utili, per esempio, per verificare se i file e le directory necessari per eseguire una determinata attività sono presenti e possono essere letti. Quindi, associato a un costrutto condizionale ",["em","if"],", il set di azioni appropriato viene eseguito se il test ha esito positivo."],["p","Il comando ",["code","test"]," può valutare espressioni usando due diverse sintassi: le espressioni di prova possono essere fornite come argomento del comando ",["code","test"]," oppure possono essere inserite tra parentesi quadre, dove il comando ",["code","test"]," è dato implicitamente. Quindi, il test per valutare se ",["code","/etc"]," è una directory valida può essere scritto come ",["code","test -d /etc"]," o come ",["code","[-d /etc]"],":"],["pre","$ ",["strong","test -d /etc"],"\n$ ",["strong","echo $?"],"\n0\n$ ",["strong","[ -d /etc ]"],"\n$ ",["strong","echo $?"],"\n0"],["p","Come confermato dai codici di stato di uscita nella variabile speciale ",["code","$?"]," — un valore di 0 significa che il test ha avuto successo — entrambe le forme hanno valutato ",["code","/etc"]," come una directory valida. Supponendo che il percorso di un file o di una directory sia stato memorizzato nella variabile ",["code","$VAR"],", le seguenti espressioni possono essere utilizzate come argomenti per ",["code","test"]," o racchiuse tra parentesi quadre:"],["dl",["dt",["code","-a \"$VAR\""]],["dd",["p","Valuta se il percorso in ",["code","VAR"]," esiste nel filesystem ed è un file."]],["dt",["code","-b \"$VAR\""]],["dd",["p","Valuta se il percorso in ",["code","VAR"]," è un file speciale a blocchi."]],["dt",["code","-c \"$VAR\""]],["dd",["p","Valuta se il percorso in ",["code","VAR"]," è un file speciale di caratteri."]],["dt",["code","-d \"$VAR\""]],["dd",["p","Valuta se il percorso in ",["code","VAR"]," è una directory."]],["dt",["code","-e \"$VAR\""]],["dd",["p","Valuta se il percorso in ",["code","VAR"]," esiste nel filesystem."]],["dt",["code","-f \"$VAR\""]],["dd",["p","Valuta se il percorso in ",["code","VAR"]," esiste ed è un file normale."]],["dt",["code","-g \"$VAR\""]],["dd",["p","Valuta se il percorso in ",["code","VAR"]," ha il permesso SGID."]],["dt",["code","-h \"$VAR\""]],["dd",["p","Valuta se il percorso in ",["code","VAR"]," è un collegamento simbolico."]],["dt",["code","-L \"$VAR\""]],["dd",["p","Valuta se il percorso in ",["code","VAR"]," è un collegamento simbolico. (come ",["code","-h"],")."]],["dt",["code","-k \"$VAR\""]],["dd",["p","Valuta se il percorso in ",["code","VAR"]," ha il permesso ",["em","sticky"]," bit."]],["dt",["code","-p \"$VAR\""]],["dd",["p","Valuta se il percorso in ",["code","VAR"]," è un file ",["em","pipe"],"."]],["dt",["code","-r \"$VAR\""]],["dd",["p","Valuta se il percorso in ",["code","VAR"]," è leggibile dall’utente corrente."]],["dt",["code","-s \"$VAR\""]],["dd",["p","Valuta se il percorso in ",["code","VAR"]," esiste e non è vuoto."]],["dt",["code","-S \"$VAR\""]],["dd",["p","Valuta se il percorso in ",["code","VAR"]," è un file socket."]],["dt",["code","-t \"$VAR\""]],["dd",["p","Valuta se il percorso in ",["code","VAR"]," è aperto in un terminale."]],["dt",["code","-u \"$VAR\""]],["dd",["p","Valuta se il percorso in ",["code","VAR"]," ha il permesso SUID."]],["dt",["code","-w \"$VAR\""]],["dd",["p","Valuta se il percorso in ",["code","VAR"]," è scrivibile dall’utente corrente."]],["dt",["code","-x \"$VAR\""]],["dd",["p","Valuta se il percorso in ",["code","VAR"]," è eseguibile dall’utente corrente."]],["dt",["code","-O \"$VAR\""]],["dd",["p","Valuta se il percorso in ",["code","VAR"]," è di proprietà dell’utente corrente."]],["dt",["code","-G \"$VAR\""]],["dd",["p","Valuta se il percorso in ",["code","VAR"]," appartiene al gruppo effettivo dell’utente corrente."]],["dt",["code","-N \"$VAR\""]],["dd",["p","Valuta se il percorso in ",["code","VAR"]," è stato modificato dall’ultimo accesso."]],["dt",["code","\"$VAR1\" -nt \"$VAR2\""]],["dd",["p","Valuta se il percorso in ",["code","VAR1"]," è più recente del percorso in ",["code","VAR2"],", in base alle date di modifica."]],["dt",["code","\"$VAR1\" -ot \"$VAR2\""]],["dd",["p","Valuta se il percorso in ",["code","VAR1"]," è più vecchio di ",["code","VAR2"],"."]],["dt",["code","\"$VAR1\" -ef \"$VAR2\""]],["dd",["p","Questa espressione restituisce ",["em","True"]," se il percorso in ",["code","VAR1"]," è un hardlink a ",["code","VAR2"],"."]]],["p","Si consiglia di utilizzare le virgolette doppie attorno a una variabile ",["em","testata"]," perché, se la variabile risulta essere vuota, potrebbe causare un errore di sintassi per il comando ",["code","test"],". Le opzioni di test richiedono un argomento e una variabile vuota non messa tra virgolette causerebbe un errore a causa di un argomento obbligatorio mancante. Esistono anche test per variabili di testo arbitrarie, descritti come segue:"],["dl",["dt",["code","-z \"$TXT\""]],["dd",["p","Valuta se la variabile ",["code","TXT"]," è vuota (dimensione zero)."]],["dt",["code","-n \"$TXT\""]," or ",["code","test \"$TXT\""]],["dd",["p","Valuta se la variabile ",["code","TXT"]," non è vuota."]],["dt",["code","\"$TXT1\" = \"$TXT2\""]," o ",["code","\"$TXT1\" == \"$TXT2\""]],["dd",["p","Valuta se ",["code","TXT1"]," e ",["code","TXT2"]," sono uguali."]],["dt",["code","\"$TXT1\" != \"$TXT2\""]],["dd",["p","Valuta se ",["code","TXT1"]," e ",["code","TXT2"]," non sono uguali."]],["dt",["code","\"$TXT1\" < \"$TXT2\""]],["dd",["p","Valuta se ",["code","TXT1"]," viene prima di ",["code","TXT2"],", in ordine alfabetico."]],["dt",["code","\"$TXT1\" > \"$TXT2\""]],["dd",["p","Valuta se ",["code","TXT1"]," viene dopo ",["code","TXT2"],", in ordine alfabetico."]]],["p","Lingue diverse possono avere regole diverse per l’ordine alfabetico. Per ottenere risultati coerenti, indipendentemente dalle impostazioni di localizzazione del sistema in cui viene eseguito lo script, si consiglia di impostare la variabile d’ambiente ",["code","LANG"]," su ",["code","C"],", come in ",["code","LANG=C"],", prima di eseguire operazioni che implicano l’ordine alfabetico . Questa definizione manterrà anche i messaggi di sistema nella lingua originale, quindi dovrebbe essere utilizzata solo nell’ambito dello script."],["p","I confronti numerici hanno il proprio set di opzioni di test:"],["dl",["dt",["code","$NUM1 -lt $NUM2"]],["dd",["p","Valuta se ",["code","NUM1"]," è minore di ",["code","NUM2"],"."]],["dt",["code","$NUM1 -gt $NUM2"]],["dd",["p","Valuta se ",["code","NUM1"]," è maggiore di ",["code","NUM2"],"."]],["dt",["code","$NUM1 -le $NUM2"]],["dd",["p","Valuta se ",["code","NUM1"]," è minore o uguale a ",["code","NUM2"],"."]],["dt",["code","$NUM1 -ge $NUM2"]],["dd",["p","Valuta se ",["code","NUM1"]," è maggiore o uguale a ",["code","NUM2"],"."]],["dt",["code","$NUM1 -eq $NUM2"]],["dd",["p","Valuta se ",["code","NUM1"]," è uguale a ",["code","NUM2"],"."]],["dt",["code","$NUM1 -ne $NUM2"]],["dd",["p","Valuta se ",["code","NUM1"]," non è uguale a ",["code","NUM2"],"."]]],["p","Tutti i test possono ricevere i seguenti modificatori:"],["dl",["dt",["code","! EXPR"]],["dd",["p","Valuta se l’espressione ",["code","EXPR"]," è falsa."]],["dt",["code","EXPR1 -a EXPR2"]],["dd",["p","Valuta se sia ",["code","EXPR1"]," che ",["code","EXPR2"]," sono veri."]],["dt",["code","EXPR1 -o EXPR2"]],["dd",["p","Valuta se almeno una delle due espressioni è vera."]]],["p","Un altro costrutto condizionale, ",["code","case"],", può essere visto come una variazione del costrutto ",["em","if"],". L’istruzione ",["code","case"]," eseguirà un elenco di comandi dati se un elemento specificato — il contenuto di una variabile, per esempio — può essere trovato in un elenco di elementi separati da ",["em","pipes"]," e terminato da ",["code",")"],". Il seguente script di esempio mostra come il costrutto ",["code","case"]," pussa essere usato per indicare il formato di pacchettizzazione del software corrispondente per una data distribuzione Linux:"],["pre","#!/bin/bash\n\nDISTRO=$1\n\necho -n \"Distribution $DISTRO uses \"\ncase \"$DISTRO\" in\n\tdebian | ubuntu | mint)\n    echo -n \"the DEB\"\n  ;;\n\tcentos | fedora | opensuse )\n    echo -n \"the RPM\"\n  ;;\n\t*)\n    echo -n \"an unknown\"\n  ;;\nesac\necho \" package format.\""],["p","Ogni elenco di pattern e comandi associati deve terminare con ",["code",";;"],", ",["code",";&"],", o ",["code",";;&"],". L’ultimo pattern, un asterisco, corrisponderà se nessun altro pattern precedente corrispondeva in precedenza. L’istruzione ",["code","esac"]," (",["em","case"]," al contrario) termina il costrutto ",["code","case"],". Supponendo che lo script di esempio precedente fosse chiamato ",["code","script.sh"]," e che venga eseguito su ",["em","OpenSuse"]," come primo argomento, verrà generato il seguente output:"],["pre","$ ",["strong","./script.sh opensuse"],"\nDistribution opensuse uses the RPM package format."],["note","Suggerimento",["p","Bash ha un’opzione chiamata ",["code","nocasematch"]," che abilita il ",["em","pattern matching"]," senza distinzione tra maiuscole e minuscole per il costrutto ",["code","case"]," e altri comandi condizionali. Il comando integrato ",["code","shopt"]," alterna i valori delle impostazioni che controllano il comportamento opzionale della shell: ",["code","shopt -s"]," abiliterà (",["em","set"],") l’opzione data e ",["code","shopt -u"]," disabiliterà (",["em","unset"],") l’opzione data. Pertanto, posizionare ",["code","shopt -s nocasematch"]," prima del costrutto case abiliterà la corrispondenza dei modelli senza distinzione tra maiuscole e minuscole. Le opzioni modificate da ",["code","shopt"]," influenzeranno solo la sessione corrente, quindi le opzioni modificate all’interno di script in esecuzione in una sub-shell — che è il modo standard per eseguire uno script — non influenzano le opzioni della sessione ",["em","parent"],"."]],["p","L’elemento ricercato e gli schemi subiscono l’espansione della tilde (",["code","~"],"), l’espansione dei parametri, la sostituzione dei comandi e l’espansione aritmetica. Se l’elemento cercato è specificato tra virgolette, verranno rimossi prima che venga tentata la corrispondenza."],["h3","Costrutti di Loop"],["p","Gli script vengono spesso utilizzati come strumento per automatizzare attività ripetitive, eseguendo lo stesso set di comandi fino a quando non viene verificato un criterio di interruzione. Bash ha tre istruzioni di ciclo — ",["code","for"],", ",["code","until"]," e ",["code","while"]," — progettate per specifici costrutti di loop."],["p","Il costrutto ",["code","for"]," percorre un dato elenco di elementi — di solito un elenco di parole o qualsiasi altro segmento di testo separato da spazi — eseguendo lo stesso insieme di comandi su ciascuno di quegli elementi. Prima di ogni iterazione, l’istruzione ",["code","for"]," assegna l’elemento corrente a una variabile, che può quindi essere utilizzata dai comandi inclusi. Il processo viene ripetuto fino a quando non ci sono più elementi rimasti. La sintassi del costrutto ",["code","for"]," è:"],["pre","for VARNAME in LIST\ndo\n\tCOMMANDS\ndone"],["p",["code","VARNAME"]," è un nome di variabile di shell arbitrario e ",["code","LIST"]," è una qualsiasi sequenza di termini separati. I caratteri di delimitazione validi che dividono gli elementi nell’elenco sono definiti dalla variabile d’ambiente ",["code","IFS"],", e sono i caratteri ",["em","space"],", ",["em","tab"]," e ",["em","newline"]," per impostazione predefinita. L’elenco dei comandi da eseguire è delimitato dalle istruzioni ",["code","do"]," e ",["code","done"],", quindi i comandi possono occupare tutte le righe necessarie."],["p","Nell’esempio seguente, il comando ",["code","for"]," prenderà ogni elemento dall’elenco fornito — una sequenza di numeri — e lo assegnerà alla variabile ",["code","NUM"],", un elemento alla volta:"],["pre","#!/bin/bash\n\nfor NUM in 1 1 2 3 5 8 13\ndo\n\techo -n \"$NUM is \"\n\tif [ $(( $NUM % 2 )) -ne 0 ]\n\tthen\n\t\techo \"odd.\"\n\telse\n\t\techo \"even.\"\n  fi\ndone"],["p","Nell’esempio, un costrutto ",["code","if"]," nidificato viene utilizzato insieme a un’espressione aritmetica per valutare se il numero nella variabile ",["code","NUM"]," corrente è pari o dispari. Supponendo che lo script di esempio precedente sia denominato ",["code","script.sh"]," e si trovi nella directory corrente, verrà generato il seguente output:"],["pre","$ ",["strong","./script.sh"],"\n1 is odd.\n1 is odd.\n2 is even.\n3 is odd.\n5 is odd.\n8 is even.\n13 is odd."],["p","Bash supporta anche un formato alternativo ai costrutti ",["code","for"],", con la notazione delle doppie parentesi. Questa notazione ricorda la sintassi dell’istruzione ",["code","for"]," del linguaggio di programmazione C ed è particolarmente utile per lavorare con gli ",["em","array"],":"],["pre","#!/bin/bash\n\nSEQ=( 1 1 2 3 5 8 13 )\n\nfor (( IDX = 0; IDX < ${#SEQ[*]}; IDX++ ))\ndo\n\techo -n \"${SEQ[$IDX]} is \"\n\tif [ $(( ${SEQ[$IDX]} % 2 )) -ne 0 ]\n\tthen\n\t\techo \"odd.\"\n\telse\n\t\techo \"even.\"\n  fi\ndone"],["p","Questo script di esempio genererà lo stesso identico output dell’esempio precedente. Tuttavia, invece di usare la variabile ",["code","NUM"]," per memorizzare un elemento alla volta, la variabile ",["code","IDX"]," viene impiegata per tracciare l’indice dell’array corrente in ordine crescente, partendo da 0 e aggiungendo continuamente ad esso il numero di elementi nell’array ",["code","SEQ"],". L’elemento effettivo viene recuperato dalla sua posizione nell’array con ",["code","${SEQ[$IDX]}"],"."],["p","Allo stesso modo, il costrutto ",["code","until"]," esegue una sequenza di comandi fino a quando un comando di test — come il comando ",["code","test"]," stesso — termina con lo stato 0 (successo). Per esempio, la stessa struttura di loop dell’esempio precedente può essere implementata con ",["code","until"]," come segue:"],["pre","#!/bin/bash\n\nSEQ=( 1 1 2 3 5 8 13 )\n\nIDX=0\n\nuntil [ $IDX -eq ${#SEQ[*]} ]\ndo\n\techo -n \"${SEQ[$IDX]} is \"\n\tif [ $(( ${SEQ[$IDX]} % 2 )) -ne 0 ]\n\tthen\n\t\techo \"odd.\"\n\telse\n\t\techo \"even.\"\n  fi\n  IDX=$(( $IDX + 1 ))\ndone"],["p","Il costrutto ",["code","until"]," può richiedere più istruzioni rispetto ai costrutti ",["code","for"],", ma può essere più adatto a criteri di arresto non numerici forniti dalle espressioni ",["code","test"]," o da qualsiasi altro comando. È importante includere azioni che assicurino un criterio di arresto valido, come l’incremento di una variabile contatore, altrimenti il ciclo potrebbe essere eseguito indefinitamente."],["p","L’istruzione ",["code","while"]," è simile all’istruzione ",["code","until"],", ma ",["code","while"]," continua a ripetere l’insieme di comandi se il comando di test termina con lo stato 0 (successo). Pertanto, l’istruzione ",["code","until [ $IDX -eq ${#SEQ[*]} ]"]," dell’esempio precedente è equivalente a ",["code","while [ $IDX -lt ${#SEQ[*]} ]"],", come ciclo che dovrebbe ripetersi mentre l’indice dell’array è ",["em","minore del"]," il totale degli elementi nell’array."],["h3","Un Esempio più Elaborato"],["p","Immagina che un utente desideri sincronizzare periodicamente una raccolta dei propri file e directory con un altro dispositivo di archiviazione, montato in un punto di montaggio arbitrario nel filesystem, e che un sistema di backup completo sia considerato eccessivo. Poiché si tratta di un’attività che deve essere eseguita periodicamente, uno script di shell è una buon candidato per una simile automazione."],["p","Il compito è semplice: sincronizzare ogni file e directory contenuto in un elenco, da una directory di origine come primo argomento dello script a una directory di destinazione come secondo argomento dello script. Per semplificare l’aggiunta o la rimozione di elementi dall’elenco, verrà conservato in un file separato, ",["code","~/sync.list"],", un elemento per riga:"],["pre","$ ",["strong","cat ~/.sync.list"],"\nDocuments\nTo do\nWork\nFamily Album\n.config\n.ssh\n.bash_profile\n.vimrc"],["p","Il file contiene una combinazione di file e directory, alcuni con spazi vuoti nei nomi. Questo è uno scenario adatto per il comando Bash ",["em","builtin"]," ",["code","mapfile"],", che analizzerà qualsiasi contenuto di testo e creerà una variabile di array da esso, posizionando ogni riga come un singolo elemento di array. Il file di script sarà chiamato ",["code","sync.sh"],", contenente il seguente codice:"],["pre","#!/bin/bash\n\nset -ef\n\n# List of items to sync\nFILE=~/.sync.list\n\n# Origin directory\nFROM=$1\n\n# Destination directory\nTO=$2\n\n# Check if both directories are valid\nif [ ! -d \"$FROM\" -o ! -d \"$TO\" ]\nthen\n  echo Usage:\n  echo \"$0 <SOURCEDIR> <DESTDIR>\"\n  exit 1\nfi\n\n# Create array from file\nmapfile -t LIST < $FILE\n\n# Sync items\nfor (( IDX = 0; IDX < ${#LIST[*]}; IDX++ ))\ndo\n\techo -e \"$FROM/${LIST[$IDX]} \\u2192 $TO/${LIST[$IDX]}\";\n\trsync -qa --delete \"$FROM/${LIST[$IDX]}\" \"$TO\";\ndone"],["p","La prima azione che lo script esegue è ridefinire due parametri della shell con il comando ",["code","set"],": l’opzione ",["code","-e"]," fa terminare immediatamente l’esecuzione se un comando esce con uno stato diverso da zero e l’opzione ",["code","-f"]," disabilita il ",["em","globbing"]," del nome del file. Entrambe le opzioni possono essere abbreviate come ",["code","-ef"],". Questo non è un passaggio obbligatorio, ma aiuta a diminuire la probabilità di comportamenti imprevisti."],["p","Le istruzioni effettive orientate all’applicazione del file di script possono essere suddivise in tre parti:"],["ol",["li",["p",["em","Raccoglie e controlla i parametri dello script"]],"  ",["p","La variabile ",["code","FILE"]," è il percorso del file contenente l’elenco degli elementi da copiare: ",["code","~/.sync.list"],". Le variabili ",["code","FROM"]," e ",["code","TO"]," sono rispettivamente i percorsi di origine e di destinazione. Poiché questi ultimi due parametri sono forniti dall’utente, passano attraverso un semplice test di convalida eseguito dal costrutto ",["code","if"],": se uno dei due non è una directory valida, valutato dal test ",["code","[ ! -d \"$FROM\" -o ! -d \"$TO\" ]"],", lo script mostrerà un breve messaggio di aiuto e poi terminerà con uno stato di uscita di 1."]],["li",["p",["em","Carica l’elenco di file e directory"]],"  ",["p","Dopo che tutti i parametri sono stati definiti, viene creato un array contenente l’elenco degli elementi da copiare con il comando ",["code","mapfile -t LIST < $FILE"],". L’opzione ",["code","-t"]," di ",["code","mapfile"]," rimuoverà il carattere di nuova riga finale da ogni riga prima di includerlo nella variabile array denominata ",["code","LIST"],". Il contenuto del file indicato dalla variabile ",["code","FILE"]," — ",["code","~/.sync.list"]," — viene letto tramite il reindirizzamento dell’input."]],["li",["p",["em","Esegue la copia e informa l’utente"]],"  ",["p","Un ciclo ",["code","for"]," che utilizza la notazione con doppie parentesi attraversa l’array di elementi, con la variabile ",["code","IDX"]," che tiene traccia dell’incremento dell’indice. Il comando ",["code","echo"]," informerà l’utente di ogni elemento che viene copiato. Il carattere Unicode di escape — ",["code","\\u2192"]," — per il carattere ",["em","freccia destra"]," è presente nel messaggio di output, quindi deve essere utilizzata l’opzione ",["code","-e"]," del comando ",["code","echo"],". Il comando ",["code","rsync"]," copierà selettivamente solo i file modificati dall’origine, quindi il suo utilizzo è raccomandato per tali attività. Le opzioni ",["code","rsync"]," ",["code","-q"]," e ",["code","-a"],", condensate in ",["code","-qa"],", inibiranno i messaggi ",["code","rsync"]," e attiveranno la modalità ",["em","archive"],", dove vengono preservate tutte le proprietà dei file. L’opzione ",["code","--delete"]," farà in modo che ",["code","rsync"]," cancelli un elemento nella destinazione che non esiste più nell’origine, quindi dovrebbe essere usato con attenzione."]]],["p","Supponendo che tutti gli elementi nell’elenco esistano nella directory home dell’utente ",["code","carol"],", ",["code","/home/carol"],", e la directory di destinazione ",["code","/media/carol/backup"]," punta a un dispositivo di archiviazione esterno montato, il comando ",["code","sync. sh /home/carol /media/carol/backup"]," genererà il seguente output:"],["pre","$ ",["strong","sync.sh /home/carol /media/carol/backup"],"\n/home/carol/Documents → /media/carol/backup/Documents\n/home/carol/\"To do\" → /media/carol/backup/\"To do\"\n/home/carol/Work → /media/carol/backup/Work\n/home/carol/\"Family Album\" → /media/carol/backup/\"Family Album\"\n/home/carol/.config → /media/carol/backup/.config\n/home/carol/.ssh → /media/carol/backup/.ssh\n/home/carol/.bash_profile → /media/carol/backup/.bash_profile\n/home/carol/.vimrc → /media/carol/backup/.vimrc"],["p","L’esempio presuppone anche che lo script venga eseguito da root o dall’utente ",["code","carol"],", poiché la maggior parte dei file sarebbe illeggibile da altri utenti. Se ",["code","script.sh"]," non è all’interno di una directory elencata nella variabile d’ambiente ",["code","PATH"],", allora dovrebbe essere specificato con il suo percorso completo."],["h2","Esercizi Guidati"],["ol",["li",["p","Come potrebbe essere usato il comando ",["code","test"]," per verificare se il percorso del file memorizzato nella variabile ",["code","FROM"]," è più recente di un file il cui percorso è memorizzato nella variabile ",["code","TO"],"?"]," ",["table",["tr",["td"]]]],["li",["p","Il seguente script dovrebbe stampare una sequenza numerica da 0 a 9, ma invece stampa indefinitamente 0. Cosa si dovrebbe fare per ottenere l’output atteso?"],"   ",["pre","#!/bin/bash\n\nCOUNTER=0\n\nwhile [ $COUNTER -lt 10 ]\ndo\n  echo $COUNTER\ndone"],"   ",["table",["tr",["td"]]]],["li",["p","Supponiamo che un utente abbia scritto uno script che genera un elenco ordinato di nomi utente. L’elenco ordinato risultante viene presentato come il seguente sul suo computer:"],"   ",["pre","carol\nDave\nemma\nFrank\nGrace\nhenry"],"    ",["p","Tuttavia, lo stesso elenco è ordinato come segue sul computer del suo collega:"],"    ",["pre","Dave\nFrank\nGrace\ncarol\nemma\nhenry"],"    ",["p","Cosa potrebbe spiegare le differenze tra i due elenchi ordinati?"],"  ",["table",["tr",["td"]]]]],["h2","Esercizi Esplorativi"],["ol",["li",["p","Come possono essere usati tutti gli argomenti della riga di comando dello script per inizializzare un array Bash?"]," ",["table",["tr",["td"]]]],["li",["p","Perché, controintuitivamente, il comando ",["code","test 1 > 2"]," viene valutato come vero?"]," ",["table",["tr",["td"]]]],["li",["p","In che modo un utente potrebbe cambiare temporaneamente il separatore di campo predefinito solo con il carattere di nuova riga, pur essendo ancora in grado di ripristinarlo al suo contenuto originale?"]," ",["table",["tr",["td"]]]]],["h2","Sommario"],["p","Questa lezione dà uno sguardo più approfondito ai test disponibili del comando ",["code","test"]," e ad altri costrutti condizionali e di ciclo, necessari per scrivere script di shell più elaborati. Un semplice script di sincronizzazione dei file viene fornito come esempio di una pratica applicazione di script di shell. La lezione segue i seguenti passaggi:"],["ul",["li",["p","Test estesi per i costrutti condizionali ",["code","if"]," e ",["code","case"],"."]],["li",["p","Costrutti di loop della shell: ",["code","for"],", ",["code","until"]," e ",["code","while"],"."]],["li",["p","Iterazione attraverso array e parametri."]]],["p","I comandi e le procedure affrontati sono stati:"],["dl",["dt",["code","test"]],["dd",["p","Esegue un confronto tra gli elementi forniti al comando."]],["dt",["code","if"]],["dd",["p","Un costrutto logico utilizzato negli script per valutare qualcosa come vero o falso, quindi l’esecuzione del comando successivo in base ai risultati."]],["dt",["code","case"]],["dd",["p","Valuta diversi valori rispetto a una singola variabile. L’esecuzione del comando script viene quindi eseguita a seconda del risultato del comando ",["code","case"],"."]],["dt",["code","for"]],["dd",["p","Ripete l’esecuzione di un comando in base a un dato criterio."]],["dt",["code","until"]],["dd",["p","Ripete l’esecuzione di un comando finché un’espressione non restituisce false."]],["dt",["code","while"]],["dd",["p","Ripete l’esecuzione di un comando mentre una data espressione restituisce true."]]],["h2","Risposte agli Esercizi Guidati"],["ol",["li",["p","Come potrebbe essere usato il comando ",["code","test"]," per verificare se il percorso del file memorizzato nella variabile ",["code","FROM"]," è più recente di un file il cui percorso è memorizzato nella variabile ",["code","TO"],"?"],"  ",["p","Il comando ",["code","test \"$FROM\" -nt \"$TO\""]," restituirà un codice di stato 0 se il file nella variabile ",["code","FROM"]," è più recente del file nella variabile ",["code","TO"],"."]],["li",["p","Il seguente script dovrebbe stampare una sequenza numerica da 0 a 9, ma invece stampa indefinitamente 0. Cosa si dovrebbe fare per ottenere l’output atteso?"],"   ",["pre","#!/bin/bash\n\nCOUNTER=0\n\nwhile [ $COUNTER -lt 10 ]\ndo\n  echo $COUNTER\ndone"],"    ",["p","La variabile ",["code","COUNTER"]," dovrebbe essere incrementata, cosa che potrebbe essere eseguita con l’espressione aritmetica ",["code","COUNTER=$(( $COUNTER + 1 ))"],", per raggiungere i criteri di stop e terminare il ciclo."]],["li",["p","Supponiamo che un utente abbia scritto uno script che genera un elenco ordinato di nomi utente. L’elenco ordinato risultante viene presentato come il seguente sul suo computer:"],"   ",["pre","carol\nDave\nemma\nFrank\nGrace\nhenry"],"    ",["p","Tuttavia, lo stesso elenco è ordinato come segue sul computer del suo collega:"],"    ",["pre","Dave\nFrank\nGrace\ncarol\nemma\nhenry"],"    ",["p","Cosa potrebbe spiegare le differenze tra i due elenchi ordinati?"],"   ",["p","L’ordinamento è basato sulle impostazioni internazionali del sistema corrente. Per evitare incongruenze, le attività di ordinamento dovrebbero essere eseguite con la variabile d’ambiente ",["code","LANG"]," impostata su ",["code","C"],"."],"    ",["pre"," [[sec.105.2_02-AEE]]\n== Risposte agli Esercizi Esplorativi"]],["li",["p","Come possono essere usati tutti gli argomenti della riga di comando dello script per inizializzare un array Bash?"],"  ",["p","I comandi ",["code","PARAMS=( $* )"]," o ",["code","PARAMS=( \"$@\" )"]," creeranno un array chiamato ",["code","PARAMS"]," con tutti gli argomenti."]],["li",["p","Perché, controintuitivamente, il comando ",["code","test 1 > 2"]," viene valutato come vero?"],"  ",["p","L’operatore ",["code",">"]," deve essere utilizzato con i test di stringa, non con i test numerici."]],["li",["p","In che modo un utente potrebbe cambiare temporaneamente il separatore di campo predefinito solo con il carattere di nuova riga, pur essendo ancora in grado di ripristinarlo al suo contenuto originale?"],"  ",["p","Una copia della variabile ",["code","IFS"]," può essere memorizzata in un’altra variabile: ",["code","OLDIFS=$IFS"],". Quindi il nuovo separatore di riga è definito con ",["code","IFS=$'\\n'"]," e la variabile IFS può essere ripristinata con ",["code","IFS=$OLDIFS"],"."]]]]}];
